
/* Competências e Rotas de Aprendizagem — Linha Dirigente e ramos (Escoteiros do Brasil).
   Chave de cada atividade marcada: <ramo>-<nível>-<competência>-<índice>; itens do PPF usam <ramo>-<nível>-<competência>-p-<índice> e não entram na contagem. */
window.FORMACAO = (function () {
  var CAT = {"lob":{"n":"Lobinho","g":[{"t":"Competências essenciais","c":[{"x":0,"n":"Gestão de Mudanças","l":[{"d":"Demonstra disposição de aprender formas diferentes de fazer as coisas","g":[["Comportamentos desejados",["Aceita outras formas de fazer as coisas.","Mantém uma atitude positiva quando tem que mudar de ideia, conceitos, tarefas ou funções.","Busca informações sobre as mudanças e obtém informações que permita compreende-las."]],["Atividades de desenvolvimento",["Ler o documento “Características Essenciais do Movimento Escoteiro “ e debater com seu APF as impressões sobre o documento.","Ler o capítulo “História do Escotismo”, do livro “Escotistas em ação - Ramo Lobinho”."]]],"r":["Os voluntários lidam de maneira receptiva com as mudanças da organização."]},{"d":"Analisa e implementa ações para a gestão de mudanças","g":[["Comportamentos desejados",["Aplica procedimentos de maneira flexível quando as circunstâncias exigem.","Toma decisões de maneira autonoma como resposta a situações de transformação.","É criativo e inovador no desempenho de suas funções."]],["Atividades de desenvolvimento",["Trabalhar junto com sua equipe ações que promovam a inovação em rotinas de sua função."]]],"r":["Os fluxos e processos da estrutura são constantemente revisados e aprimorados."]},{"d":"Avalia e projeta ações de mudança na estrutura em que atua","g":[["Comportamentos desejados",["Antecipa riscos emergentes e aproveita oportunidades para satisfazer as necessidades futuras.","Modifica procedimentos padronizados em resposta a ambientes em transformação.","Cria novos modelos e metodologias organizacionais em resposta a novos contextos, condições e situações."]],["Atividades de desenvolvimento",["Organizar ações de melhoria e desenvolvimento contínuo na estrutura em que atua, tais como projetos, campanhas de comunicação e inovações em processos."]],["Inclua no seu PPF",["Promover em seu grupo uma discussão sobre alguma nova publicação ou resolução da UEB lançadas no último ano.","Propor alguma alteração ou adequação de procedimento no seu nível de atuação visando atender às transformações do ambiente.","Identificar uma nova situação e propor um plano de implantação para as mudanças sugeridas, ressaltando os controles que devem ser tidos para evitar os antigos hábitos.","Desenvolver pesquisas sobre o uso de novas tecnologias na metodologia organizacional.","Organizar ações de melhoria e desenvolvimento contínuo na estrutura em que atua, tais como projetos, campanhas de comunicação e inovações em processos."]]],"r":["Em momentos de mudança, os voluntários já se sentem preparados para adaptarem-se e promoverem as ações necessárias para a sua implantação."]}]},{"x":1,"n":"Aprendizagem Permanente e Desenvolvimento Pessoal","l":[{"d":"Expressa interesse e comprometimento com sua capacitação para a função que exerce","g":[["Comportamentos desejados",["Observa e aprende com os demais.","Participa de cursos, módulos e outras iniciativas de formação inerentes ao seu cargo ou função.","Como voluntário, buscar esclarecer suas dúvidas em relação ao desempenho de sua função com o APF."]],["Atividades de desenvolvimento",["Em conjunto com o APF, preparar o seu Plano Pessoal de Formação.","Participar satisfatoriamente do Curso Preliminar.","Ler e discutir com o APF a descrição do Cargo de Assessor Pessoal de Formação."]]],"r":["Os voluntários são comprometidos com seus processos de atualização.","Os adultos da U.E.L. tem APFs nomeados pela Diretoria da Estrutura."]},{"d":"Analisa os resultados de sua aprendizagem e compartilha seus conhecimentos e experiências com os demais","g":[["Comportamentos desejados",["Atua como agente promotor de novas ideias e tecnologias.","Motiva os demais na participação em processos de melhoria contínua, ajudando no desenvolvimento de suas tarefas e crescimento pessoal","Aplica ao seu trabalho novas aprendizagens que enriquecem suas ações"]],["Atividades de desenvolvimento",["Realizar a revisão de seu PPF.","Participar satisfatoriamente do Curso Básico.","Ler o Guia do Chefe Escoteiro de Baden-Powell.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função.","Participar do curso em EAD sobre Assessor Pessoal de Formação ou outra iniciativa sobre o tema."]]],"r":["Os voluntários da estrutura compartilham informações sobre suas experiências de formação.","Os voluntários da estrutura aplicam novos conceitos às ações empregadas."]},{"d":"Avalia seus próprios resultados e realiza ações para melhorar seu desempenho continuamente","g":[["Comportamentos desejados",["Analisa seus próprios resultados e estabelece planos de ações para sua melhora.","Aproveita as mudanças organizacionais como oportunidades para desenvolver novos conhecimentos e habilidades.","Utiliza suas próprias experiências como aprendizados que compartiilha abertamente com os demais."]],["Atividades de desenvolvimento",["Realizar a revisão do seu PPF,","Organizar ações para que os demais voluntários participem de iniciativas de formação e atualização.","Participar satisfatoriamente do Curso Avançado.","Conversar com o seu Assessor Pessoal de Formação sobre a História da Insígnia de Madeira e Gilwell Park.","Ler a Politica Nacional de Adultos no Movimento Escoteiro.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função."]],["Inclua no seu PPF",["Fazer anotações pessoais e avaliar se as atividades planejadas foram cumpridas e se as propostas foram realizadas, identificando oportunidades de autodesenvolvimento.","Fazer um levantamento dos projetos que estão sendo realizados pela UEB, que possam ser agregados como metodologia de desenvolvimento e melhoria no nível em que atua.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função.","Promover um debate junto ao nível em que atua sobre as atualizações propostas pela União dos Escoteiros do Brasil, vinculando as experiências vividas e desenvolvidas no último ano.","Desenvolver e manter um arquivo pessoal com projetos realizados e resgatá-los com os ajustes sempre que necessário."]]],"r":["Os voluntários promovem momentos de autoavaliação e compartilhamento de impressões sobre seu próprio desenvolvimento, gerando um clima de aprendizado contínuo."]}]},{"x":2,"n":"Compromisso","l":[{"d":"Aceita voluntariamente os fundamentos do Escotismo e cumpre suas tarefas com responsabilidade","g":[["Comportamentos desejados",["Vincula o propósito, os princípios, os valores e a missão do Movimento Escoteiro às suas atividades cotidianas.","Assume como próprios o propósito, os princípios, os valores e a missão do Movimento Escoteiro.","Atua de acordo com a orientação espiritual dos Escoteiros do Brasil no exercício de sua função."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 1 do P.O.R.","Conversar com seu APF, identificando os quatro itens que compõem os fundamentos do Escotismo (definição, propósito, princípios e método).","Realizar sua Promessa Escoteira.","Ler o capítulo 3 do P.O.R. - orientação espiritual."]]],"r":["As responsabillidades são distribuídas e cumpridas de maneira adequada."]},{"d":"Assume voluntariamente novas responsabilidades adicionais a correspondente ao seu cargo, atuando de acordo com os fundamentos do Escotismo","g":[["Comportamentos desejados",["Compartilha o significado do propósito, dos princípios, dos valores e da missão do Movimento Escoteiro a ambientes exteriores aos da organização.","Assessora e guia os demais na realização de suas tarefas.","Dar andamento aos seus compromissos e reconhecer as ações que deve implementar para seu cumprimento."]],["Atividades de desenvolvimento",["Organizar/Participar com a equipe de adultos da estrutura, de grupos de debates sobre as diversas funções existentes no Movimento Escoteiro.","Organizar/Participar de ações de captação de novos adultos para o Movimento Escoteiro.","Ler o Projeto Educativo da União dos Escoteiros do Brasil"]]],"r":["Os voluntários compartilham os valores do Movimento Escoteiro em ambientes externos à organização.","Os voluntários recebem a orientação e o suporte necessários para a implementação do propósito, princípio, valores e missão do Movimento Escoteiro."]},{"d":"Implementa ações para promover o compromisso de outros adultos dos Escoteiros do Brasil aos fundamentos do Escotismo","g":[["Comportamentos desejados",["Gera espaços que fomentem a iniciativa e responsabilidades em momentos críticos.","É disciplinado e consciente no uso de recursos para o cumprimento de suas ações.","Dedica uma porcentagem de seu tempo a revisão dos planos de trabalho, objetivos e sua contribuição nestas tarefas."]],["Atividades de desenvolvimento",["Ler o Manual de Reconhecimento dos Escoteiros do Brasil."]],["Inclua no seu PPF",["Elaborar uma forma de dividir tarefas promovendo a avaliação de situações vividas pelo grupo e diferentes formas de se abordar momentos críticos.","Desenvolver propostas e métodos para melhoria na execução do planejamento das atividades no tocante ao uso de recursos.","Organizar com a equipe de adultos da estrutura, de grupos de debates sobre o uso de recursos para o cumprimento de ações.","Apresentar a revisão crítica de planos de trabalho executados nos últimos 6 meses, buscando apresentar sugestões de melhorias.","Apresentar um cronograma de desenvolvimento de ações futuras, evitando o acúmulo de atividades a serem realizadas."]]],"r":["Os voluntários são devidamente reconhecidos pelo seu compromisso e comprometimento.","São organizados momentos para revisão dos planos de trabalho e discussão sobre a distribuição de tarefas entre os voluntários."]}]},{"x":3,"n":"Consciência Organizacional","l":[{"d":"Identifica as estruturas da organização, especialmente o funcionamento e os objetivos do nível em que atua","g":[["Comportamentos desejados",["Conhece a história e os avanços mais relevantes da organização.","Conhece e identifica a estrutura da organização nos níveis local e regional.","Conhece os direitos e deveres inerentes ao seu cargo/função."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 5 do título 2 do Estatuto da União dos Escoteiros do Brasil e o Capítulo 5 do P.O.R."]]],"r":["Os voluntários conhecem a estrutura do nível que atuam e suas competências."]},{"d":"Desenvolve ações para a promoção de maior sentido de unidade e propósito comum nas ações da estrutura em que atua","g":[["Comportamentos desejados",["Implementa procedimentos organizacionais para a resolução de problemas.","Aplica os princípios de governança dentro da instituição.","Promove permanentemente as práticas democráticas e o respeito às diferenças."]],["Atividades de desenvolvimento",["Promover as políticas organizacionais dos Escoteiros do Brasil em grupos de debate e discussões, juntamente com a equipe da qual faz parte.","Ler o Estatuto dos Escoteiros do Brasil.","Participar de eventos distritais, regionais ou nacionais."]]],"r":["Os processos de escolha e renovação de lideranças estão de acordo com as recomendações das Políticas e orientações da Organização Mundial do Movimento Escoteiro.","São promovidas práticas de exercício da democracia e respeito às diferenças na estrutura."]},{"d":"Avalia e implementa ações para a conscientização de voluntários sobre a importância da estrutura institucional do Movimento Escoteiro","g":[["Comportamentos desejados",["Promove o sentido de unidade e propósito comum entre os diferentes níveis da Organização.","Compreende o impacto da sociedade civil, governo, setor privado, terceiro setor e outros grupos de interesse externos no cumprimento da missão da Organização.","Conhece a estrutura do Escotismo Mundial."]],["Atividades de desenvolvimento",["Explicar aos demais voluntários as relações entre as estruturas e níveis da organização.","Participar de uma assembleia regional ou nacional.","Ler as resoluções do CAN e DEN e debater com o APF ou grupo de discussão sobre os documentos."]],["Inclua no seu PPF",["Promover dentro do nível em que atua um debate sobre os diferentes níveis institucionais da União dos Escoteiros do Brasil, buscando compreender a atuação de cada um.","Promover as políticas organizacionais dos Escoteiros do Brasil em grupos de debate e discussões, juntamente com a equipe da qual faz parte.","Conhecer as propostas atuais sobre voluntariado definidas pelo Sistema público e terceiro setor, avaliar as necessidades de adaptação do nível em que atua.","Propor ações em parcerias com outras ONGS, entidades privadas e governamentais, visando o cumprimento da missão de nossa organização.","Apresentar aos membros do nível em que atua uma pesquisa sobre a estrutura do escotismo mundial, resumindo pelo menos uma política regional ou mundial."]]],"r":["Os voluntários têm a compreensão da importância das estruturas da organização e promovem boas práticas e o diálogo entre elas.","Os voluntários têm a compreensão da importância da boa relação que o Movimento Escoteiro deve ter com as demais instituições."]}]},{"x":4,"n":"Planejamento Estratégico","l":[{"d":"Identifica as responsabilidades e objetivos da função que desempenha","g":[["Comportamentos desejados",["Atua de acordo com as funções atribuidas a seu cargo, com a tarefa que lhe é designada.","Conhece o plano de trabalho da equipe da qual faz parte.","Solicita a assessoria necessária para o estabelecimento de planos de trabalho referentes a sua função."]],["Atividades de desenvolvimento",["Assinar o acordo de trabalho voluntário contendo a descrição das funções pertinentes ao cargo ao qual está designado."]]],"r":["Os voluntários da estrutura compartilham as responsabilidades necessárias para o desenvolvimento das atividades."]},{"d":"Planeja atividades e tarefas inerentes ao seu cargo ou função","g":[["Comportamentos desejados",["Formula planos de ação, considerando os objetivos de longo prazo, as metas e os planos da organização.","Presta assessoria em função dos planos de trabalho a curto, médio e longo prazo.","Estabelece pontos de controle, gerando dados e informações para o acompanhamento dos objetivos e prazos."]],["Atividades de desenvolvimento",["Ler o documento “Perfis: cargos e funções”, do nível em que atua.","Participar da concepção do calendário de atividades da estrutura em que atua."]]],"r":["Os voluntários da estrutura trabalham na concepção e revisão de planos de trabalho, monitorando seus resultados."]},{"d":"Compreende como sua atuação contribui para o alcance dos objetivos do Planejamento Estratégico dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Avalia periodicamente os resultados considerando fatores internos e externos críticos para o cumprimento dos seus planos e atividades.","Desenvolve diagnósticos de seus resultados e toma medidas em correspondência com seus resultados.","Propõe ações de melhora aos planos estratégicos e de ação da estrutura que faz parte."]],["Atividades de desenvolvimento",["Ler o Planejamento Estratégico dos Escoteiros do Brasil.","Participar do planejamento da sua Unidade Escoteira Local, considerando os objetivos anuais da sua seção."]],["Inclua no seu PPF",["Realizar sessão de avaliação visando identificar a influência de fatores internos e externos e se o planejamento proposto está sendo realizado, verificando a necessidade de adequação.","Estudar ao menos uma ferramenta de diagnóstico e, a utilizando, apresentar um estudo sobre quais ações devo realizar na resolução de problemas e desenvolvimento de um projeto em andamento.","Analisar o plano estratégico do nível que atua propondo ações de melhoria.","Participar do planejamento da sua Unidade Escoteira Local, considerando os objetivos anuais do nível em que atua."]]],"r":["Os voluntários são devidamente reconhecidos pelo seu compromisso e comprometimento.","São organizados momentos para revisão dos planos de trabalho e discussão sobre a distribuição de tarefas entre os voluntários."]}]},{"x":5,"n":"Relações Interpessoais","l":[{"d":"Identifica quais são as condutas referenciais de cortesia, respeito e confiança desejadas aos adultos dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Trata os demais com respeito, aceita as diferenças de pensamento e expressão das emoções.","Interage socialmente com outros, seguindo as normas básicas de cortesia.","Refere-se em termos positivos aos demais e sobre o trabalho que realizam."]],["Atividades de desenvolvimento",["Ler e discutir com seu Assessor Pessoal de Formação a definição do Movimento Escoteiro - Regra 001 do P.O.R."]]],"r":["A relação entre os voluntários é respeitosa e baseada em ações de cortesia.","Existe uma cultura de respeito à diversidade."]},{"d":"Desenvolve ações favorecendo as boas relações de trabalho cooperativo entre os adultos, inclusive com os responsáveis dos jovens","g":[["Comportamentos desejados",["É coerente em suas ações e seus resultados.","Promove a participação dos integrantes da alcateia e o diálogo intergeracional.","Escuta pontos de vista dos demais e modificar sua própria perspectiva quando necessário."]],["Atividades de desenvolvimento",["Participar da organização de, pelo menos, um conselho de pais.","Participar de uma seção de avaliação sobre o seu próprio trabalho e receber as críticas de maneira aberta e construtiva."]]],"r":["Há envolvimento e preocupação por parte dos voluntários para que os conflitos existentes sejam mediados e solucionados."]},{"d":"Avalia sua relação com os demais e busca alternativas para fortalecê-las, baseadas em compreensão e flexibilidade","g":[["Comportamentos desejados",["Demonstra proatividade no momento de prestar apoio aos acontecimentos que requerem esforços integrados.","Sabe criticar ideias sem ofender pessoalmente quem as expressa.","Demonstra não tomar as palavras ou situações de maneira pessoal."]],["Atividades de desenvolvimento",["Planejar ações de integração entre pessoas e áreas de trabalho, promovendo o fortalecimento das relações","Prestar adequadamente avaliações sobre os componentes de sua equipe de trabalho"]],["Inclua no seu PPF",["Propor um projeto para a UEL que deva ser realizado com integração das diferentes equipes que a compõe.","Procurar desenvolver atividades com outras pessoas da UEL não membros da sua equipe, buscando um olhar diferenciado na dinâmica possibilitando o fortalecimento e a boa comunicação interna do nível em que atua.","Planejar atividades de integração entre as equipes ou a novos integrantes a sua equipe de atuação.","Identificar formas de escuta e reflexão antes de criticar outras pessoas da equipe ou da UEL","Planejar ações de integração entre pessoas e áreas de trabalho, promovendo o fortalecimento das relações.","Prestar adequadamente avaliações sobre os componentes de sua equipe de trabalho.","Promover um debate sobre empatia e comunicação não violenta.","Desenvolver uma metodologia para dar oportunidade de ouvir todos os membros da equipe antes de tomar decisões ou propor ações, levando em consideração que as soluções devem sempre estar voltadas para o interesse do grupo e não para os interesses individuais."]]],"r":["Os voluntários são pró-ativos na resolução de conflitos entre adultos da organização.","Os voluntários posicionam-se de maneira adequada e sensata, gerando um clima de confiança mútua."]}]},{"x":6,"n":"Trabalho em Equipe","l":[{"d":"Reafirma a importância do trabalho em equipe, cooperando com os participantes de seu grupo de trabalho","g":[["Comportamentos desejados",["Assume seu papel/tarefas designadas com responsabilidade.","Ajuda em outras tarefas além das quais é responsável, quando necessário.","Expressa-se em termos positivos a sua equipe."]],["Atividades de desenvolvimento",["Participar de, pelo menos, um Conselho de Chefes da Unidade Escoteira Local."]]],"r":["As tarefas/projetos são desenvolvidas coletivamente e seus resultados são compartilhados."]},{"d":"Desenvolve projetos e as competências da equipe de trabalho que compõe","g":[["Comportamentos desejados",["Conhece as fortalezas e pontos de melhoria dos integrantes da equipe.","Proporciona ou assegura o apoio necessário para o desenvolvimento da equipe.","Gera um clima de trabalho que promove o espírito e a cooperação da equipe com outras equipes."]],["Atividades de desenvolvimento",["Cumprir com as responsabilidades inerentes a sua função (Registro no PAXTU, acompanhamento da progressão pessoal, aplicação de jogo/atividade, realização de cerimônia, etc.)"]]],"r":["Os voluntários têm facilitado o apoio para o desenvolvimento de seus projetos mediante o trabalho em equipe.","A comunicação entre os voluntários da estrutura tem fluxos ágeis e definidos."]},{"d":"Avalia os resultados atingidos pela equipe de trabalho que compõe e estimula ações para sua melhoria.","g":[["Comportamentos desejados",["Avalia as fortalezas e pontos de melhoria da equipe e seus integrantes para propor ações de melhora.","Avalia abertamente sua própria participação e contribuição nos resultados da equipe.","Permite aos demais a participação na construção da visão dos resultados que se esperam pela equipe."]],["Atividades de desenvolvimento",["Avaliar as ações desenvolvidas pela sua equipe em reuniões periódicas, com a colaboração dos demais participantes da equipe."]],["Inclua no seu PPF",["Promover momentos de autoavaliação das ações e atuação da equipe perante as necessidades de um projeto em desenvolvimento, identificando as fortalezas e pontos de melhoria de cada membro da equipe.","Avaliar periodicamente com os membros do nível em que atua as ações realizadas e refletir sobre as causas do não cumprimento, identificando como posso melhor contribuir para os resultados da equipe.","Avaliar as ações desenvolvidas por você em reuniões periódicas, com a colaboração dos demais participantes da equipe.","Propor diferentes modos para que todos da equipe possam participar dos processos de construção e desenvolvimento de projetos, inclusive assumindo diferentes funções."]]],"r":["Os voluntários realizam processos de avaliação em equipe e propõem estratégias para suas ações."]}]}]},{"t":"Competências específicas","c":[{"x":7,"n":"Aplicação de Jogos e Canções","l":[{"d":"Identifica as características dos diferentes tipos de jogos e canções e os conduz de maneira adequada para a criação de um ambiente educativo","g":[["Comportamentos desejados",["Pesquisa sobre os diferentes tipos de jogos e canções existentes.","Entende os jogos e canções como recurso educativo.","Participa da aplicação de jogos e canções na seção."]],["Atividades de desenvolvimento",["Aplicar jogos e canções de maneira atraente, utilizando técnicas diversificadas."]]],"r":["As atividades são divertidas e os integrantes da alcateia gostam de estar presentes.","Os escotistas compreendem a importância dos jogos e canções na prática do Escotismo."]},{"d":"Organiza e aplica jogos educativos no Movimento Escoteiro","g":[["Comportamentos desejados",["Seleciona os jogos e canções adequados a faixa etária do ramo.","Sugere jogos e canções adequados aos diversos momentos e situações na alcateia.","Aplica jogos e canções corretamente e com entusiasmo."]],["Atividades de desenvolvimento",["Aplicar diferentes jogos (ativo, cooperativo, noturno, grande jogo etc.), em atividades da alcateia, explicando claramente suas regras.","Cantar diferentes canções junto com a alcateia.","Antes do curso básico, ler o capítulo 10 do Manual do Escotista do Ramo Lobinho."]]],"r":["Há a troca de informações sobre a realização de jogos e canções entre os escotistas.","Os jogos e canções são atraentes, progressivos e variados."]},{"d":"Cria e orienta a aplicação de jogos e atividades educativas em todas as áreas de desenvolvimento.","g":[["Comportamentos desejados",["Cria jogos e canções adequados à faixa etária do ramo.","Orienta sobre a aplicação de jogos e canções adequados aos diversos momentos e situações na Alcateia.","Administra seu próprio arquivo/acervo de jogos e canções e o compartilha com os demais integrantes da equipe de escotistas."]],["Atividades de desenvolvimento",["Criar diferentes jogos que contribuam em todas as áreas de desenvolvimento.","Colaborar com a atualização do arquivo de jogos da alcateia.","Identificar as características que contribuem para que os participantes da seção desenvolvam suas competências durante a aplicação de jogos e canções."]],["Inclua no seu PPF",["Participar de uma iniciativa de formação sobre criação de jogos e canções.","Fazer uma leitura de livros e manuais de jogos e canções aplicadas para crianças.","Aprimorar a criação de jogos e canções, selecionando atividades interessantes para aplicar na sua seção.","Promover na seção um momento de reflexão entre os escotistas sobre a aplicação de jogos e canções e como essa prática pode ser aperfeiçoada.","Ter uma conversa com o APF sobre que ferramentas podem ser utilizadas para a gestão e arquivo de Jogos e Canções Escoteiras."]]],"r":["Os adultos da equipe de escotistas recebem a orientação adequada para a criação e condução de jogos e canções.","Os jogos e canções são instrumentos que possibilitam a observação e a orientação educativa na alcateia."]}]},{"x":8,"n":"Condução de Cerimônias","l":[{"d":"Identifica as vozes de Comando na alcateia e conduz as cerimônias de abertura e encerramento das reuniões da seção","g":[["Comportamentos desejados",["Comunica-se com crianças utilizando vozes de comando corretamente.","Demonstra boa organização na preparação do local e dos materiais necessários para a realização das cerimonias da alcateia.","Transmite as informações com segurança quando coordena uma cerimônia."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, assistir aos vídeos da série “Como se Faz?”","Conduzir uma cerimônia de hasteamento/arriamento na seção.","Realizar uma entrega de Distintivo de Progressão/Especialidade/ Insígnia de Interesse Especial na seção.","Participar de um Grande Uivo na Seção."]]],"r":["As crianças atendem às orientações dos escotistas.","As cerimônias são significativas para seus participantes."]},{"d":"Conduz cerimônias Escoteiras de maneira adequada","g":[["Comportamentos desejados",["Conduz adequadamente o processo de passagem de ramos entre os integrantes da alcateia.","Compreende as cerimônias escoteiras como um momento educativo e inclusivo da prática do escotismo.","Compreende as cerimônias como um espaço educativo e inclusivo na prática do escotismo."]],["Atividades de desenvolvimento",["Ler o Manual de Cerimônias dos Escoteiros do Brasil e discutir com seu Assessor Pessoal de Formação.","Conduzir uma cerimônia de Promessa.","Realizar uma entrega de distintivo de progressão, Insígnia de Interesse Especial ou Distintivo Especial na seção.","Conduzir uma cerimônia de passagem de Ramo."]]],"r":["As cerimônias são adequadas, realizadas em momento oportuno, local apropriado e são estimulantes."]},{"d":"Orienta os demais integrantes da equipe quanto à realização de cerimônias, zelando pelo caráter educativo","g":[["Comportamentos desejados",["Conduz adequadamente o processo de passagem entre ramos dos integrantes da alcateia.","Orienta os demais adultos da seção na realização de cerimônias.","Compreende as cerimônias escoteiras como um momento educativo e inclusivo da prática do escotismo."]],["Atividades de desenvolvimento",["Orientar outro adulto na seção sobre a realização de uma cerimônia de Grande Uivo."]],["Inclua no seu PPF",["Participar de uma cerimônia de passagem em conjunto com outros escotistas e observar se a cerimônia guarda as características previstas no Manual de Cerimônias dos Escoteiros do Brasil.","Observar outros escotistas na aplicação de cerimônias e transmitir informações para que as realizem corretamente e com segurança.","Analisar as cerimônias realizadas na seção, e assim avaliar as congruências e eventuais divergências encontradas entre o que é aplicado em sua UEL e o proposto pelos Escoteiros do Brasil.","Observar a participação dos integrantes da seção nas cerimônias e relacionála com o desenvolvimento da progressão pessoal."]]],"r":["Os participantes da seção valorizam os momentos em que se reúnem para realizar cerimônias."]}]},{"x":9,"n":"Compreensão do Desenvolvimento de Crianças, Adolescentes e Jovens","l":[{"d":"Conhece as diferentes fases do desenvolvimento das crianças e identifica os elementos que compõem o sistema de progressão","g":[["Comportamentos desejados",["Compreende o Ramo Lobinho como uma fase de desenvolvimento das crianças.","Percebe que as atividades da alcateia são o espaço para o desenvolvimento global das crianças, favorecendo a vida em grupo.","Comunica-se adequadamente com as crianças da alcateia, orientando-as educativamente."]],["Atividades de desenvolvimento",["L er o capítulo 1 do Manual do Escotista do Ramo Lobinho.","Ler as regras 13, 53, 66, 84 e 102 do P.O.R."]]],"r":["A alcateia torna-se um espaço de crescimento pessoal para seus integrantes.","As atividades da seção estão adequadas à faixa etária de seus integrantes.","Há estímulo para o desenvolvimento do processo de autoconhecimento, aceitação e aprimoramento de características pessoais, o que favorece a vida em grupo."]},{"d":"Acompanha e registra as atividades de progressão pessoal realizadas pelos integrantes da seção sob sua orientação","g":[["Comportamentos desejados",["Realiza o registro no PAXTU das atividades realizadas pelas crianças que acompanha.","Conversa com as crianças sobre o desenvolvimento individual, orientando-as a respeito da progressão pessoal de cada uma delas.","Realiza o registro das conquistas das crianças no PAXTU, mantendo os dados atualizados"]],["Atividades de desenvolvimento",["Acompanhar, por pelo menos um ciclo de programa, a progressão.","Antes do curso básico, ler o capítulo 9 do Manual do Escotista do Ramo Lobinho.","Utilizar o aplicativo mAPPa como ferramenta para o acompanhamento da progressão pessoal."]]],"r":["A alcateia possui um mapa (ou outra forma) de registro da progressão pessoal de todos as crianças, disponível para a ciência dos escotistas, da diretoria do GE e dos pais.","As crianças sentem-se estimuladas em sua progressão pessoal."]},{"d":"Orienta os demais escotistas sobre o acompanhamento da progressão pessoal das crianças da alcateia","g":[["Comportamentos desejados",["Demonstra empatia diante situações apresentadas pelas crianças.","É capaz de dialogar e orientar as crianças sem ser diretivo.","Utiliza uma linguagem adequada na orientação às crianças."]],["Atividades de desenvolvimento",["Realizar a avaliação e o registro da progressão pessoal das crianças da seção.","Conversa com os outros integrantes da equipe de escotistas sobre o acompanhamento da progressão pessoal."]],["Inclua no seu PPF",["Participar ativamente do processo de avaliação da progressão pessoal dos integrantes da seção utilizando linguagem apropriada.","Participar de uma Roca de Conselho promovendo o bom diálogo entre os participantes, auxiliando nas avaliações necessárias."]]],"r":["Percebe-se o clima de confiança entre adultos e crianças."]}]},{"x":10,"n":"Segurança","l":[{"d":"Reconhece a importância da segurança nas atividades escoteiras, seguindo as orientações do P.O.R. nas atividades de seção","g":[["Comportamentos desejados",["Leva em conta, prioritariamente, os aspectos relacionados à segurança para organizar suas atividades.","Zela pela segurança dos lobinhos durante as atividades","Observa se todas as atividades da alcateia preservam prioritariamente as regras de segurança."]],["Atividades de desenvolvimento",["Antes do curso, ler o capítulo 14 do P.O.R. (Segurança nas atividades escoteiras).","Ler o capítulo 15 do P.O.R. (Política de Proteção Infantojuvenil)","Realizar o Curso de Proteção Infantojuvenil dos Escoteiros do Brasil.","Solicitar, formalmente, autorização do responsável pela U.E.L. e autorização dos pais ou responsáveis para realização de atividades fora da sede."]]],"r":["Os pais e/ou responsáveis confiam nos escotistas na realização de atividades da alcateia.","A alcateia realiza atividades estimulantes e notavelmente seguras.","A alcateia é modelo de zelo e cuidado com os jovens."]},{"d":"Age de maneira imediata em situações potenciais ou reais de risco à integridade física, abusos ou maus tratos","g":[["Comportamentos desejados",["Zela pelos procedimentos de segurança dos Escoteiros do Brasil, assim como conhecer a Política de Proteção Infantojuvenil, agindo conforme suas diretrizes.","Orienta os integrantes da seção sobre as regras de segurança dos Escoteiros do Brasil.","Promove a Política de Proteção Infantojuvenil dos Escoteiros do Brasil."]],["Atividades de desenvolvimento",["Organizar/participar junto com os demais adultos da Unidade Escoteira, de um debate sobre o capítulo 15 do P.O.R.","Organizar um plano de segurança para uma atividade de seção fora da sede.","Ensinar aos integrantes da seção os conteúdos relacionados aos primeiros socorros descritos no Programa Educativo do ramo.","Discutir com o APF os procedimentos a serem adotados em casos de suspeita de abuso."]]],"r":["A alcateia é um ambiente seguro e de confiança para os responsáveis e jovens."]},{"d":"Toma as devidas precauções em relação a aspectos legais envolvidos nas atividades escoteiras.","g":[["Comportamentos desejados",["Conhece suas responsabilidades e tem atitudes adequadas e educativas com os integrantes da seção.","É exemplo de conduta responsável.","Cumpre as recomendações da União dos Escoteiros do Brasil e respeita todas as determinações legais."]],["Atividades de desenvolvimento",["Ler o Estatuto da Criança e do Adolescente.","Antes do curso, ler o livro “Proteção da Criança e do Adolescente - Orientações sobre como Proteger e Previnir Abusos”.","Conduzir, em uma reunião de pais, uma conversa sobre prevenção a maus tratos e abusos."]],["Inclua no seu PPF",["Participar de um evento/ conversa sobre a política de Proteção Infantojuvenil dos Escoteiros do Brasil.","Conhecer as regras do POR sobre segurança.","Conhecer o livreto Padrões de Atividades Escoteiras.","Conhecer sobre a Política de segurança da OMME - Safe no Harm (a salvo do perigo).","Elaborar um formulário, ou revisar o formulário atual, da UEL para planejamento de atividades externas.","Debater com sua Seção a importância do Planejamento para atividades, destacando os pontos críticos de controle no que se refere a segurança de todos os participantes da atividade."]]],"r":["A alcateia é um espaço de confiança para os pais. A alcateia tem atividades seguras e que garantem a integridade de todos os seus participantes.","É exemplo no que diz respeito a atenção aos direitos dos crianças no ambiente escoteiro."]}]},{"x":11,"n":"Aplicação do Marco Simbólico","l":[{"d":"Identifica os elementos que compõem o marco simbólico do Ramo","g":[["Comportamentos desejados",["Identifica as características que contextualizam a utilização do marco simbólico nas atividades do ramo.","Solicita orientação aos demais escotistas sobre a aplicação do marco simbólico.","Observa a vivência do marco simbólico na seção, utilizando-o como referencial na sua percepção do dia a dia."]],["Atividades de desenvolvimento",["Ler o texto referente ao marco simbólico do Capítulo 3 do Manual do Escotista do Ramo Lobinho.","Participar, junto com a equipe de escotistas, da aplicação de uma atividade com base no marco simbólico do Ramo Lobinho.","Cantar com as crianças, músicas com o tema da vida na Jângal."]]],"r":["As atividades da alcateia tem caráter educativo e reúnem os símbolos do Ramo Lobinho e Método Escoteiro.","As atividades da alcateia são apoiadas no marco simbólico do Ramo Lobinho: “O livro da Jângal”.","As matilhas são designadas por cores, e a alcateia utiliza um Bastão Totem conforme estabelecido no P.O.R."]},{"d":"Orienta e incentiva a vivência do marco simbólico do Ramo Lobinho","g":[["Comportamentos desejados",["Contextualiza suas atividades, utilizando o marco simbólico do ramo, relacionando-o ao Programa Educativo.","Utiliza o marco simbólico, preocupando-se com suas ações e o impacto que ele gera entre os integrantes da alcateia","Utiliza elementos simbólicos no Ramo Lobinho."]],["Atividades de desenvolvimento",["Estimular os lobinhos na utilização dos distintivos de matilha e outros elementos simbólicos do ramo.","Ler o Livro da Jângal e discutir com o assessor pessoal de formação sua aplicação educativa.","Aplicar uma atividade com base no marco simbólico do ramo.","Contar para a alcateia uma história da Jângal."]]],"r":["As atividades na alcateia são ambientadas em um fundo de cena motivador, inspirado na obra “O Livro da Jângal”, de Rudyard Kipling.","A vida de grupo na alcateia revela a presença dos marcos simbólicos do Ramo Lobinho.","As crianças compreendem e assimilam os valores propostos pelo Escotismo por meio dos exemplos contidos nas condutas das personagens da Jângal."]},{"d":"Cria atividades inspiradas no marco simbólico e nos símbolos do Ramo","g":[["Comportamentos desejados",["Organiza atividades utilizando o marco simbólico do ramo, relacionando-o com o Programa Educativo.","Utiliza o marco simbólico, preocupando-se com suas ações e o impacto que ele gera entre os integrantes da Alcateia.","Utiliza elementos simbólicos no Ramo Lobinho."]],["Atividades de desenvolvimento",["Planejar e executar uma atividade para a alcateia, na qual se evidencie o marco simbólico.","Fazer uma dança da Jângal com a alcateia.","Incentivar a utilização pelos lobinhos do livro de caça na alcateia.","Colaborar na atualização das conquistas dos lobinhos no totem da alcateia."]],["Inclua no seu PPF",["Participar de uma conversa, sobre o marco simbólico do ramo e aplicar seus conceitos durante as atividades de seção.","Participar junto com a chefia de sua seção sobre uma reflexão sobre como estão aplicando o Marco Simbólico na seção, estudando as possíveis implementações para os próximos ciclos de programa."]]],"r":["Os lobinhos conhecem as danças da Jângal.","As crianças compreendem e assimilam os valores propostos pelo Escotismo a partir das vivências proporcionadas pelas atividades do ramo."]}]},{"x":12,"n":"Operação do Sistema de Especialidades e Insígnias","l":[{"d":"Identifica os elementos essenciais que compõem o sistema de especialidades e de Insígnias de Interesse Especial","g":[["Comportamentos desejados",["Conhece a literatura relacionada à conquista de Distintivos de Especialidades e Insígnias de Interesse Especial, orientando as crianças a terem contato com isso.","Participa de cerimônias de entrega de distintivos de especialidades e insígnias de interesse especial.","Orienta os integrantes da seção sobre o sistema de especialidades e insígnias de interesse especial."]],["Atividades de desenvolvimento",["Ler o Guia de Especialidades e das Insígnias de Interesse Especial e saber orientar sobre sua utilização.","Ler as regras 169, 170 e 171 do P.O.R."]]],"r":["Os escotistas conhecem os aspectos gerais e essenciais para a operação do sistema de especialidades e insígnias."]},{"d":"Aplica o Sistema de Especialidades e das Insígnias de Interesse Especial no Programa, incentivando sua conquista na alcateia","g":[["Comportamentos desejados",["Estimula as crianças a conquistarem Distintivos de Especialidade e insígnias de interesse especial.","Compreende as especialidades como uma busca pessoal da criança, de acordo com suas aptidões e interesses.","Auxilia na escolha de examinadores para a conquista de especialidades."]],["Atividades de desenvolvimento",["Realizar atividades que estimulem a conquista de especialidades entre as crianças.","Realizar uma atividade que estimule a conquista de alguma Insígnia de Interesse Especial do Ramo Lobinho.","Registrar a conquista de especialidades e insígnias das crianças que acompanha.","Preencher de maneira adequada os certificados de conquista de insígnias e especialidades."]]],"r":["As crianças desenvolvem especialidades em diversos ramos de conhecimento, de acordo com suas aptidões.","As crianças sentem-se estimuladas a conquistar especialidades e Insígnias de Interesse Especial.","As crianças conversam com seus responsáveis sobre a conquista de distintivos."]},{"d":"Administra adequadamente a conquista de especialidades e insígnias pelos componentes da seção","g":[["Comportamentos desejados",["Realiza o acompanhamento das crianças que estão em processo de conquista de especialidades e insígnias.","Registra de maneira adequada as especialidades e insígnias conquistadas pelas crianças.","Realiza a entrega dos certificados e distintivos em tempo e maneira adequados."]],["Atividades de desenvolvimento",["Organizar o mapeamento geral de conquistas de especialidades e insígnias dos integrantes da seção.","Orientar os demais escotistas sobre o panorama de conquistas de especialidades e insígnias dos integrantes da seção.","Em uma reunião de pais, apresentar o sistema de especialidades e insígnias."]],["Inclua no seu PPF",["Conversar com outro adulto sobre ferramentas para realização do acompanhamento de especialidades e utilizá-lo em seu dia a dia.","Verificar se o mAPPa está sendo utilizado pelos integrantes da seção e se os adultos estão conseguindo acessar e acompanhar a progressão pelo aplicativo.","Avaliar, junto ao seu APF, a forma que realizou as entregas de distintivo, durante as atividades da seção.","Avalia a entrega de distintivos de sua seção para verificar se estão de acordo com o proposto pelos Escoteiros do Brasil."]]],"r":["A documentação e os registros da seção são preservados de maneira adequada e segura.","As crianças são reconhecidas adequadamente e prontamente sobre suas conquistas."]}]},{"x":13,"n":"Envolvimento Comunitário","l":[{"d":"Descreve o conceito de envolvimento comunitário e as atividades propostas para o tema pelos Escoteiros do Brasil","g":[["Comportamentos desejados",["Conhece os materiais de referência para atividades comunitárias dos Escoteiros do Brasil.","Incentiva as crianças a realizarem e participarem de atividades de serviço à comunidade.","Participa da organização de atividades comunitárias dos Escoteiros do Brasil."]],["Atividades de desenvolvimento",["Ler a programação e as orientações de aplicação de uma edição do EducAção Escoteira e MUTCOM.","Participar de uma atividade comunitária juntamente com a alcateia."]]],"r":["As crianças compreendem a importância da realização de boas ações à comunidade.","A Unidade Escoteira Local faz-se presente na comunidade e busca reconhecimento por sua atuação."]},{"d":"Aplica e desenvolve atividades comunitárias, de acordo com as orientações dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Participa da organização de atividades comunitárias dos Escoteiros do Brasil.","Incentiva as crianças a realizarem e participarem de atividades de serviço à comunidade.","Explica aos demais adultos da estrutura a importância da realização de atividades comunitárias."]],["Atividades de desenvolvimento",["Estimular a participação da seção em um Mutirão Nacional de Ação Comunitária, EducAção Escoteira.","Organizar uma atividade relacionada ao envolvimento comunitário, além das citadas acima.","Ler a publicação “Escotismo e Comunidade” e discuti-la com seu assessor pessoal de formação.","Promover uma atividade que estimule os lobinhos a conquistarem a Insígnia da Boa Ação."]]],"r":["As crianças compreendem a importância da realização de atividades comunitárias.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço relevante para o desenvolvimento comunitário."]},{"d":"Avalia a participação da seção em atividades de envolvimento comunitário e busca pontos de melhoria para as próximas participações","g":[["Comportamentos desejados",["Avalia a organização de atividades comunitárias dos Escoteiros do Brasil na Unidade Escoteira Local.","Incentiva as crianças a realizarem e participarem de atividades de serviço à comunidade.","Identifica pontos de melhoria para a organização de novas atividades de envolvimento comunitário na Unidade Escoteira Local."]],["Atividades de desenvolvimento",["Realizar, junto à equipe de escotistas, uma reunião de avaliação das atividades relacionadas às práticas de envolvimento comunitário."]],["Inclua no seu PPF",["Organizar/participar de uma conversa de avaliação sobre as atividades de Envolvimento Comunitário com os outros adultos da seção.","Avaliar como foi a aplicação e envolvimento da sua seção no MUTCOM.","Promover uma atividade de serviço à comunidade na seção, incentivando a participação da alcateia, buscando orientação na diretoria da UEL.","Organizar/participar de uma conversa de avaliação sobre as atividades de envolvimento comunitário com os outros adultos da seção.","Em uma Reunião do Conselho de Pais da seção, avaliar as possibilidades de atividades comunitárias, mapeando as iniciativas propostas para aumentar o impacto das ações da Seção."]]],"r":["As crianças compreendem a importância da realização de atividades voltadas ao envolvimento comunitário.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço de referência em práticas de envolvimento comunitário."]}]},{"x":14,"n":"Desenvolvimento Sustentável","l":[{"d":"Descreve o conceito de desenvolvimento sustentável e as atividades propostas para o tema pelos Escoteiros do Brasil","g":[["Comportamentos desejados",["Conhece os materiais de referência para atividades de desenvolvimento sustentável dos Escoteiros do Brasil.","Incentiva as crianças a realizarem e participarem de atividades de desenvolvimento sustentável.","Conhece quais são os Objetivos do Desenvolvimento Sustentável."]],["Atividades de desenvolvimento",["Ler a programação e as orientações de aplicação de uma edição do MUTECO.","Participar de uma atividade relacionada ao desenvolvimento sustentável, juntamente com a alcateia."]]],"r":["As crianças compreendem a importância da realização de atividades que enfatizem as práticas para o desenvolvimento sustentável.","A Unidade Escoteira Local faz-se presente na comunidade e busca reconhecimento por sua atuação.","A Unidade Escoteira Local promove ações relacionadas aos pontos dos ODS."]},{"d":"Aplica e desenvolve atividades sobre desenvolvimento sustentável e meio ambiente de acordo com as orientações dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Participa da organização de atividades que enfatizem a prática de ações para o desenvolvimento sustentável.","Incentiva as crianças a realizarem e participarem de atividades voltadas ao desenvolvimento sustentável","Atualiza-se em relação à tendências e práticas sustentáveis."]],["Atividades de desenvolvimento",["Estimular a participação da seção em um Mutirão Nacional de Ação Ecológica.","Organizar uma atividade relacionada ao desenvolvimento sustentável, além da citada acima.","Estimular os integrantes da seção a conquistarem a Insígnia Mundial do Meio Ambiente."]]],"r":["As crianças compreendem a importância da realização de atividades comunitárias ligadas aos ODS.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço relevante para o desenvolvimento sustentável."]},{"d":"Avalia a participação da seção em atividades de desenvolvimento sustentável, buscando pontos de melhoria","g":[["Comportamentos desejados",["Avalia a organização de atividades dos Escoteiros do Brasil que enfatizem o desenvolvimento sustentável na Unidade Escoteira Local.","Incentiva as crianças a realizarem e participarem de atividades relacionadas ao desenvolvimento sustentável.","Identifica pontos e melhoria para a organização de novas atividades relacionadas ao desenvolvimento sustentável na Unidade Escoteira Local."]],["Atividades de desenvolvimento",["Realizar, junto à equipe de escotistas, uma reunião de avaliação das atividades relacionadas às práticas de desenvolvimento sustentável","Ler o documento “Educação para os Objetivos de Desenvolvimento Sustentável”, da Unesco, e aplicar uma atividade sobre os ODS, baseado em suas informações."]],["Inclua no seu PPF",["Organizar/participar de uma conversa de avaliação sobre as atividades de Desenvolvimento Sustentável com os outros adultos da seção.","Avaliar como foi a aplicação e envolvimento da sua seção no MUTECO.","Promover uma atividade sobre desenvolvimento sultentável na seção, incentivando a participação dos lobinhos, buscando a orientação da Direotria da UEL.","Organizar/participar de uma conversa de avaliação sobre as atividades de desenvolvimento sustentável com os outros adultos da seção.","Em uma Reunião do Conselho de Pais da seção, avaliar as possibilidades de atividades de desenvolvimento sustentável, mapeando as iniciativas propostas para aumentar o impacto das ações da seção."]]],"r":["Os integrantes da seção compreendem a relação entre os objetivos do desenvolvimento sustentável e suas formas de interação com o mundo que os cerca.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço de referência em práticas de desenvolvimento sustentável."]}]},{"x":15,"n":"Aplicação do Sistema de Equipes","l":[{"d":"Descreve os elementos que compõem o conceito de vida em equipe no Ramo","g":[["Comportamentos desejados",["Conhece os elementos essenciais que embasam os sistemas de equipe no ramo.","Colabora e incentiva o trabalho em equipe entre as crianças da seção.","Entende a alcateia como ambiente natural para o desenvolvimento das atividades do Ramo Lobinho."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 4 do Manual do Escotista do Ramo Lobinho."]]],"r":["A vida em equipe na alcateia acontece de acordo com os conceitos apresentados no Manual do Escotista do Ramo Lobinho."]},{"d":"Aplica o sistema de equipes na alcateia, de acordo com o Manual do Escotista do Ramo Lobinho","g":[["Comportamentos desejados",["Proporciona o ambiente necessário para o autodesenvolvimento das crianças da alcateia.","Atua educativamente na resolução de conflitos entre os integrantes da seção.","Realiza a ação educativa durante as Rocas de Conselho."]],["Atividades de desenvolvimento",["Organizar e executar uma Roca de Conselho junto com a alcateia.","Promover uma eleição de Primos e Segundos na alcateia."]]],"r":["Progressivamente, as crianças assumem responsabilidades nas atividades da seção e em suas vidas.","São realizadas Rocas de Conselho.","São realizadas eleições de primos e segundos na alcateia."]},{"d":"Orienta os demais escotistas na correta aplicação do sistema de equipes no Ramo Lobinho.","g":[["Comportamentos desejados",["Entende a alcateia como espaço natural para o desenvolvimento das atividades do Ramo Lobinho.","Proporciona o ambiente necessário para o autodesenvolvimento das crianças da alcateia.","Orienta os demais escotistas sobre as maneiras de aplicar o sistema de equipes no ramo."]],["Atividades de desenvolvimento",["Em um conselho de pais, apresentar as características do sistema de equipes na seção."]],["Inclua no seu PPF",["Participar de uma conversa sobre a vida em grupo no Ramo Lobinho e aplicar seus conceitos durante as atividades da seção.","Avaliar a atuação das matilhas refletindo no desenvolvimento de cada integrante."]]],"r":["Os escotistas recebem a orientação adequada sobre a aplicação do sistema de equipes na seção."]}]},{"x":16,"n":"Domínio do Programa Educativo","l":[{"d":"Identifica as seis áreas de desenvolvimento do Programa Educativo","g":[["Comportamentos desejados",["Participa junto dos demais escotistas da seção, da organização de atividades nas seis áreas de desenvolvimento.","Identifica quais são as seis áreas de desenvolvimento do Programa Educativo.","Colabora com o registro das atividades da seção."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 8 (Áreas de desenvolvimento), do Manual do Escotista do Ramo Lobinho.","Ler o livro “Escotistas em ação - Ramo Lobinho”.","Ler os capítulos 7 e 8 do P.O.R."]]],"r":["São realizadas na U.E.L. atividades nas seis áreas de desenvolvimento."]},{"d":"Aplica atividades atraentes, progressivas e variadas nas seis áreas de desenvolvimento, organizadas de acordo com a ênfase definida pelo Ciclo de Programa.","g":[["Comportamentos desejados",["Aplica atividades atraentes, progressivas e variadas no Ramo Lobinho, conforme definidas no ciclo de programa.","Pesquisa atividades relacionadas às áreas de desenvolvimento.","Orienta educativamente as crianças da seção no cumprimento das atividades do Programa Educativo"]],["Atividades de desenvolvimento",["Aplicar atividades em todas as áreas de desenvolvimento e registrá-las adequadamente.","Ler o Capítulo 11 (O Ciclo de Programa) do Manual do Escotista do Ramo Lobinho.","Contar uma história para a alcateia.","Participar ativamente de todas as fases do Ciclo de Programa.","Ensinar um trabalho manual para a alcateia."]]],"r":["As atividades fixas e variáveis consideram todas as áreas de desenvolvimento."]},{"d":"Avalia a aplicação das atividades do Programa Educativo e orienta os demais escotistas.","g":[["Comportamentos desejados",["Avalia as atividades organizadas na seção.","Orienta a realização de atividades relacionadas às áreas de desenvolvimento.","Orienta os demais integrantes da Alcateia sobre os processos de avaliação da progressão pessoal."]],["Atividades de desenvolvimento",["Conversar com o APF sobre os resultados da avaliações das atividades desenvolvidas e buscar novas ideias a partir dos pontos de melhoria identificados.","Ler a Politica Nacional de Programa Educativo."]],["Inclua no seu PPF",["Realizar, com seus pares, momentos de avaliação das diversas atividades da seção.","Rever com sua Equipe de trabalho se as atividades estão relacionadas às áreas de desenvolvimento e, se necessário, reler o capítulo do Manual do escotista que versa sobre o tema.","Realizar reuniões com sua Equipe de trabalho para orientá-los sobre os processos de avaliação da progressão pessoal na Alcateia.","Em uma reunião com sua equipe de trabalho, avaliar se todos os pontos do método escoteiro estão sendo trabalhados, fazendo eventuais sugestões de como melhorar a aplicação de algum dos pontos."]]],"r":["As atividades fixas e variáveis consideram todas as áreas de desenvolvimento.","A administração da seção está em dia e a documentação em ordem."]}]},{"x":17,"n":"Campismo e Vida ao Ar Livre","l":[{"d":"Reconhece a importância da vida ao ar livre para as atividades da alcateia","g":[["Comportamentos desejados",["Relaciona adequadamente a utilização de técnicas de campismo e vida ao ar livre a atividades educativas.","Colabora com os demais escotistas na promoção de atividades que contribuam para o aprendizado de técnicas de campo para as crianças.","Identifica adequadamente os materiais necessários para os diversos tipos de atividades de campismo e vida ao ar livre."]],["Atividades de desenvolvimento",["Ensinar para a alcateia: Nó Direito, Nó Direito Alceado, Nó de Correr, Nó de Aselha, Nó de Escota, Nó de Escota Alceado e Volta do Fiel.","Distribuir corretamente o material de acampamento em uma mochila e ensinar para a alcateia."]]],"r":["Os escotistas da seção valorizam a realização de acampamentos e atividades ao ar livre na seção.","São realizadas atividades ao ar livre na seção."]},{"d":"Seleciona e aplica técnicas de campismo adequadas às atividades do Programa Educativo do Ramo Lobinho.","g":[["Comportamentos desejados",["Aplica técnicas de campo e proporciona vivências educativas a partir destes recursos às crianças.","Planeja atividades que contribuam para o aprendizado de técnicas de campo para as crianças.","Orienta os integrantes da seção na realização de atividades e tarefas referentes ao campismo e à vida ao ar livre"]],["Atividades de desenvolvimento",["Ensinar aos integrantes da alcateia a preparação de uma fogueira simples e seus procedimentos de segurança.","Saber se orientar pelo Cruzeiro do Sul e pelo Sol, e ensinar aos integrantes da alcateia.","Montar um fogareiro e um lampião, utilizando-os de acordo com as normas de segurança em atividades.","Ensinar para a alcateia como montar uma barraca.","Ler o livro “Padrões de atividades escoteiras”."]]],"r":["Os integrantes da alcateia utilizam técnicas de campismo em seus acampamentos.","Os integrantes da alcateia participam com entusiasmo dos acampamentos e atividades ao ar livre.","Os integrantes da alcateia apresentam bom aproveitamento na realização das técnicas de campo previstas no Programa Educativo do ramo.","São realizadas atividades ao ar livre na seção."]},{"d":"Avalia a execução da prática de técnicas de campismo e vida ao ar livre e orienta sobre sua correta aplicação.","g":[["Comportamentos desejados",["Aplica técnicas de campo e proporciona vivências educativas, a partir destes recursos, às crianças.","Planeja atividades que contribuam para o aprendizado de técnicas de campo para as crianças.","Orienta os demais escotistas da equipe na execução de atividades ao ar livre e aplicação de técnicas de campismo."]],["Atividades de desenvolvimento",["Orientar os escotistas na correta aplicação de técnicas de campo e realização de atividades ao ar livre.","Coordenar na seção uma reunião de avaliação de uma atividade ao ar livre."]],["Inclua no seu PPF",["Participar de um módulo ou outro momento de capacitação a respeito de técnicas de campo, aplicando seus conceitos nas reuniões da seção.","Conversar com sua equipe de trabalho sobre o equilíbrio de atividades ao ar livre dentro dos ciclos de programas propostos.","Em uma reunião de pais, expor a importância de atividades ao ar livre para o Movimento escoteiro, destacando os benefícios que essa prática traz para o desenvolvimento dos jovens."]]],"r":["A equipe de escotistas recebe a orientação adequada para a aplicação de atividades ao ar livre.","As atividades ao ar livre são avaliadas e sua execução é constantemente aperfeiçoada."]}]},{"x":18,"n":"Organização de Atividades","l":[{"d":"Identifica os tipos de atividade (fixas e variáveis), planejando e executando reuniões semanais, gerando experiências educativas","g":[["Comportamentos desejados",["Participa dos encontros de planejamento das reuniões semanais, contribuindo com sugestões.","Dirige algumas atividades das reuniões semanais e apoia a realização das demais.","Reconhece pontos positivos e negativos durante a execução das atividades realizadas."]],["Atividades de desenvolvimento",["Ler o livro “Os primeiros meses de uma nova alcateia”.","Participar das reuniões da alcateia, contribuindo em seu planejamento, execução e avaliação."]]],"r":["As reuniões semanais são dinâmicas e animadas.","As reuniões semanais são organizadas e com materiais disponíveis e preparados previamente.","Há um bom índice de assiduidade nas reuniões semanais da alcateia"]},{"d":"Diferencia os cuidados de planejamento entre reuniões e atividades regulares fora da sede","g":[["Comportamentos desejados",["Cuida da organização das atividades fora da sede realizando todos os passos que garantam sua realização de maneira segura e educativa.","Compartilha previamente a programação das atividades com a equipe de escotistas.","Informa antecipadamente os participantes da seção e seus responsáveis sobre a realização de atividades fora da sede."]],["Atividades de desenvolvimento",["Responsabilizar-se pela organização de uma reunião especial da seção.","Participar da organização e da execução de uma Flor Vermelha.","Planejar um cardápio para um acampamento de seção.","Participar do planejamento de um acampamento ou acantonamento da seção.","Organizar uma excursão com a alcateia e participar da avaliação junto da equipe de escotistas.","Ler o livro “Fogo de Conselho”."]]],"r":["As atividades da seção são seguras e têm seu caráter educativo preservado.","As atividades fora da sede são organizadas e com materiais sempre disponíveis e preparados.","Há um bom índice de assiduidade nas atividades realizadas fora da sede."]},{"d":"Orienta os demais adultos sobre os tipos de atividade (fixas e variáveis), auxiliando- -os em sua execução e condução","g":[["Comportamentos desejados",["Avalia o planejamento e execução de atividades dentro e fora da sede, buscando pontos de melhoria para próximas atividades.","Orienta os demais escotistas da seção no planejamento e execução de atividades dentro e fora da sede.","Planeja atividades variadas, de acordo com a ênfase identificada durante a execução do ciclo de programa."]],["Atividades de desenvolvimento",["Realizar reuniões de avaliação das atividades junto à equipe de escotistas e discutir suas impressões sobre as atividades com o APF."]],["Inclua no seu PPF",["Preparar um plano de execução de atividades e tê-lo aprovado pela diretoria da UEL.","Realizar reuniões de avaliação e orientação dos demais escotistas quanto à realização de atividades ao ar livre.","Reavaliar, junto à sua equipe, o calendário de atividades e verificar se as atividades estão de acordo com a ênfase definida durante a preparação do ciclo de programa."]]],"r":["Os integrantes da alcateia participam com entusiasmo dos acampamentos e atividades ao ar livre.","São realizadas atividades ao ar livre na seção.","Os escotistas recebem orientação adequada para a realização de atividades de campismo e vida ao ar livre.","As atividades fora da sede são organizadas e com materiais sempre disponíveis e preparados.","Há um bom índice de assiduidade nas atividades realizadas fora da sede."]}]}]}]},"esc":{"n":"Escoteiro","g":[{"t":"Competências essenciais","c":[{"x":0,"n":"Gestão de Mudanças","l":[{"d":"Demonstra disposição de aprender formas diferentes de fazer as coisas","g":[["Comportamentos desejados",["Aceita outras formas de fazer as coisas.","Mantém uma atitude positiva quando tem que mudar de ideia, conceitos, tarefas ou funções.","Busca informações sobre as mudanças e obtém informações que permita compreende-las."]],["Atividades de desenvolvimento",["Ler o documento “Características Essenciais do Movimento Escoteiro “ e debater com seu APF as impressões sobre o documento.","Ler o capítulo “História do Escotismo”, do livro “Escotistas em ação - Ramo Escoteiro”."]]],"r":["Os voluntários lidam de maneira receptiva com as mudanças da organização."]},{"d":"Analisa e implementa ações para a gestão de mudanças","g":[["Comportamentos desejados",["Aplica procedimentos de maneira flexível quando as circunstâncias exigem.","Toma decisões de maneira autonoma como resposta a situações de transformação.","É criativo e inovador no desempenho de suas funções."]],["Atividades de desenvolvimento",["Trabalhar junto com sua equipe ações que promovam a inovação em rotinas de sua função."]]],"r":["Os fluxos e processos da estrutura são constantemente revisados e aprimorados."]},{"d":"Avalia e projeta ações de mudança na estrutura em que atua","g":[["Comportamentos desejados",["Antecipa riscos emergentes e aproveita oportunidades para satisfazer as necessidades futuras.","Modifica procedimentos padronizados em resposta a ambientes em transformação.","Cria novos modelos e metodologias organizacionais em resposta a novos contextos, condições e situações."]],["Atividades de desenvolvimento",["Organizar ações de melhoria e desenvolvimento contínuo na estrutura em que atua, tais como projetos, campanhas de comunicação e inovações em processos."]],["Inclua no seu PPF",["Promover em seu grupo uma discussão sobre alguma nova publicação ou resolução da UEB lançadas no último ano.","Propor alguma alteração ou adequação de procedimento no seu nível de atuação visando atender às transformações do ambiente.","Identificar uma nova situação e propor um plano de implantação para as mudanças sugeridas, ressaltando os controles que devem ser tidos para evitar os antigos hábitos.","Desenvolver pesquisas sobre o uso de novas tecnologias na metodologia organizacional.","Organizar ações de melhoria e desenvolvimento contínuo na estrutura em que atua, tais como projetos, campanhas de comunicação e inovações em processos."]]],"r":["Em momentos de mudança, os voluntários já se sentem preparados para adaptarem-se e promoverem as ações necessárias para a sua implantação."]}]},{"x":1,"n":"Aprendizagem e Desenvolvimento Pessoal","l":[{"d":"Expressa interesse e comprometimento com sua capacitação para a função que exerce","g":[["Comportamentos desejados",["Observa e aprende com os demais.","Participa de cursos, módulos e outras iniciativas de formação inerentes ao seu cargo ou função.","Como voluntário, busca esclarecer suas dúvidas em relação ao desempenho de sua função com o APF."]],["Atividades de desenvolvimento",["Em conjunto com o APF, preparar o seu Plano Pessoal de Formação.","Participar do Curso Preliminar.","Ler e discutir com o APF a descrição do Cargo de Assessor Pessoal de Formação."]]],"r":["Os voluntários são comprometidos com seus processos de atualização.","Os adultos da U.E.L. tem APFs nomeados pela Diretoria da Estrutura."]},{"d":"Analisa os resultados de sua aprendizagem e compartilha seus conhecimentos e experiências com os demais","g":[["Comportamentos desejados",["Atua como agente promotor de novas ideias e tecnologias.","Motiva os demais na participação em processos de melhoria contínua, ajudando no desenvolvimento de suas tarefas e crescimento pessoal","Aplica ao seu trabalho novas aprendizagens que enriquecem suas ações"]],["Atividades de desenvolvimento",["Realizar a revisão de seu PPF.","Participar do Curso Básico.","Ler o Guia do Chefe Escoteiro de Baden-Powell.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função.","Participar do curso em EAD sobre Assessor Pessoal de Formação ou outra iniciativa sobre o tema."]]],"r":["Os voluntários da estrutura compartilham informações sobre suas experiências de formação.","Os voluntários da estrutura aplicam novos conceitos às ações empregadas."]},{"d":"Avalia seus próprios resultados e realiza ações para melhorar seu desempenho continuamente","g":[["Comportamentos desejados",["Analisa seus próprios resultados e estabelece planos de ações para sua melhora.","Aproveita as mudanças organizacionais como oportunidades para desenvolver novos conhecimentos e habilidades.","Utiliza suas próprias experiências como aprendizados que compartiilha abertamente com os demais."]],["Atividades de desenvolvimento",["Realizar a revisão do seu PPF.","Organizar ações para que os demais voluntários participem de iniciativas de formação e atualização.","Participar do Curso Avançado.","Conversar com o seu APF sobre a História da Insígnia de Madeira e Gilwell Park.","Ler a Politica Nacional de Adultos no Movimento Escoteiro.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função."]],["Inclua no seu PPF",["Fazer anotações pessoais e avaliar se as atividades planejadas foram cumpridas e se as propostas foram realizadas, identificando oportunidades de autodesenvolvimento.","Fazer um levantamento dos projetos que estão sendo realizados pela UEB, que possam ser agregados como metodologia de desenvolvimento e melhoria no nível em que atua.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função.","Promover um debate junto ao nível em que atua sobre as atualizações propostas pela União dos Escoteiros do Brasil, vinculando as experiências vividas e desenvolvidas no último ano.","Desenvolver e manter um arquivo pessoal com projetos realizados e resgatá-los com os ajustes sempre que necessário."]]],"r":["Os voluntários promovem momentos de autoavaliação e compartilhamento de impressões sobre seu próprio desenvolvimento, gerando um clima de aprendizado contínuo."]}]},{"x":2,"n":"Compromisso","l":[{"d":"Aceita voluntariamente os fundamentos do Escotismo e cumpre suas tarefas com responsabilidade","g":[["Comportamentos desejados",["Vincula o propósito, os princípios, os valores e a missão do Movimento Escoteiro às suas atividades cotidianas.","Assume como próprios o propósito, os princípios, os valores e a missão do Movimento Escoteiro.","Atua de acordo com a orientação espiritual dos Escoteiros do Brasil no exercício de sua função."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 1 do P.O.R.","Conversar com seu APF, identificando os quatro itens que compõem os fundamentos do Escotismo (definição, propósito, princípios e método).","Realizar sua Promessa Escoteira.","Ler o capítulo 3 do P.O.R. - orientação espiritual."]]],"r":["As responsabillidades são distribuídas e cumpridas de maneira adequada."]},{"d":"Assume voluntariamente novas responsabilidades adicionais a correspondente ao seu cargo, atuando de acordo com os fundamentos do Escotismo","g":[["Comportamentos desejados",["Compartilha o significado do propósito, dos princípios, dos valores e da missão do Movimento Escoteiro a ambientes exteriores aos da organização","Assessora e guia os demais na realização de suas tarefas.","Da andamento aos seus compromissos e reconhece as ações que deve implementar para seu cumprimento."]],["Atividades de desenvolvimento",["Organizar/Participar com a equipe de adultos da estrutura, de grupos de debates sobre as diversas funções existentes no Movimento Escoteiro.","Organizar/Participar de ações de captação de novos adultos para o Movimento Escoteiro.","Ler o Projeto Educativo da União dos Escoteiros do Brasil"]]],"r":["Os voluntários compartilham os valores do Movimento Escoteiro em ambientes externos à organização.","Os voluntários recebem a orientação e o suporte necessários para a implementação do propósito, princípio, valores e missão do Movimento Escoteiro."]},{"d":"Implementa ações para promover o compromisso de outros adultos dos Escoteiros do Brasil aos fundamentos do Escotismo","g":[["Comportamentos desejados",["Gera espaços que fomentem a iniciativa e responsabilidades em momentos críticos.","É disciplinado e consciente no uso de recursos para o cumprimento de suas ações.","Dedica uma porcentagem de seu tempo a revisão dos planos de trabalho, objetivos e sua contribuição nestas tarefas."]],["Atividades de desenvolvimento",["Ler o Manual de Reconhecimento dos Escoteiros do Brasil."]],["Inclua no seu PPF",["Elaborar uma forma de dividir tarefas promovendo a avaliação de situações vividas pelo grupo e diferentes formas de se abordar momentos críticos.","Desenvolver propostas e métodos para melhoria na execução do planejamento das atividades no tocante ao uso de recursos.","Organizar com a equipe de adultos da estrutura, de grupos de debates sobre o uso de recursos para o cumprimento de ações.","Apresentar a revisão crítica de planos de trabalho executados nos últimos 6 meses, buscando apresentar sugestões de melhorias.","Apresentar um cronograma de desenvolvimento de ações futuras, evitando o acúmulo de atividades a serem realizadas."]]],"r":["Os voluntários são devidamente reconhecidos pelo seu compromisso e comprometimento.","São organizados momentos para revisão dos planos de trabalho e discussão sobre a distribuição de tarefas entre os voluntários."]}]},{"x":3,"n":"Consciência Organizacional","l":[{"d":"Identifica as estruturas da organização, especialmente o funcionamento e os objetivos do nível em que atua","g":[["Comportamentos desejados",["Conhece a história e os avanços mais relevantes da organização.","Conhece e identifica a estrutura da organização nos níveis local e regional.","Conhece os direitos e deveres inerentes ao seu cargo/função."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 5 do título 2 do Estatuto da União dos Escoteiros do Brasil e o Capítulo 5 do P.O.R."]]],"r":["Os voluntários conhecem a estrutura do nível que atuam e suas competências."]},{"d":"Desenvolve ações para a promoção de maior sentido de unidade e propósito comum nas ações da estrutura em que atua","g":[["Comportamentos desejados",["Implementa procedimentos organizacionais para a resolução de problemas.","Aplica os princípios de governança dentro da instituição.","Promove permanentemente as práticas democráticas e o respeito às diferenças."]],["Atividades de desenvolvimento",["Promover as políticas organizacionais dos Escoteiros do Brasil em grupos de debate e discussões, juntamente com a equipe da qual faz parte.","Ler o Estatuto dos Escoteiros do Brasil","Participar de eventos distritais, regionais ou nacionais."]]],"r":["Os processos de escolha e renovação de lideranças estão de acordo com as recomendações das Políticas e orientações da Organização Mundial do Movimento Escoteiro.","São promovidas práticas de exercício da democracia e respeito às diferenças na estrutura."]},{"d":"Avalia e implementa ações para a conscientização de voluntários sobre a importância da estrutura institucional do Movimento Escoteiro","g":[["Comportamentos desejados",["Promove o sentido de unidade e propósito comum entre os diferentes níveis da Organização.","Compreende o impacto da sociedade civil, governo, setor privado, terceiro setor e outros grupos de interesse externos no cumprimento da missão da Organização.","Conhece a estrutura do Escotismo Mundial."]],["Atividades de desenvolvimento",["Explicar aos demais voluntários as relações entre as estruturas e níveis da organização.","Participar de uma assembleia regional ou nacional.","Ler as resoluções do CAN e DEN e debater com o APF ou grupo de discussão sobre os documentos."]],["Inclua no seu PPF",["Promover dentro do nível em que atua um debate sobre os diferentes níveis institucionais da União dos Escoteiros do Brasil, buscando compreender a atuação de cada um.","Promover as políticas organizacionais dos Escoteiros do Brasil em grupos de debate e discussões, juntamente com a equipe da qual faz parte.","Conhecer as propostas atuais sobre voluntariado definidas pelo Sistema público e terceiro setor, avaliar as necessidades de adaptação do nível em que atua.","Propor ações em parcerias com outras ONGS, entidades privadas e governamentais, visando o cumprimento da missão de nossa organização.","Apresentar aos membros do nível em que atua uma pesquisa sobre a estrutura do escotismo mundial, resumindo pelo menos uma política regional ou mundial."]]],"r":["Os voluntários têm a compreensão da importância das estruturas da organização e promovem boas práticas e o diálogo entre elas.","Os voluntários têm a compreensão da importância da boa relação que o Movimento Escoteiro deve ter com as demais instituições."]}]},{"x":4,"n":"Planejamento Estratégico","l":[{"d":"Identifica as responsabilidades e objetivos da função que desempenha","g":[["Comportamentos desejados",["Atua de acordo com as funções atribuidas a seu cargo, com a tarefa que lhe é designada.","Conhece o plano de trabalho da equipe da qual faz parte.","Solicita a assessoria necessária para o estabelecimento de planos de trabalho referentes a sua função."]],["Atividades de desenvolvimento",["Assinar o acordo de trabalho voluntário contendo a descrição das funções pertinentes ao cargo ao qual está designado."]]],"r":["Os voluntários da estrutura compartilham as responsabilidades necessárias para o desenvolvimento das atividades."]},{"d":"Planeja atividades e tarefas inerentes ao seu cargo ou função","g":[["Comportamentos desejados",["Formula planos de ação, considerando os objetivos de longo prazo, as metas e os planos da organização.","Presta assessoria em função dos planos de trabalho a curto, médio e longo prazo.","Estabelece pontos de controle, gerando dados e informações para o acompanhamento dos objetivos e prazos."]],["Atividades de desenvolvimento",["Ler o documento “Perfis: cargos e funções”, do nível em que atua.","Participar da concepção do calendário de atividades da estrutura em que atua."]]],"r":["Os voluntários da estrutura trabalham na concepção e revisão de planos de trabalho, monitorando seus resultados."]},{"d":"Compreende como sua atuação contribui para o alcance dos objetivos do Planejamento Estratégico dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Avalia periodicamente os resultados considerando fatores internos e externos críticos para o cumprimento dos seus planos e atividades.","Desenvolve diagnósticos de seus resultados e toma medidas em correspondência com seus resultados.","Propõe ações de melhora aos planos estratégicos e de ação da estrutura que faz parte."]],["Atividades de desenvolvimento",["Ler o Planejamento Estratégico dos Escoteiros do Brasil.","Participar do planejamento da sua Unidade Escoteira Local, considerando os objetivos anuais da sua seção."]],["Inclua no seu PPF",["Realizar sessão de avaliação visando identificar a influência de fatores internos e externos e se o planejamento proposto está sendo realizado, verificando a necessidade de adequação.","Estudar ao menos uma ferramenta de diagnóstico e, a utilizando, apresentar um estudo sobre quais ações devo realizar na resolução de problemas e desenvolvimento de um projeto em andamento.","Analisar o plano estratégico do nível que atua propondo ações de melhoria.","Participar do planejamento da sua Unidade Escoteira Local, considerando os objetivos anuais do nível em que atua."]]],"r":["Os voluntários são devidamente reconhecidos pelo seu compromisso e comprometimento.","São organizados momentos para revisão dos planos de trabalho e discussão sobre a distribuição de tarefas entre os voluntários."]}]},{"x":5,"n":"Relações Interpessoais","l":[{"d":"Identifica quais são as condutas referenciais de cortesia, respeito e confiança desejadas aos adultos dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Trata os demais com respeito, aceita as diferenças de pensamento e expressão das emoções.","Interage socialmente com outros, seguindo as normas básicas de cortesia.","Refere-se em termos positivos aos demais e sobre o trabalho que realizam."]],["Atividades de desenvolvimento",["Ler e discutir com seu Assessor Pessoal de Formação a definição do Movimento Escoteiro - Regra 001 do P.O.R."]]],"r":["A relação entre os voluntários é respeitosa e baseada em ações de cortesia.","Existe uma cultura de respeito à diversidade."]},{"d":"Desenvolve ações favorecendo as boas relações de trabalho cooperativo entre os adultos, inclusive com os responsáveis dos jovens","g":[["Comportamentos desejados",["É coerente em suas ações e seus resultados.","Promove a participação dos integrantes da tropa e o diálogo intergeracional.","Escuta pontos de vista dos demais e modifica sua própria perspectiva quando necessário."]],["Atividades de desenvolvimento",["Participar da organização de, pelo menos, um conselho de pais.","Participar de uma seção de avaliação sobre o seu próprio trabalho e receber as críticas de maneira aberta e construtiva."]]],"r":["Há envolvimento e preocupação por parte dos voluntários para que os conflitos existentes sejam mediados e solucionados."]},{"d":"Avalia sua relação com os demais e busca alternativas para fortalecê-las, baseadas em compreensão e flexibilidade","g":[["Comportamentos desejados",["Demonstra proatividade no momento de prestar apoio aos acontecimentos que requerem esforços integrados.","Sabe criticar ideias sem ofender pessoalmente quem as expressa.","Demonstra não tomar as palavras ou situações de maneira pessoal."]],["Atividades de desenvolvimento",["Planejar ações de integração entre pessoas e áreas de trabalho, promovendo o fortalecimento das relações","Prestar adequadamente avaliações sobre os componentes de sua equipe de trabalho"]],["Inclua no seu PPF",["Propor um projeto para a UEL que deva ser realizado com integração das diferentes equipes que a compõe.","Procurar desenvolver atividades com outras pessoas da UEL não membros da sua equipe, buscando um olhar diferenciado na dinâmica possibilitando o fortalecimento e a boa comunicação interna do nível em que atua.","Planejar atividades de integração entre as equipes ou a novos integrantes a sua equipe de atuação.","Identificar formas de escuta e reflexão antes de criticar outras pessoas da equipe ou da UEL","Planejar ações de integração entre pessoas e áreas de trabalho, promovendo o fortalecimento das relações.","Prestar adequadamente avaliações sobre os componentes de sua equipe de trabalho.","Promover um debate sobre empatia e comunicação não violenta.","Desenvolver uma metodologia para dar oportunidade de ouvir todos os membros da equipe antes de tomar decisões ou propor ações, levando em consideração que as soluções devem sempre estar voltadas para o interesse do grupo e não para os interesses individuais."]]],"r":["Os voluntários são pró-ativos na resolução de conflitos entre adultos da organização.","Os voluntários posicionam-se de maneira adequada e sensata, gerando um clima de confiança mútua."]}]},{"x":6,"n":"Trabalho em Equipe","l":[{"d":"Reafirma a importância do trabalho em equipe, cooperando com os participantes de seu grupo de trabalho","g":[["Comportamentos desejados",["Assume seu papel/tarefas designadas com responsabilidade.","Ajuda em outras tarefas além das quais é responsável, quando necessário.","Expressa-se em termos positivos a sua equipe."]],["Atividades de desenvolvimento",["Participar de, pelo menos, um Conselho de Chefes da Unidade Escoteira Local."]]],"r":["As tarefas/projetos são desenvolvidas coletivamente e seus resultados são compartilhados."]},{"d":"Desenvolve projetos e as competências da equipe de trabalho que compõe","g":[["Comportamentos desejados",["Conhece as fortalezas e pontos de melhoria dos integrantes da equipe.","Proporciona ou assegura o apoio necessário para o desenvolvimento da equipe.","Gera um clima de trabalho que promove o espírito e a cooperação da equipe com outras equipes."]],["Atividades de desenvolvimento",["Cumprir com as responsabilidades inerentes a sua função (Registro no PAXTU, acompanhamento da progressão pessoal, aplicação de jogo/atividade, realização de cerimônia, etc.)"]]],"r":["Os voluntários têm facilitado o apoio para o desenvolvimento de seus projetos mediante o trabalho em equipe.","A comunicação entre os voluntários da estrutura tem fluxos ágeis e definidos."]},{"d":"Avalia os resultados atingidos pela equipe de trabalho que compõe e estimula ações para sua melhoria","g":[["Comportamentos desejados",["Avalia as fortalezas e pontos de melhoria da equipe e seus integrantes para propor ações de melhora.","Avalia abertamente sua própria participação e contribuição nos resultados da equipe.","Permite aos demais a participação na construção da visão dos resultados que se esperam pela equipe."]],["Atividades de desenvolvimento",["Avaliar as ações desenvolvidas pela sua equipe em reuniões periódicas, com a colaboração dos demais participantes da equipe."]],["Inclua no seu PPF",["Promover momentos de autoavaliação das ações e atuação da equipe perante as necessidades de um projeto em desenvolvimento, identificando as fortalezas e pontos de melhoria de cada membro da equipe.","Avaliar periodicamente com os membros do nível em que atua as ações realizadas e refletir sobre as causas do não cumprimento, identificando como posso melhor contribuir para os resultados da equipe.","Avaliar as ações desenvolvidas por você em reuniões periódicas, com a colaboração dos demais participantes da equipe.","Propor diferentes modos para que todos da equipe possam participar dos processos de construção e desenvolvimento de projetos, inclusive assumindo diferentes funções."]]],"r":["Os voluntários realizam processos de avaliação em equipe e propõem estratégias para suas ações."]}]}]},{"t":"Competências específicas","c":[{"x":7,"n":"Aplicação de Jogos e Canções","l":[{"d":"Identifica as características dos diferentes tipos de jogos e canções e os conduz de maneira adequada para a criação de um ambiente educativo","g":[["Comportamentos desejados",["Pesquisa sobre os diferentes tipos de jogos e canções existentes.","Entende os jogos e canções como recurso educativo.","Participa da aplicação de jogos e canções na seção."]],["Atividades de desenvolvimento",["Aplicar jogos e canções de maneira atraente, utilizando técnicas diversificadas."]]],"r":["Os escotistas compreendem a importância dos jogos e das canções na prática do Escotismo.","Os jogos são oportunidades de avaliação do comportamento dos integrantes da tropa.","As canções são utilizadas na programação da seção, de forma a servirem como equalizador do ritmo da reunião, acalmando ou animando os jovens."]},{"d":"Organiza e aplica jogos educativos e canções no Movimento Escoteiro","g":[["Comportamentos desejados",["Seleciona jogos e canções adequados à faixa etária do ramo.","Sugere jogos e canções adequados aos diversos momentos e situações na tropa escoteira.","Aplica jogos e canções corretamente e com entusiasmo."]],["Atividades de desenvolvimento",["Aplicar diferentes jogos (ativo, cooperativo, noturno, grande jogo etc.), em atividades da tropa escoteira, orientando os monitores na utilização do Método Escoteiro.","Orientar os monitores para que cantem canções escoteiras junto com suas patrulhas.","Antes do curso básico, ler o capítulo 10 do Manual do Escotista do Ramo Escoteiro."]]],"r":["Há a troca de informações sobre a realização de jogos e canções entre os escotistas.","Os jogos e canções são atraentes, progressivos e variados."]},{"d":"Cria e orienta a aplicação de jogos e atividades educativas, em todas as áreas de desenvolvimento","g":[["Comportamentos desejados",["Cria jogos e canções adequados à faixa etária do ramo.","Orienta sobre a aplicação de jogos e canções adequados aos diversos momentos e situações na Tropa escoteira.","Administra seu próprio arquivo/acervo de jogos e canções e o compartilha com os demais integrantes da equipe de escotistas."]],["Atividades de desenvolvimento",["Criar e aplicar jogos que contribuam em cada área de desenvolvimento.","Colaborar com a atualização do arquivo de jogos da tropa escoteira.","Identificar as características que contribuem para que os participantes da seção desenvolvam suas competências durante a aplicação de jogos e canções.","Estimular e orientar para que os jovens apliquem jogos e canções."]],["Inclua no seu PPF",["Participar de uma iniciativa de formação sobre criação de jogos e canções.","Fazer uma leitura de livros e manuais de jogos e canções aplicadas para crianças.","Aprimorar a criação de jogos e canções, selecionando atividades interessantes para aplicar na sua seção.","Promover na seção um momento de reflexão entre os escotistas sobre a aplicação de jogos e canções e como essa prática pode ser aperfeiçoada.","Ter uma conversa com o APF sobre que ferramentas podem ser utilizadas para a gestão e arquivo de Jogos e Canções Escoteiras."]]],"r":["Os adultos da equipe de escotistas recebem a orientação adequada para a criação e condução de jogos e canções. Os jogos e canções são instrumentos que possibilitam a observação e a orientação educativa na tropa escoteira.","Tanto a tropa quanto as patrulhas utilizam canções no cotidiano de suas atividades, inclusive, criando paródias escoteiras."]}]},{"x":8,"n":"Condução de Cerimônias","l":[{"d":"Identifica as vozes de comando e sinais de apito na tropa escoteira e conduz as cerimônias de abertura e encerramento das reuniões de seção","g":[["Comportamentos desejados",["Comunica-se com adolescentes utilizando os sinais manuais, apitos e vozes de comando corretamente.","Demonstra boa organização na preparação do local e dos materiais necessários para a realização das cerimônias da tropa.","Transmite as informações com segurança quando coordena uma cerimônia."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, assistir aos vídeos da série “Como se Faz?”.","Aplicar sinais manuais e apitos de comando na seção.","Conduzir uma cerimônia de hasteamento ou arriamento de bandeira.","Realizar uma entrega de Distintivo de Progressão/Especialidade/ Insígnia de Interesse Especial na seção."]]],"r":["Os adolescentes atendem às orientações dos escotistas.","As cerimônias são significativas para seus participantes."]},{"d":"Conduz cerimônias escoteiras de maneira adequada","g":[["Comportamentos desejados",["Conduz adequadamente o processo de passagem entre ramos dos integrantes da tropa escoteira.","Compreende as cerimônias como um espaço educativo e inclusivo na prática do escotismo.","Compreende as cerimônias escoteiras como um momento educativo e inclusivo na prática do escotismo."]],["Atividades de desenvolvimento",["Conduzir uma cerimônia de Promessa Escoteira.","Realizar uma entrega de Distintivo de Progressão/Insígnia de Interesse Especial ou Distintivo de Lis de Ouro.","Ler o Manual de Cerimônias dos Escoteiros do Brasil e discutir com seu Assessor Pessoal de Formação.","Conduzir uma cerimônia de passagem de Ramo."]]],"r":["As cerimônias são adequadas, realizadas em momento oportuno, local apropriado e são estimulantes."]},{"d":"Orienta os demais integrantes da equipe quanto à realização de cerimônias, zelando pelo caráter educativo","g":[["Comportamentos desejados",["Conduz adequadamente o processo de passagem entre ramos dos integrantes da tropa escoteira.","Orienta os demais adultos da seção na realização de cerimônias.","Compreende as cerimônias escoteiras como um momento educativo e inclusivo da prática do escotismo."]],["Atividades de desenvolvimento",["Orientar outro adulto na realização de uma cerimônia de hasteamento/ arriamento."]],["Inclua no seu PPF",["Participar de uma cerimônia de passagem em conjunto com outros escotistas e observar se a cerimônia guarda as características previstas no Manual de Cerimônias dos Escoteiros do Brasil.","Observar outros escotistas na aplicação de cerimônias e transmitir informações para que as realizem corretamente e com segurança.","Analisar as cerimônias realizadas na seção, e assim avaliar as congruências e eventuais divergências encontradas entre o que é aplicado em sua UEL e o proposto pelos Escoteiros do Brasil.","Observar a participação dos integrantes da seção nas cerimônias e relacionála com o desenvolvimento da progressão pessoal."]]],"r":["Os participantes da seção valorizam os momentos em que se reúnem para realizar cerimônias."]}]},{"x":9,"n":"Compreensão sobre o Desenvolvimento de Crianças, Adolescentes e Jovens","l":[{"d":"Conhece as diferentes fases do desenvolvimento dos adolescentes e identifica os elementos que compõe o sistema de progressão","g":[["Comportamentos desejados",["Compreende o Ramo Escoteiro como uma fase de desenvolvimento dos adolescentes.","Percebe que as atividades da tropa são o espaço para o desenvolvimento global dos adolescentes, favorecendo o processo de desenvolvimento da autonomia.","Comunica-se adequadamente com os adolescentes da tropa escoteira, orientando-os educativamente."]],["Atividades de desenvolvimento",["Ler o capítulo 1 (Os Jovens de 11 a 14 anos) do Manual do Escotista do Ramo Escoteiro.","Ler as regras 13, 53, 66, 84 e 102 do P.O.R."]]],"r":["A tropa escoteira é um espaço de crescimento pessoal para seus integrantes.","As atividades da seção estão adequadas à faixa etária de seus integrantes.","Há estímulo para o desenvolvimento do processo de autoconhecimento, aceitação e aprimoramento de características pessoais, o que favorece a vida em grupo."]},{"d":"Acompanha e registra as atividades de progressão pessoal realizadas pelos integrantes da seção sob sua orientação","g":[["Comportamentos desejados",["Realiza o registro no PAXTU das atividades realizadas pelos adolescentes que acompanha.","Conversa com os adolescentes sobre o seu desenvolvimento e os orienta a respeito de sua progressão pessoal.","Realiza o registro das conquistas dos adolescentes no PAXTU e os mantém atualizados."]],["Atividades de desenvolvimento",["Acompanhar, por pelo menos um ciclo de programa, a progressão pessoal de alguns adolescentes da sua tropa escoteira.","Antes do curso básico, ler os capítulos 9 e 11 do Manual do Escotista do Ramo Escoteiro.","Utiliza o aplicativo mAPPa como ferramenta para acompanhamento da progressão pessoal."]]],"r":["A tropa escoteira possui um mapa (ou outra forma) de registro da progressão pessoal de todos os adolescentes, disponível para a ciência dos escotistas, da diretoria do GE e dos pais.","Os adolescentes sentem-se estimulados em sua progressão pessoal."]},{"d":"Orienta os demais escotistas sobre o acompanhamento da progressão pessoal dos adolescentes da tropa","g":[["Comportamentos desejados",["Demonstra empatia diante situações apresentadas pelas crianças.","É capaz de dialogar e orientar as crianças sem ser diretivo.","Utiliza uma linguagem adequada na orientação às crianças."]],["Atividades de desenvolvimento",["Realizar a avaliação e o registro da progressão pessoal dos adolescentes que acompanha.","Conversar com os outros integrantes da equipe de escotistas sobre o acompanhamento da progressão pessoal."]],["Inclua no seu PPF",["Participar ativamente do processo de avaliação da progressão pessoal dos integrantes da seção utilizando linguagem apropriada.","Participar de uma Corte de Honra promovendo o bom diálogo entre os participantes, auxiliando nas avaliações necessárias."]]],"r":["Percebe-se o clima de confiança entre adultos e adolescentes."]}]},{"x":10,"n":"Segurança","l":[{"d":"Reconhece a importância da segurança nas atividades escoteiras, seguindo as orientações do P.O.R. nas atividades de seção","g":[["Comportamentos desejados",["Leva em conta, prioritariamente, os aspectos relacionados à segurança para organizar suas atividades.","Zela pela segurança dos escoteiros durante as atividades da tropa.","Observa se todas as atividades da tropa preservam prioritariamente as regras de segurança."]],["Atividades de desenvolvimento",["Antes do curso preliminar ler o capítulo 14 do P.O.R. (segurança nas atividades escoteiras).","Ler o capítulo 15 do P.O.R. (Política de Proteção Infanto-Juvenil).","Realizar o Curso de Proteção Infanto-Juvenil dos Escoteiros do Brasil.","Solicitar, formalmente, autorização do responsável pela U.E.L. e autorização dos pais ou responsáveis para realizar atividade fora da sede."]]],"r":["Os pais e/ou responsáveis confiam nos escotistas na realização de atividades da tropa escoteira.","A tropa escoteira realiza atividades estimulantes e notavelmente seguras.","A tropa escoteira é modelo de zelo e cuidado com os jovens."]},{"d":"Age de maneira imediata em situações potenciais ou reais de abusos ou maus tratos","g":[["Comportamentos desejados",["Zela pelos procedimentos de segurança dos Escoteiros do Brasil, assim como conhece a Política de Proteção Infantojuvenil, agindo conforme suas diretrizes.","Orienta os integrantes da seção sobre as regras de segurança dos Escoteiros do Brasil.","Promove a Política de Proteção Infantojuvenil dos Escoteiros do Brasil."]],["Atividades de desenvolvimento",["Organizar/participar junto com os demais adultos da Unidade Escoteira, de um debate sobre o capítulo 15 do P.O.R.","Organizar um plano de segurança para uma atividade de seção fora da sede.","Ensinar aos integrantes da seção os conteúdos relacionados aos primeiros socorros descritos no Programa Educativo do ramo.","Discutir com o APF os procedimentos a serem adotados em casos de suspeita de abuso."]]],"r":["A tropa escoteira é um ambiente seguro e de confiança para os responsáveis e jovens."]},{"d":"Toma as devidas precauções com os aspectos legais envolvidos nas atividades escoteiras","g":[["Comportamentos desejados",["Conhece suas responsabilidades e tem atitudes adequadas e educativas com os integrantes da seção.","É exemplo de conduta responsável.","Cumpre as recomendações da União dos Escoteiros do Brasil e respeita todas as determinações legais."]],["Atividades de desenvolvimento",["Ler o Estatuto da Criança e do Adolescente.","Antes do curso, ler o livro “Proteção da Criança e do Adolescente - Orientações sobre como Proteger e Previnir Abusos - Manual para escotistas”.","Conduzir, em uma reunião de pais, uma conversa sobre prevenção a maus tratos e abusos."]],["Inclua no seu PPF",["Participar de um evento/ conversa sobre a política de Proteção Infantojuvenil dos Escoteiros do Brasil.","Conhecer as regras do POR sobre segurança.","Conhecer o livreto Padrões de Atividades Escoteiras.","Conhecer sobre a Política de segurança da OMME - Safe no Harm (a salvo do perigo).","Elaborar um formulário, ou revisar o formulário atual, da UEL para planejamento de atividades externas.","Debater com sua Seção a importância do Planejamento para atividades, destacando os pontos críticos de controle no que se refere a segurança de todos os participantes da atividade."]]],"r":["A tropa escoteira é um espaço de confiança para os pais.","A tropa escoteira tem atividades seguras e que garantem a integridade de todos os seus participantes.","A tropa é exemplo no que diz respeito à atenção aos direitos dos adolescentes no ambiente escoteiro."]}]},{"x":11,"n":"Aplicação do Marco Simbólico","l":[{"d":"Identifica os elementos que compõe o marco simbólico do Ramo","g":[["Comportamentos desejados",["Identifica as características que contextualizam a utilização do marco simbólico nas atividades do ramo.","Solicita orientação aos demais escotistas sobre a aplicação do marco simbólico.","Observa a vivência do marco simbólico na seção, utilizando-o como referencial na sua percepção do dia a dia."]],["Atividades de desenvolvimento",["Ler o texto referente ao marco simbólico do Capítulo 2 do Manual do Escotista do Ramo Escoteiro.","Participar, junto com a equipe de escotistas, da aplicação de uma atividade com base no Marco Simbólico do Ramo Escoteiro."]]],"r":["As atividades da tropa escoteira tem caráter educativo e reúnem os símbolos do Ramo Escoteiro e Método Escoteiro.","As atividades da tropa são apoiadas no marco simbólico do Ramo Escoteiro: “Explorar novos territórios com um grupo de amigos”","As patrulhas utilizam nome, bandeirola e distintivo, conforme estabelecido no P.O.R."]},{"d":"Orienta e incentiva a vivência do marco simbólico do Ramo Escoteiro","g":[["Comportamentos desejados",["Contextualiza suas atividades, utilizando o marco simbólico do ramo, relacionando-o ao Programa Educativo.","Utiliza o marco simbólico, preocupando-se com suas ações e o impacto que ele gera entre os integrantes da tropa escoteira.","Utiliza elementos simbólicos no Ramo Escoteiro."]],["Atividades de desenvolvimento",["Estimular a realização de atividades de patrulha com base no marco simbólico do ramo.","Aplicar uma atividade que enfatize o Marco Simbólico do Ramo."]]],"r":["As atividades da tropa escoteira motiva seus participantes na vivência de seu marco simbólico.","A vida em grupo na tropa escoteira revela a presença dos elementos que compõem o marco simbólico no ramo.","Os adolescentes compreendem e assimilam os valores propostos pelo Escotismo por meio das experiências vividas na tropa escoteira."]},{"d":"Cria atividades inspiradas no marco simbólico e nos símbolos do Ramo","g":[["Comportamentos desejados",["Organiza atividades utilizando o marco simbólico do ramo, relacionando-o com o Programa Educativo.","Utiliza o marco simbólico, preocupando-se com suas ações e o impacto que ele gera entre os integrantes da Tropa escoteira.","Utiliza elementos simbólicos no Ramo Escoteiro."]],["Atividades de desenvolvimento",["Planejar e executar uma atividade para a tropa escoteira, na qual se evidencie o marco simbólico.","Criar e aplicar uma atividade com base no marco simbólico do ramo."]],["Inclua no seu PPF",["Participar de uma conversa, sobre o marco simbólico do ramo e aplicar seus conceitos durante as atividades de seção.","Participar junto com a chefia de sua seção sobre uma reflexão sobre como estão aplicando o Marco Simbólico na seção, estudando as possíveis implementações para os próximos ciclos de programa."]]],"r":["Os adolescentes compreendem e assimilam os valores propostos pelo Escotismo a partir das vivências proporcionadas pelas atividades do ramo."]}]},{"x":12,"n":"Operação do Sistema de Especialidades e Insígnias","l":[{"d":"Identifica os elementos essenciais que compõem o sistema de especialidades, Insígnias de Interesse Especial e de modalidades","g":[["Comportamentos desejados",["Conhece a literatura relacionada à conquista de Distintivos de Especialidade e Insígnias de Interesse Especial, orientando os adolescentes a terem contato com isso.","Participa de cerimônias de entrega de Distintivos de Especialidade e Insígnias de Interesse Especial.","Orienta os integrantes da seção sobre as especialidades e Insígnias de Interesse Especial."]],["Atividades de desenvolvimento",["Ler o Guia de Especialidades e das Insígnias de Interesse Especial e saber orientar sobre sua utilização.","Ler as regras 169, 170, 171 e 173 do P.O.R."]]],"r":["Os escotistas conhecem os aspectos gerais e essenciais para a operação do sistema de especialidades e insígnias.","Os escotistas conhecem as regras de concessão das Insígnias de Modalidade."]},{"d":"Aplica o Sistema de Especialidades, da Insígnia da Modalidade e das Insígnias de Interesse Especial no Programa, incentivando sua conquista na Tropa","g":[["Comportamentos desejados",["Estimula o os adolescentes a conquistarem Distintivos de Especialidade e insígnias de interesse especial.","Auxilia na escolha de examinadores para a conquista de especialidades.","Compreende as especialidades como uma busca pessoal do jovem, de acordo com suas aptidões e interesses."]],["Atividades de desenvolvimento",["Realizar atividades que estimulem a conquista de especialidades.","Realizar uma atividade que estimule a conquista de Insígnias de Interesse Especial do Ramo Escoteiro.","Registrar a conquista de especialidades e insígnias dos adolescentes que acompanha.","Preencher de maneira adequada os certificados de conquista de insígnias e especialidades."]]],"r":["Os adolescentes desenvolvem especialidades em diversos ramos de conhecimento, tendo a oportunidade de desenvolverem-se de acordo com suas aptidões.","Os adolescentes sentem-se estimulados a conquistar especialidades e Insígnias de Interesse Especial.","Os adolescentes conversam com seus responsáveis sobre a conquista de distintivos."]},{"d":"Administra adequadamente a conquista de especialidades e insígnias pelos componentes da seção","g":[["Comportamentos desejados",["Realiza o acompanhamento das crianças que estão em processo de conquista de especialidades e insígnias.","Registra de maneira adequada as especialidades e insígnias conquistadas pelas crianças.","Realiza a entrega dos certificados e distintivos em tempo e maneira adequados."]],["Atividades de desenvolvimento",["Organizar o mapeamento geral de conquistas de especialidades e insígnias dos integrantes da seção.","Orientar os demais escotistas sobre o panorama de conquistas de especialidades e insígnias dos integrantes da seção.","Em uma reunião de pais, apresentar o sistema de especialidades e insígnias."]],["Inclua no seu PPF",["Conversar com outro adulto sobre ferramentas para realização do acompanhamento de especialidades e utilizá-lo em seu dia a dia.","Verificar se o mAPPa está sendo utilizado pelos integrantes da seção e se os adultos estão conseguindo acessar e acompanhar a progressão pelo aplicativo.","Avaliar, junto ao seu APF, a forma que realizou as entregas de distintivo, durante as atividades da seção.","Avalia a entrega de distintivos de sua seção para verificar se estão de acordo com o proposto pelos Escoteiros do Brasil."]]],"r":["A documentação e os registros da seção são preservados de maneira adequada e segura.","Os adolescentes são reconhecidos adequadamente e prontamente sobre suas conquistas."]}]},{"x":13,"n":"Envolvimento Comunitário","l":[{"d":"Descreve o conceito de envolvimento comunitário e as atividades propostas para o tema pelos Escoteiros do Brasil","g":[["Comportamentos desejados",["Conhece os materiais de referência para atividades comunitárias dos Escoteiros do Brasil.","Incentiva os adolescentes a realizarem e participarem de atividades de serviço à comunidade.","Participa da organização de atividades comunitárias dos Escoteiros do Brasil."]],["Atividades de desenvolvimento",["Ler a programação e as orientações de aplicação de uma edição do EducAção Escoteira e MUTCOM.","Participar de uma atividade comunitária juntamente com a tropa escoteira."]]],"r":["Os escoteiros compreendem a importância da realização de boas ações à comunidade.","A Unidade Escoteira Local faz-se presente na comunidade e busca reconhecimento por sua atuação."]},{"d":"Aplica e desenvolve atividades comunitárias de acordo com as orientações dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Participa da organização de atividades comunitárias dos Escoteiros do Brasil.","Incentiva os adolescentes a realizarem e participarem de atividades de serviço à comunidade.","Explica aos demais adultos da estrutura a importância da realização de atividades comunitárias."]],["Atividades de desenvolvimento",["Estimular a participação da seção em um Mutirão Nacional de Ação Comunitária ou EducAção Escoteira, orientando os jovens quanto aos aspectos de organização.","Organizar uma atividade comunitária, além das citadas acima.","Ler a publicação “Escotismo e Comunidade” e discuti-la com seu Assessor Pessoal de Formação.","Promover uma atividade que estimulem os escoteiros a conquistarem a Insígnia de Ação Comunitária."]]],"r":["Os escoteiros compreendem a importância da realização atividades comunitárias.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço relevante para o desenvolvimento comunitário."]},{"d":"Avalia a participação da seção em atividades de envolvimento comunitário e busca pontos de melhoria para as próximas participações","g":[["Comportamentos desejados",["Avalia a organização de atividades comunitárias dos Escoteiros do Brasil na Unidade Escoteira Local.","Incentiva as crianças a realizarem e participarem de atividades de serviço à comunidade.","Identifica pontos de melhoria para a organização de novas atividades de envolvimento comunitário na Unidade Escoteira Local."]],["Atividades de desenvolvimento",["Realizar, junto à equipe de escotistas, uma reunião de avaliação das atividades de desenvolvimento comunitário.","Orientar os jovens a avaliarem o impacto das atividades e projetos de desenvolvimento comunitário realizados pelas patrulhas ou pela seção, indicando pontos de melhoria."]],["Inclua no seu PPF",["Organizar/participar de uma conversa de avaliação sobre as atividades de Envolvimento Comunitário com os outros adultos da seção.","Avaliar como foi a aplicação e envolvimento da sua seção no MUTCOM.","Promover uma atividade de serviço à comunidade na seção, incentivando a participação da tropa escoteira, buscando orientação na diretoria da UEL.","Organizar/participar de uma conversa de avaliação sobre as atividades de envolvimento comunitário com os outros adultos da seção.","Em uma Reunião do Conselho de Pais da seção, avaliar as possibilidades de atividades comunitárias, mapeando as iniciativas propostas para aumentar o impacto das ações da Seção."]]],"r":["Os adolescentes compreendem a importância da realização de atividades voltadas ao envolvimento comunitário.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço relevante para o desenvolvimento comunitário."]}]},{"x":14,"n":"Desenvolvimento Sustentável","l":[{"d":"Descreve o conceito de desenvolvimento sustentável e as atividades propostas para o tema pelos Escoteiros do Brasil","g":[["Comportamentos desejados",["Conhece os materiais de referência para atividades de desenvolvimento sustentável dos Escoteiros do Brasil.","Incentiva os adolescentes a realizarem e participarem de atividades de desenvolvimento sustentável.","Conhece quais são os Objetivos do Desenvolvimento Sustentável."]],["Atividades de desenvolvimento",["Ler a programação e as orientações de aplicação de uma edição do MUTECO.","Participar de uma atividade relacionada ao desenvolvimento sustentável juntamente com a tropa escoteira."]]],"r":["Os escoteiros compreendem a importância da realização de atividades que enfatizem as práticas para o desenvolvimento sustentável.","A Unidade Escoteira Local faz-se presente na comunidade e busca reconhecimento por sua atuação.","A Unidade EscoteiraLocal promove ações relacionadas aos pontos dos ODS."]},{"d":"Aplica e desenvolve atividades sobre desenvolvimento sustentável e meio ambiente de acordo com as orientações dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Participa da organização de atividades que enfatizem a prática de ações para o desenvolvimento sustentável.","Incentiva os adolescentes a realizarem e participarem de atividades voltadas ao desenvolvimento sustentável","Atualiza-se em relação às tendências e às práticas sustentáveis."]],["Atividades de desenvolvimento",["Estimular a participação da seção em um MUTECo, orientando os jovens quanto aos aspectos de sua organização.","Organizar uma atividade relacionada ao desenvolvimento sustentável, além da citada acima.","Estimular os integrantes da seção a conquistarem a Insígnia Mundial do Meio Ambiente."]]],"r":["Os escoteiros compreendem a importância da realização de atividades comunitárias ligadas aos ODS.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço relevante para o desenvolvimento sustentável."]},{"d":"Avalia a participação da seção em atividades de desenvolvimento sustentável, buscando pontos de melhoria","g":[["Comportamentos desejados",["Avalia a organização de atividades dos Escoteiros do Brasil que enfatizem o desenvolvimento sustentável na Unidade Escoteira Local.","Incentiva as crianças a realizarem e participarem de atividades relacionadas ao desenvolvimento sustentável.","Identifica pontos e melhoria para a organização de novas atividades relacionadas ao desenvolvimento sustentável na Unidade Escoteira Local."]],["Atividades de desenvolvimento",["Realizar, junto à equipe de escotistas, uma reunião de avaliação das atividades relacionadas às práticas de desenvolvimento sustentável.","Ler o documento “Educação para os Objetivos de Desenvolvimento Sustentável”, da UNESCO, e aplicar uma atividade sobre os ODS, baseado em suas informações.","Orientar os jovens a avaliarem o impacto das atividades e projetos de desenvolvimento sustentável realizados pelas patrulhas ou pela seção, indicando pontos de melhoria."]],["Inclua no seu PPF",["Organizar/participar de uma conversa de avaliação sobre as atividades de Desenvolvimento Sustentável com os outros adultos da seção.","Avaliar como foi a aplicação e envolvimento da sua seção no MUTECO.","Promover uma atividade sobre desenvolvimento sultentável na seção, incentivando a participação dos escoteiros, buscando a orientação da Direotria da UEL.","Organizar/participar de uma conversa de avaliação sobre as atividades de desenvolvimento sustentável com os outros adultos da seção.","Em uma Reunião do Conselho de Pais da seção, avaliar as possibilidades de atividades de desenvolvimento sustentável, mapeando as iniciativas propostas para aumentar o impacto das ações da seção."]]],"r":["Os integrantes da seção compreendem a relação entre os Objetivos do Desenvolvimento Sustentável e suas formas de interação com o mundo que os cerca.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço de referência em práticas de desenvolvimento sustentável."]}]},{"x":15,"n":"Aplicação do Sistema de Equipes","l":[{"d":"Descreve os elementos que compõem o Sistema de Patrulhas","g":[["Comportamentos desejados",["Conhece os elementos essenciais que embasam o Sistema de Patrulhas.","Entende a tropa escoteira como ambiente natural para o desenvolvimento das atividades no Ramo Escoteiro.","Incentiva as patrulhas a terem seus símbolos."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 3 do Manual do Escotista do Ramo Escoteiro.","Orientar os monitores para que as patrulhas tenham encargos dentro e fora da sede.","Orientar os monitores para que as patrulhas tenham livros de patrulha, bandeirola e grito, além de utilizar seu distintivo de patrulha."]]],"r":["Os adolescentes nas patrulhas têm encargos na sede e em atividades fora da sede.","As patrulhas na tropa têm livros de patrulha.","Os integrantes da tropa utilizam distintivos de patrulha.","As patrulhas tem elementos simbólicos, tais como bandeirola, grito e cores."]},{"d":"Aplica o sistema de de Patrulhas na tropa escoteira, de acordo com o orientado no Manual do Escotista do Ramo Escoteiro","g":[["Comportamentos desejados",["Incentiva as patrulhas para a realização de Conselhos e Atividades de Patrulhas.","Realiza a ação educativa durante os Conselhos de Patrulha, Assembleias de Tropa e Corte de Honra.","Orienta os monitores na realização de eleições de monitores e submonitores."]],["Atividades de desenvolvimento",["Orientar os monitores para que as patrulhas realizem a eleição de monitores e submonitores.","Atuar educativamente nas reuniões da Corte de Honra previstas no calendário.","Orientar as patrulhas sobre a realização de atividades de patrulha dentro ou fora da sede.","Atuar educativamente nas Assembleias de Tropa previstas no calendário."]]],"r":["Os monitores operam as atividades da seção por meio das orientações dos escotistas.","As patrulhas realizam atividades de patrulha (tanto na sede quanto fora) com regularidade.","As reuniões da Corte de Honra são realizadas com regularidade e contam com a correta intervenção educativa dos escotistas."]},{"d":"Orienta os demais Escotistas na correta aplicação Sistema de Patrulhas no Ramo Escoteiro","g":[["Comportamentos desejados",["Entende a tropa escoteira como espaço natural para o desenvolvimento das atividades do Ramo Escoteiro.","Proporciona o ambiente necessário para o autodesenvolvimento das crianças da tropa escoteira.","Orienta os demais escotistas sobre as maneiras de aplicar o sistema de equipes no ramo."]],["Atividades de desenvolvimento",["Em um conselho de pais, apresentar as características do Sistema de Patrulhas.","Orientar os demais escotistas sobre a realização de Conselhos de Patrulha, Assembleias de Tropa e Corte de Honra.","Orientar os monitores no planejamento de excursões e acampamentos de patrulha."]],["Inclua no seu PPF",["Participar de uma conversa sobre a vida em grupo no Ramo Escoteiro e aplicar seus conceitos durante as atividades da seção.","Avaliar a atuação das matilhas refletindo no desenvolvimento de cada integrante."]]],"r":["Os escotistas recebem a orientação adequada sobre a aplicação do Sistema de Patrulhas."]}]},{"x":16,"n":"Domínio do Programa Educativo","l":[{"d":"Identifica as seis áreas de desenvolvimento do Programa Educativo","g":[["Comportamentos desejados",["Participa, junto dos demais escotistas da seção, da organização de atividades nas seis áreas de desenvolvimento.","Identifica quais são as seis áreas de desenvolvimento do Programa Educativo.","Colabora com o registro das atividades da seção."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 8 (Áreas de desenvolvimento), do Manual do Escotista do Ramo Escoteiro.","Ler os capítulos 7 e 9 do P.O.R.","Ler o livro “Escotistas em ação - Ramo Escoteiro”."]]],"r":["São realizadas na U.E.L. atividades nas seis áreas de desenvolvimento."]},{"d":"Aplica atividades atraentes, progressivas e variadas nas 6 áreas de desenvolvimento, organizadas de acordo com a ênfase definida pelo Ciclo de Programa","g":[["Comportamentos desejados",["Aplica atividades atraentes, progressivas e variadas no Ramo Escoteiro, conforme definidas no ciclo de programa.","Pesquisa atividades relacionadas às áreas de desenvolvimento.","Orienta educativamente os adolescentes da seção no cumprimento das atividades do Programa Educativo."]],["Atividades de desenvolvimento",["Aplicar atividades em todas as áreas de desenvolvimento e registrá-las adequadamente.","Ler o capítulo 12 (O Ciclo de Programa), do Manual do Escotista do Ramo Escoteiro.","Participar de todas as fases de desenvolvimento de um Ciclo de Programa, de acordo com as orientações do Manual do Escotista do Ramo."]]],"r":["As atividades fixas e variáveis consideram todas as áreas de desenvolvimento."]},{"d":"Avalia a aplicação das atividades do programa educativo e orienta os demais escotistas","g":[["Comportamentos desejados",["Avalia as atividades organizadas na seção.","Orienta a realização de atividades relacionadas às áreas de desenvolvimento.","Orienta os demais integrantes da Tropa escoteira sobre os processos de avaliação da progressão pessoal."]],["Atividades de desenvolvimento",["Conversar com o APF sobre os resultados da avaliações das atividades desenvolvidas e buscar novas ideias a partir dos pontos de melhoria identificados.","Ler a Política Nacional de Programa Educativo.","Conduzir corretamente, em conjunto com os jovens, processos de avaliação das atividades realizadas pela seção."]],["Inclua no seu PPF",["Realizar, com seus pares, momentos de avaliação das diversas atividades da seção.","Rever com sua Equipe de trabalho se as atividades estão relacionadas às áreas de desenvolvimento e, se necessário, reler o capítulo do Manual do escotista que versa sobre o tema.","Realizar reuniões com sua Equipe de trabalho para orientá-los sobre os processos de avaliação da progressão pessoal na Tropa escoteira.","Em uma reunião com sua equipe de trabalho, avaliar se todos os pontos do método escoteiro estão sendo trabalhados, fazendo eventuais sugestões de como melhorar a aplicação de algum dos pontos."]]],"r":["As atividades fixas e variáveis consideram todas as áreas de desenvolvimento.","A administração da seção está em dia e a documentação em ordem."]}]},{"x":17,"n":"Campismo e Vida ao Ar Livre","l":[{"d":"Reconhece a importância da vida ao ar livre para as atividades escoteiras","g":[["Comportamentos desejados",["Relaciona adequadamente a utilização de técnicas de campismo e vida ao ar livre a atividades educativas.","Colabora com os demais escotistas na promoção de atividades que contribuam para o aprendizado de técnicas de campo para os adolescentes.","Identifica adequadamente os materiais necessários para os diversos tipos de atividades de campismo e vida ao ar livre."]],["Atividades de desenvolvimento",["Saber os seguintes nós: Direito, Volta do Fiel, Volta da Ribeira, Nó de Escota, Escota Alceado, Nó em oito, Volta Redonda com Dois Cotes, Catau, Lais de Guia, Cadeira de Bombeiro, assim como saber saber falcaçar cabos e transmiti-los utilizando o sistema de patrulhas.","Distribuir corretamente o material dentro de uma mochila e ensinar para a tropa utilizando o Sistema de Patrulhas."]]],"r":["Os escotistas da seção valorizam a realização de acampamentos e atividades ao ar livre na seção.","São realizadas atividades ao ar livre na seção."]},{"d":"Seleciona e aplica técnicas de campismo adequadas às atividades do Programa Educativo do Ramo Escoteiro","g":[["Comportamentos desejados",["Aplica técnicas de campo e proporciona vivências educativas a partir destes recursos aos adolescentes.","Planeja atividades que contribuam para o aprendizado de técnicas de campo para os adolescentes.","Orienta os integrantes da seção na realização de atividades e tarefas referentes ao campismo e à vida ao ar livre."]],["Atividades de desenvolvimento",["Saber as amarras Quadrada e Diagonal e ensiná-las à tropa escoteira, utilizando o Sistema de Patrulhas.","Utilizando o Sistema de Patrulha ensinar para a tropa: utilizar e conservar o fogareiro e lampião, utilizar ferramentas de sapa e corte e acender uma fogueira e realizar uma receita de comida mateira.","Montar uma barraca e ensinar os procedimentos à tropa, utilizando o Sistema de Patrulhas.","Conhecer os Sinais de Pistas e ensinar sobre sua utilização a tropa usando o sistema de patrulhas.","Saber estimar alturas e distâncias utilizando métodos distintos, assim como ensiná-los à tropa escoteira, utilizando o sistema de Patrulhas","Ler o livro “Padrões de atividades escoteiras”."]]],"r":["Os integrantes da tropa escoteira assumem responsabilidades e sabem como resolver pequenos problemas em acampamentos.","Os integrantes da tropa escoteira participam com entusiasmo dos acampamentos e atividades ao ar livre.","Os integrantes da tropa escoteira apresentam bom aproveitamento na realização das técnicas de campo previstas no Programa Educativo do Ramo.","São realizadas atividades ao ar livre na seção."]},{"d":"Avalia a execução da prática de técnicas de campismo e vida ao ar livre e orienta sobre sua correta aplicação","g":[["Comportamentos desejados",["Aplica técnicas de campo e proporciona vivências educativas, a partir destes recursos, às crianças.","Planeja atividades que contribuam para o aprendizado de técnicas de campo para as crianças.","Orienta os demais escotistas da equipe na execução de atividades ao ar livre e aplicação de técnicas de campismo."]],["Atividades de desenvolvimento",["Organizar uma jornada de Travessia, relacionada com progressão pessoal, para um jovem (acompanhado de outro membro da seção). Devem ser considerando todos os aspectos de planejamento do percurso e segurança.","Realizar reuniões de avaliação das atividades junto à equipe de escotistas e discutir suas impressões sobre as atividades com o APF.","Aplicar os conceitos básicos de estruturas (cavaletes, encaixes, ancoragens) nos projetos e montagem de construções, como pontes, balsas etc.","Utilizando o sistema de Patrulha ensinar a tropa a construir um abrigo natural.","Orientar as patrulhas sobre como utilizar técnicas de previsão de tempo por indícios naturais.","Ensinar a técnica do percurso de Gilwell, utilizando o Sistema de Patrulhas.","Ensinar tecnicas de leitura e orientação de cartas topográficas, com auxílio de bússola, utilizando o sistema de patrulhas."]],["Inclua no seu PPF",["Participar de um módulo ou outro momento de capacitação a respeito de técnicas de campo, aplicando seus conceitos nas reuniões da seção.","Conversar com sua equipe de trabalho sobre o equilíbrio de atividades ao ar livre dentro dos ciclos de programas propostos.","Em uma reunião de pais, expor a importância de atividades ao ar livre para o Movimento escoteiro, destacando os benefícios que essa prática traz para o desenvolvimento dos jovens."]]],"r":["A equipe de escotistas recebe a orientação adequada para a aplicação de atividades ao ar livre.","As atividades ao ar livre são avaliadas e sua execução é constantemente aperfeiçoada."]}]},{"x":18,"n":"Organização de Atividades","l":[{"d":"Identifica os tipos de atividade fixas e variáveis), planejando e executando reuniões semanais e gerando experiências educativas","g":[["Comportamentos desejados",["Participa dos encontros de planejamento das reuniões semanais, contribuindo com sugestões.","Dirige algumas atividades das reuniões semanais e apoia a realização das demais.","Reconhece pontos positivos e negativos durante a execução das atividades realizadas."]],["Atividades de desenvolvimento",["Ler o livro “Os primeiros meses de uma tropa escoteira”.","Participar das reuniões da tropa escoteira, contribuindo em seu planejamento, execução e avaliação."]]],"r":["As reuniões semanais são dinâmicas e animadas.","As reuniões semanais são organizadas e com materiais disponíveis e preparados previamente.","Há um bom índice de assiduidade nas reuniões semanais da tropa escoteira."]},{"d":"Diferencia os cuidados de planejamento entre reuniões e atividades fora da sede","g":[["Comportamentos desejados",["Cuida da organização das atividades fora da sede, realizando todos os passos que garantam sua realização de maneira segura e educativa.","Compartilha previamente a programação das atividades com a equipe de escotistas.","Informa antecipadamente os participantes da seção e seus responsáveis sobre a realização de atividades fora da sede."]],["Atividades de desenvolvimento",["Participar da organização e da execução de um Fogo de conselho.","Orientar os Monitores no planejamento de um cardápio para um acampamento.","Participar do planejamento de um acampamento ou acantonamento da seção.","Organizar uma excursão com a tropa e participar da avaliação junto da equipe de escotistas.","Ler o livro “Fogo de Conselho”."]]],"r":["As atividades da seção são seguras e tem seu caráter educativo preservado.","As atividades fora da sede são organizadas e com materiais sempre disponíveis e preparados.","Há um bom índice de assiduidade nas atividades realizadas fora da sede."]},{"d":"Orienta os demais adultos sobre os tipos de atividade fixas e variáveis), auxiliando-os em sua execução e condução","g":[["Comportamentos desejados",["Avalia o planejamento e execução de atividades dentro e fora da sede, buscando pontos de melhoria para próximas atividades.","Orienta os demais escotistas da seção no planejamento e execução de atividades dentro e fora da sede.","Planeja atividades variadas, de acordo com a ênfase identificada durante a execução do ciclo de programa."]],["Atividades de desenvolvimento",["Realizar reuniões de avaliação das atividades junto à equipe de escotistas e discutir suas impressões sobre as atividades com o APF."]],["Inclua no seu PPF",["Preparar um plano de execução de atividades e tê-lo aprovado pela diretoria da UEL.","Realizar reuniões de avaliação e orientação dos demais escotistas quanto à realização de atividades ao ar livre.","Reavaliar, junto à sua equipe, o calendário de atividades e verificar se as atividades estão de acordo com a ênfase definida durante a preparação do ciclo de programa."]]],"r":["Os integrantes da tropa escoteira participam com entusiasmo dos acampamentos e atividades ao ar livre.","São realizadas atividades ao ar livre na seção.","Os escotistas recebem orientação adequada para a realização de atividades de campismo e vida ao ar livre.","As atividades fora da sede são organizadas e com materiais sempre disponíveis e preparados.","Há um bom índice de assiduidade nas atividades realizadas fora da sede."]}]}]}]},"sen":{"n":"Sênior","g":[{"t":"Competências essenciais","c":[{"x":0,"n":"Gestão de Mudanças","l":[{"d":"Demonstra disposição de aprender formas diferentes de fazer as coisas","g":[["Comportamentos desejados",["Aceita outras formas de fazer as coisas.","Mantém uma atitude positiva quando tem que mudar de ideia, conceitos, tarefas ou funções.","Busca informações sobre as mudanças e obtém informações que permita compreende-las."]],["Atividades de desenvolvimento",["Ler o documento “Características Essenciais do Movimento Escoteiro “ e debater com seu APF as impressões sobre o documento.","Ler o capítulo “História do Escotismo”, do livro “Escotistas em ação - Ramo Sênior”."]]],"r":["Os voluntários lidam de maneira receptiva com as mudanças da organização."]},{"d":"Analisa e implementa ações para a gestão de mudanças","g":[["Comportamentos desejados",["Aplica procedimentos de maneira flexível quando as circunstâncias exigem.","Toma decisões de maneira autonoma como resposta a situações de transformação.","É criativo e inovador no desempenho de suas funções."]],["Atividades de desenvolvimento",["Trabalhar junto com sua equipe ações que promovam a inovação em rotinas de sua função."]]],"r":["Os fluxos e processos da estrutura são constantemente revisados e aprimorados."]},{"d":"Avalia e projeta ações de mudança na estrutura em que atua","g":[["Comportamentos desejados",["Antecipa riscos emergentes e aproveita oportunidades para satisfazer as necessidades futuras.","Modifica procedimentos padronizados em resposta a ambientes em transformação.","Cria novos modelos e metodologias organizacionais em resposta a novos contextos, condições e situações."]],["Atividades de desenvolvimento",["Organizar ações de melhoria e desenvolvimento contínuo na estrutura em que atua, tais como projetos, campanhas de comunicação e inovações em processos."]],["Inclua no seu PPF",["Promover em seu grupo uma discussão sobre alguma nova publicação ou resolução da UEB lançadas no último ano.","Propor alguma alteração ou adequação de procedimento no seu nível de atuação visando atender às transformações do ambiente.","Identificar uma nova situação e propor um plano de implantação para as mudanças sugeridas, ressaltando os controles que devem ser tidos para evitar os antigos hábitos.","Desenvolver pesquisas sobre o uso de novas tecnologias na metodologia organizacional.","Organizar ações de melhoria e desenvolvimento contínuo na estrutura em que atua, tais como projetos, campanhas de comunicação e inovações em processos."]]],"r":["Em momentos de mudança, os voluntários já se sentem preparados para adaptarem-se e promoverem as ações necessárias para a sua implantação."]}]},{"x":1,"n":"Aprendizagem e Desenvolvimento Pessoal","l":[{"d":"Expressa interesse e comprometimento com sua capacitação para a função que exerce","g":[["Comportamentos desejados",["Observa e aprende com os demais.","Participa de cursos, módulos e outras iniciativas de formação inerentes ao seu cargo ou função.","Como voluntário, busca esclarecer suas dúvidas em relação ao desempenho de sua função com o APF."]],["Atividades de desenvolvimento",["Em conjunto com o APF, preparar o seu Plano Pessoal de Formação.","Participar do Curso Preliminar.","Ler e discutir com o APF a descrição do Cargo de Assessor Pessoal de Formação."]]],"r":["Os voluntários são comprometidos com seus processos de atualização.","Os adultos da U.E.L. tem APFs nomeados pela Diretoria da Estrutura."]},{"d":"Analisa os resultados de sua aprendizagem e compartilha seus conhecimentos e experiências com os demais","g":[["Comportamentos desejados",["Atua como agente promotor de novas ideias e tecnologias.","Motiva os demais na participação em processos de melhoria contínua, ajudando no desenvolvimento de suas tarefas e crescimento pessoal","Aplica ao seu trabalho novas aprendizagens que enriquecem suas ações"]],["Atividades de desenvolvimento",["Realizar a revisão de seu PPF.","Participar do Curso Básico.","Ler o Guia do Chefe Escoteiro de Baden-Powell.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função.","Participar do curso em EAD sobre Assessor Pessoal de Formação ou outra iniciativa sobre o tema."]]],"r":["Os voluntários da estrutura compartilham informações sobre suas experiências de formação.","Os voluntários da estrutura aplicam novos conceitos às ações empregadas."]},{"d":"Avalia seus próprios resultados e realiza ações para melhorar seu desempenho continuamente","g":[["Comportamentos desejados",["Analisa seus próprios resultados e estabelece planos de ações para sua melhora.","Aproveita as mudanças organizacionais como oportunidades para desenvolver novos conhecimentos e habilidades.","Utiliza suas próprias experiências como aprendizados que compartiilha abertamente com os demais."]],["Atividades de desenvolvimento",["Realizar a revisão do seu PPF,","Organizar ações para que os demais voluntários participem de iniciativas de formação e atualização.","Participar do Curso Avançado.","Conversar com o seu Assessor Pessoal de Formação sobre a História da Insígnia de Madeira e Gilwell Park.","Ler a Politica Nacional de Adultos no Movimento Escoteiro.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função."]],["Inclua no seu PPF",["Fazer anotações pessoais e avaliar se as atividades planejadas foram cumpridas e se as propostas foram realizadas, identificando oportunidades de autodesenvolvimento.","Fazer um levantamento dos projetos que estão sendo realizados pela UEB, que possam ser agregados como metodologia de desenvolvimento e melhoria no nível em que atua.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função.","Promover um debate junto ao nível em que atua sobre as atualizações propostas pela União dos Escoteiros do Brasil, vinculando as experiências vividas e desenvolvidas no último ano.","Desenvolver e manter um arquivo pessoal com projetos realizados e resgatá-los com os ajustes sempre que necessário."]]],"r":["Os voluntários promovem momentos de autoavaliação e compartilhamento de impressões sobre seu próprio desenvolvimento, gerando um clima de aprendizado contínuo."]}]},{"x":2,"n":"Compromisso","l":[{"d":"Aceita voluntariamente os fundamentos do Escotismo e cumpre suas tarefas com responsabilidade","g":[["Comportamentos desejados",["Vincula o propósito, os princípios, os valores e a missão do Movimento Escoteiro às suas atividades cotidianas.","Assume como próprios o propósito, os princípios, os valores e a missão do Movimento Escoteiro.","Atua de acordo com a orientação espiritual dos Escoteiros do Brasil no exercício de sua função."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 1 do P.O.R.","Conversar com seu APF, identificando os quatro itens que compõem os fundamentos do Escotismo (definição, propósito, princípios e método).","Realizar sua Promessa Escoteira.","Ler o capítulo 3 do P.O.R. - orientação espiritual."]]],"r":["As responsabillidades são distribuídas e cumpridas de maneira adequada."]},{"d":"Assume voluntariamente novas responsabilidades adicionais a correspondente ao seu cargo, atuando de acordo com os fundamentos do Escotismo","g":[["Comportamentos desejados",["Compartilha o significado do propósito, dos princípios, dos valores e da missão do Movimento Escoteiro a ambientes exteriores aos da organização.","Assessora e guia os demais na realização de suas tarefas.","Dá andamento aos seus compromissos e reconhece as ações que deve implementar para seu cumprimento."]],["Atividades de desenvolvimento",["Organizar/Participar com a equipe de adultos da estrutura, de grupos de debates sobre as diversas funções existentes no Movimento Escoteiro.","Organizar/Participar de ações de captação de novos adultos para o Movimento Escoteiro.","Ler o Projeto Educativo da União dos Escoteiros do Brasil"]]],"r":["Os voluntários compartilham os valores do Movimento Escoteiro em ambientes externos à organização.","Os voluntários recebem a orientação e o suporte necessários para a implementação do propósito, princípio, valores e missão do Movimento Escoteiro."]},{"d":"Implementa ações para promover o compromisso de outros adultos dos Escoteiros do Brasil aos fundamentos do Escotismo","g":[["Comportamentos desejados",["Gera espaços que fomentem a iniciativa e responsabilidades em momentos críticos.","É disciplinado e consciente no uso de recursos para o cumprimento de suas ações.","Dedica uma porcentagem de seu tempo a revisão dos planos de trabalho, objetivos e sua contribuição nestas tarefas."]],["Atividades de desenvolvimento",["Ler o Manual de Reconhecimento dos Escoteiros do Brasil."]],["Inclua no seu PPF",["Elaborar uma forma de dividir tarefas promovendo a avaliação de situações vividas pelo grupo e diferentes formas de se abordar momentos críticos.","Desenvolver propostas e métodos para melhoria na execução do planejamento das atividades no tocante ao uso de recursos.","Organizar com a equipe de adultos da estrutura, de grupos de debates sobre o uso de recursos para o cumprimento de ações.","Apresentar a revisão crítica de planos de trabalho executados nos últimos 6 meses, buscando apresentar sugestões de melhorias.","Apresentar um cronograma de desenvolvimento de ações futuras, evitando o acúmulo de atividades a serem realizadas."]]],"r":["Os voluntários são devidamente reconhecidos pelo seu compromisso e comprometimento.","São organizados momentos para revisão dos planos de trabalho e discussão sobre a distribuição de tarefas entre os voluntários."]}]},{"x":3,"n":"Consciência Organizacional","l":[{"d":"Identifica as estruturas da organização, especialmente o funcionamento e os objetivos do nível em que atua","g":[["Comportamentos desejados",["Conhece a história e os avanços mais relevantes da organização.","Conhece e identifica a estrutura da organização nos níveis local e regional.","Conhece os direitos e deveres inerentes ao seu cargo/função."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 5 do título 2 do Estatuto da União dos Escoteiros do Brasil e o Capítulo 5 do P.O.R."]]],"r":["Os voluntários conhecem a estrutura do nível que atuam e suas competências."]},{"d":"Desenvolve ações para a promoção de maior sentido de unidade e propósito comum nas ações da estrutura em que atua","g":[["Comportamentos desejados",["Implementa procedimentos organizacionais para a resolução de problemas.","Aplica os princípios de governança dentro da instituição.","Promove permanentemente as práticas democráticas e o respeito às diferenças."]],["Atividades de desenvolvimento",["Promover as políticas organizacionais dos Escoteiros do Brasil em grupos de debate e discussões, juntamente com a equipe da qual faz parte.","Ler o Estatuto dos Escoteiros do Brasil.","Participar de eventos distritais, regionais ou nacionais."]]],"r":["Os processos de escolha e renovação de lideranças estão de acordo com as recomendações das Políticas e orientações da Organização Mundial do Movimento Escoteiro.","São promovidas práticas de exercício da democracia e respeito às diferenças na estrutura."]},{"d":"Avalia e implementa ações para a conscientização de voluntários sobre a importância da estrutura institucional do Movimento Escoteiro","g":[["Comportamentos desejados",["Promove o sentido de unidade e propósito comum entre os diferentes níveis da Organização.","Compreende o impacto da sociedade civil, governo, setor privado, terceiro setor e outros grupos de interesse externos no cumprimento da missão da Organização.","Conhece a estrutura do Escotismo Mundial."]],["Atividades de desenvolvimento",["Explicar aos demais voluntários as relações entre as estruturas e níveis da organização.","Participar de uma assembleia regional ou nacional.","Ler as resoluções do CAN e DEN e debater com o APF ou grupo de discussão sobre os documentos."]],["Inclua no seu PPF",["Promover dentro do nível em que atua um debate sobre os diferentes níveis institucionais da União dos Escoteiros do Brasil, buscando compreender a atuação de cada um.","Promover as políticas organizacionais dos Escoteiros do Brasil em grupos de debate e discussões, juntamente com a equipe da qual faz parte.","Conhecer as propostas atuais sobre voluntariado definidas pelo Sistema público e terceiro setor, avaliar as necessidades de adaptação do nível em que atua.","Propor ações em parcerias com outras ONGS, entidades privadas e governamentais, visando o cumprimento da missão de nossa organização.","Apresentar aos membros do nível em que atua uma pesquisa sobre a estrutura do escotismo mundial, resumindo pelo menos uma política regional ou mundial."]]],"r":["Os voluntários têm a compreensão da importância das estruturas da organização e promovem boas práticas e o diálogo entre elas.","Os voluntários têm a compreensão da importância da boa relação que o Movimento Escoteiro deve ter com as demais instituições."]}]},{"x":4,"n":"Planejamento Estratégico","l":[{"d":"Identifica as responsabilidades e objetivos da função que desempenha","g":[["Comportamentos desejados",["Atua de acordo com as funções atribuidas a seu cargo, com a tarefa que lhe é designada.","Conhece o plano de trabalho da equipe da qual faz parte.","Solicita a assessoria necessária para o estabelecimento de planos de trabalho referentes a sua função."]],["Atividades de desenvolvimento",["Assinar o acordo de trabalho voluntário contendo a descrição das funções pertinentes ao cargo ao qual está designado."]]],"r":["Os voluntários da estrutura compartilham as responsabilidades necessárias para o desenvolvimento das atividades."]},{"d":"Planeja atividades e tarefas inerentes ao seu cargo ou função","g":[["Comportamentos desejados",["Formula planos de ação, considerando os objetivos de longo prazo, as metas e os planos da organização.","Presta assessoria em função dos planos de trabalho a curto, médio e longo prazo.","Estabelece pontos de controle, gerando dados e informações para o acompanhamento dos objetivos e prazos."]],["Atividades de desenvolvimento",["Ler o documento “Perfis: cargos e funções”, do nível em que atua.","Participar da concepção do calendário de atividades da estrutura em que atua."]]],"r":["Os voluntários da estrutura trabalham na concepção e revisão de planos de trabalho, monitorando seus resultados."]},{"d":"Compreende como sua atuação contribui para o alcance dos objetivos do Planejamento Estratégico dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Avalia periodicamente os resultados considerando fatores internos e externos críticos para o cumprimento dos seus planos e atividades.","Desenvolve diagnósticos de seus resultados e toma medidas em correspondência com seus resultados.","Propõe ações de melhora aos planos estratégicos e de ação da estrutura que faz parte."]],["Atividades de desenvolvimento",["Ler o Planejamento Estratégico dos Escoteiros do Brasil.","Participar do planejamento da sua Unidade Escoteira Local, considerando os objetivos anuais da sua seção."]],["Inclua no seu PPF",["Realizar sessão de avaliação visando identificar a influência de fatores internos e externos e se o planejamento proposto está sendo realizado, verificando a necessidade de adequação.","Estudar ao menos uma ferramenta de diagnóstico e, a utilizando, apresentar um estudo sobre quais ações devo realizar na resolução de problemas e desenvolvimento de um projeto em andamento.","Analisar o plano estratégico do nível que atua propondo ações de melhoria.","Participar do planejamento da sua Unidade Escoteira Local, considerando os objetivos anuais do nível em que atua."]]],"r":["Os voluntários são devidamente reconhecidos pelo seu compromisso e comprometimento.","São organizados momentos para revisão dos planos de trabalho e discussão sobre a distribuição de tarefas entre os voluntários."]}]},{"x":5,"n":"Relações Interpessoais","l":[{"d":"Identifica quais são as condutas referenciais de cortesia, respeito e confiança desejadas aos adultos dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Trata os demais com respeito, aceita as diferenças de pensamento e expressão das emoções.","Interage socialmente com outros, seguindo as normas básicas de cortesia.","Refere-se em termos positivos aos demais e sobre o trabalho que realizam."]],["Atividades de desenvolvimento",["Ler e discutir com seu Assessor Pessoal de Formação a definição do Movimento Escoteiro - Regra 001 do P.O.R."]]],"r":["A relação entre os voluntários é respeitosa e baseada em ações de cortesia.","Existe uma cultura de respeito à diversidade."]},{"d":"Desenvolve ações favorecendo as boas relações de trabalho cooperativo entre os adultos, inclusive com os responsáveis dos jovens","g":[["Comportamentos desejados",["É coerente em suas ações e seus resultados.","Promove a participação dos integrantes da tropa e o diálogo intergeracional.","Escuta pontos de vista dos demais e modifica sua própria perspectiva quando necessário."]],["Atividades de desenvolvimento",["Participar da organização de, pelo menos, um conselho de pais.","Participar de uma seção de avaliação sobre o seu próprio trabalho e receber as críticas de maneira aberta e construtiva."]]],"r":["Há envolvimento e preocupação por parte dos voluntários para que os conflitos existentes sejam mediados e solucionados."]},{"d":"Avalia sua relação com os demais e busca alternativas para fortalecê-las, baseadas em compreensão e flexibilidade","g":[["Comportamentos desejados",["Demonstra proatividade no momento de prestar apoio aos acontecimentos que requerem esforços integrados.","Sabe criticar ideias sem ofender pessoalmente quem as expressa.","Demonstra não tomar as palavras ou situações de maneira pessoal."]],["Atividades de desenvolvimento",["Planejar ações de integração entre pessoas e áreas de trabalho, promovendo o fortalecimento das relações","Prestar adequadamente avaliações sobre os componentes de sua equipe de trabalho ."]],["Inclua no seu PPF",["Propor um projeto para a UEL que deva ser realizado com integração das diferentes equipes que a compõe.","Procurar desenvolver atividades com outras pessoas da UEL não membros da sua equipe, buscando um olhar diferenciado na dinâmica possibilitando o fortalecimento e a boa comunicação interna do nível em que atua.","Planejar atividades de integração entre as equipes ou a novos integrantes a sua equipe de atuação.","Identificar formas de escuta e reflexão antes de criticar outras pessoas da equipe ou da UEL","Planejar ações de integração entre pessoas e áreas de trabalho, promovendo o fortalecimento das relações.","Prestar adequadamente avaliações sobre os componentes de sua equipe de trabalho.","Promover um debate sobre empatia e comunicação não violenta.","Desenvolver uma metodologia para dar oportunidade de ouvir todos os membros da equipe antes de tomar decisões ou propor ações, levando em consideração que as soluções devem sempre estar voltadas para o interesse do grupo e não para os interesses individuais."]]],"r":["Os voluntários são pró-ativos na resolução de conflitos entre adultos da organização.","Os voluntários posicionam-se de maneira adequada e sensata, gerando um clima de confiança mútua."]}]},{"x":6,"n":"Trabalho em Equipe","l":[{"d":"Reafirma a importância do trabalho em equipe, cooperando com os participantes de seu grupo de trabalho","g":[["Comportamentos desejados",["Assume seu papel/tarefas designadas com responsabilidade.","Ajuda em outras tarefas além das quais é responsável, quando necessário.","Expressa-se em termos positivos a sua equipe."]],["Atividades de desenvolvimento",["Participar de, pelo menos, um Conselho de Chefes da Unidade Escoteira Local."]]],"r":["As tarefas/projetos são desenvolvidas coletivamente e seus resultados são compartilhados."]},{"d":"Desenvolve projetos e as competências da equipe de trabalho que compõe","g":[["Comportamentos desejados",["Conhece as fortalezas e pontos de melhoria dos integrantes da equipe.","Proporciona ou assegura o apoio necessário para o desenvolvimento da equipe.","Gera um clima de trabalho que promove o espírito e a cooperação da equipe com outras equipes."]],["Atividades de desenvolvimento",["Cumprir com as responsabilidades inerentes a sua função (Registro no PAXTU, acompanhamento da progressão pessoal, aplicação de jogo/atividade, realização de cerimônia, etc.)"]]],"r":["Os voluntários têm facilitado o apoio para o desenvolvimento de seus projetos mediante o trabalho em equipe.","A comunicação entre os voluntários da estrutura tem fluxos ágeis e definidos."]},{"d":"Avalia os resultados atingidos pela equipe de trabalho que compõe e estimula ações para sua melhoria.","g":[["Comportamentos desejados",["Avalia as fortalezas e pontos de melhoria da equipe e seus integrantes para propor ações de melhora.","Avalia abertamente sua própria participação e contribuição nos resultados da equipe.","Permite aos demais a participação na construção da visão dos resultados que se esperam pela equipe."]],["Atividades de desenvolvimento",["Avaliar as ações desenvolvidas pela sua equipe em reuniões periódicas, com a colaboração dos demais participantes da equipe."]],["Inclua no seu PPF",["Promover momentos de autoavaliação das ações e atuação da equipe perante as necessidades de um projeto em desenvolvimento, identificando as fortalezas e pontos de melhoria de cada membro da equipe.","Avaliar periodicamente com os membros do nível em que atua as ações realizadas e refletir sobre as causas do não cumprimento, identificando como posso melhor contribuir para os resultados da equipe.","Avaliar as ações desenvolvidas por você em reuniões periódicas, com a colaboração dos demais participantes da equipe.","Propor diferentes modos para que todos da equipe possam participar dos processos de construção e desenvolvimento de projetos, inclusive assumindo diferentes funções."]]],"r":["Os voluntários realizam processos de avaliação em equipe e propõem estratégias para suas ações."]}]}]},{"t":"Competências específicas","c":[{"x":7,"n":"Aplicação de Jogos e Canções","l":[{"d":"Identifica as características dos diferentes tipos de jogos e canções e os conduz de maneira adequada para a criação de um ambiente educativo","g":[["Comportamentos desejados",["Pesquisa sobre os diferentes tipos de jogos e canções existentes.","Entende os jogos e canções como recurso educativo.","Participa da aplicação de jogos e canções na seção."]],["Atividades de desenvolvimento",["Aplicar jogos e canções de maneira atraente, utilizando técnicas diversificadas."]]],"r":["Os escotistas compreendem a importância dos jogos e das canções na prática do Escotismo.","Os jogos são oportunidades de avaliação do comportamento dos integrantes da tropa.","As canções são utilizadas na programação da seção, de forma a servirem como equalizador do ritmo da reunião, acalmando ou animando os jovens."]},{"d":"Organiza e aplica jogos educativos e canções no Movimento Escoteiro","g":[["Comportamentos desejados",["Seleciona jogos e canções adequados à faixa etária do ramo.","Sugere jogos e canções adequados aos diversos momentos e situações na tropa.","Aplica jogos e canções corretamente e com entusiasmo."]],["Atividades de desenvolvimento",["Aplicar diferentes jogos (ativo, cooperativo, noturno, grande jogo etc.), em atividades da tropa, orientando os monitores na utilização do Método Escoteiro.","Orientar os monitores para que cantem canções escoteiras junto com suas patrulhas.","Antes do curso básico, ler o capítulo 7 do Manual do Escotista do Ramo Sênior."]]],"r":["Há a troca de informações sobre a realização de jogos e canções entre os escotistas.","Os jogos e canções são atraentes, progressivos e variados."]},{"d":"Cria e orienta a aplicação de jogos e atividades educativas, em todas as áreas de desenvolvimento","g":[["Comportamentos desejados",["Cria jogos e canções adequados à faixa etária do ramo.","Orienta sobre a aplicação de jogos e canções adequados aos diversos momentos e situações na Tropa sênior.","Administra seu próprio arquivo/acervo de jogos e canções e o compartilha com os demais integrantes da equipe de escotistas."]],["Atividades de desenvolvimento",["Criar e aplicar jogos que contribuam em cada área de desenvolvimento.","Colaborar com a atualização do arquivo de jogos da tropa sênior.","Identificar as características que contribuem para que os participantes da seção desenvolvam suas competências durante a aplicação de jogos e canções.","Estimular e orientar as patrulhas da tropa na aplicação de jogos e canções."]],["Inclua no seu PPF",["Participar de uma iniciativa de formação sobre criação de jogos e canções.","Fazer uma leitura de livros e manuais de jogos e canções aplicadas para crianças.","Aprimorar a criação de jogos e canções, selecionando atividades interessantes para aplicar na sua seção.","Promover na seção um momento de reflexão entre os escotistas sobre a aplicação de jogos e canções e como essa prática pode ser aperfeiçoada.","Ter uma conversa com o APF sobre que ferramentas podem ser utilizadas para a gestão e arquivo de Jogos e Canções Escoteiras."]]],"r":["Os adultos da equipe de escotistas recebem a orientação adequada para a criação e condução de jogos e canções. Os jogos e canções são instrumentos que possibilitam a observação e a orientação educativa na tropa.","Tanto a tropa quanto as patrulhas utilizam canções no cotidiano de suas atividades, inclusive, criando paródias escoteiras."]}]},{"x":8,"n":"Condução de Cerimônias","l":[{"d":"Identifica as vozes de comando e sinais de apito na tropa e conduz as cerimônias de abertura e encerramento das reuniões de seção","g":[["Comportamentos desejados",["Comunica-se com adolescentes utilizando os sinais manuais apitos e vozes de comando corretamente.","Demonstra boa organização na preparação do local e dos materiais necessários para a realização das cerimonias da tropa.","Transmite as informações com segurança quando coordena uma cerimônia."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, assistir aos vídeos da série “Como se Faz?”.","Aplicar sinais manuais e apitos de comando na seção.","Conduzir uma cerimônia de Hasteamento ou Arriamento de bandeira.","Realizar uma entrega de Distintivo de Progressão/Especialidade/ Insígnia de Interesse Especial na seção."]]],"r":["Os adolescentes atendem às orientações dos escotistas.","As cerimônias são significativas para seus participantes."]},{"d":"Conduz cerimônias escoteiras de maneira adequada","g":[["Comportamentos desejados",["Conduz adequadamente o processo de passagem entre ramos","Compreende as cerimônias como um espaço educativo e inclusivo na prática do escotismo.","Compreende as cerimônias escoteiras como um momento educativo e inclusivo na prática do escotismo."]],["Atividades de desenvolvimento",["Conduzir uma cerimônia de Promessa Escoteira.","Realizar uma entrega de distintivo/Insígnia de Interesse Especial ou Distintivo Especial, Escoteiro da Pátria na seção.","Ler o Manual de Cerimônias dos Escoteiros do Brasil e discutir com seu Assessor Pessoal de Formação.","Conduzir uma cerimônia de Passagem de Ramo."]]],"r":["As cerimônias são adequadas, realizadas em momento oportuno, local apropriado e são estimulantes."]},{"d":"Orienta os demais integrantes da equipe quanto à realização de cerimônias, zelando pelo caráter educativo","g":[["Comportamentos desejados",["Conduz adequadamente o processo de passagem entre ramos dos integrantes da tropa sênior.","Orienta os demais adultos da seção na realização de cerimônias.","Compreende as cerimônias escoteiras como um momento educativo e inclusivo da prática do escotismo."]],["Atividades de desenvolvimento",["Orientar outro adulto na realização de uma cerimônia de hasteamento/ arriamento.","Conduzir uma cerimônia de Compromisso Sênior.","Orientar um integrante da tropa a preparar o seu Compromisso Sênior."]],["Inclua no seu PPF",["Participar de uma cerimônia de passagem em conjunto com outros escotistas e observar se a cerimônia guarda as características previstas no Manual de Cerimônias dos Escoteiros do Brasil.","Observar outros escotistas na aplicação de cerimônias e transmitir informações para que as realizem corretamente e com segurança.","Analisar as cerimônias realizadas na seção, e assim avaliar as congruências e eventuais divergências encontradas entre o que é aplicado em sua UEL e o proposto pelos Escoteiros do Brasil.","Observar a participação dos integrantes da seção nas cerimônias e relacionála com o desenvolvimento da progressão pessoal."]]],"r":["Os participantes da seção valorizam os momentos em que se reúnem para realizar cerimônias."]}]},{"x":9,"n":"Compreensão do Desenvolvimento de Crianças, Adolescentes e Jovens","l":[{"d":"Conhece as diferentes fases do desenvolvimento dos adolescentes e identifica os elementos que compõem o sistema de progressão","g":[["Comportamentos desejados",["Compreende o Ramo Sênior como uma fase de desenvolvimento dos adolescentes.","Percebe que as atividades da tropa são o espaço para o desenvolvimento global dos adolescentes, favorecendo o processo de desenvolvimento da autonomia.","Comunica-se adequadamente com os adolescentes da tropa sênior, orientando-os educativamente."]],["Atividades de desenvolvimento",["Ler o capítulo 1 (A Identidade Pessoal) do Manual do Escotista do Ramo Sênior.","Ler as regras 13, 53, 66, 84 e 102 do P.O.R."]]],"r":["A tropa é um espaço de crescimento pessoal para seus integrantes.","As atividades da seção estão adequadas à faixa etária de seus integrantes.","Há estímulo para o desenvolvimento do processo de autoconhecimento, aceitação e aprimoramento de características pessoais, o que favorece a vida em grupo."]},{"d":"Acompanha e registra as atividades de progressão pessoal realizadas pelos integrantes da seção sob sua orientação","g":[["Comportamentos desejados",["Realiza o registro no PAXTU das atividades realizadas pelos adolescentes que acompanha.","Conversa com os adolescentes sobre o seu desenvolvimento e os orienta a respeito de sua progressão pessoal.","Realiza o registro das conquistas dos adolescentes no PAXTU e os mantém atualizados."]],["Atividades de desenvolvimento",["Acompanhar, por pelo menos um ciclo de programa, a progressão pessoal de alguns adolescentes da sua tropa.","Antes do curso básico, ler os capítulos 9 do Manual do Escotista do Ramo Sênior.","Utilizar o aplicativo mAPPa como ferramenta para o acompanhamento da progressão pessoal."]]],"r":["A tropa possui um mapa (ou outra forma) de registro da progressão pessoal de todos os adolescentes, disponível para a ciência dos escotistas, da diretoria do GE e dos pais.","Os adolescentes sentem-se estimulados em sua progressão pessoal."]},{"d":"Orienta os demais escotistas sobre o acompanhamento da progressão pessoal dos adolescentes da Tropa","g":[["Comportamentos desejados",["Demonstra empatia diante situações apresentadas pelas crianças.","É capaz de dialogar e orientar as crianças sem ser diretivo.","Utiliza uma linguagem adequada na orientação às crianças."]],["Atividades de desenvolvimento",["Realizar a avaliação e o registro da progressão pessoal dos adolescentes que acompanha.","Conversar com os outros integrantes da equipe de escotistas sobre o acompanhamento da progressão pessoal."]],["Inclua no seu PPF",["Participar ativamente do processo de avaliação da progressão pessoal dos integrantes da seção utilizando linguagem apropriada.","Participar de uma Corte de Honra promovendo o bom diálogo entre os participantes, auxiliando nas avaliações necessárias."]]],"r":["Percebe-se o clima de confiança entre adultos e adolescentes."]}]},{"x":10,"n":"Segurança","l":[{"d":"Reconhece a importância da segurança nas atividades escoteiras, seguindo as orientações do P.O.R. nas atividades de seção","g":[["Comportamentos desejados",["Leva em conta, prioritariamente, os aspectos relacionados à segurança para organizar suas atividades.","Zela pela segurança dos seniores e guias durante as atividades da tropa.","Observa se todas as atividades da tropa preservam prioritariamente as regras de segurança."]],["Atividades de desenvolvimento",["Antes do curso preliminar, ler o capítulo 14 do P.O.R. (Segurança nas atividades escoteiras).","Ler o capítulo 15 do P.O.R. (Política de Proteção Infantojuvenil).","Realizar o Curso de Proteção Infanto-Juvenil dos Escoteiros do Brasil.","Solicitar, formalmente, autorização do responsável pela U.E.L. e autorização dos pais ou responsáveis para realizar atividade fora da sede."]]],"r":["Os pais e/ou responsáveis confiam nos escotistas na realização de atividades da tropa sênior.","A tropa realiza atividades estimulantes e notavelmente seguras.","A tropa é modelo de zelo e cuidado com os jovens."]},{"d":"Age de maneira imediata em situações potenciais ou reais de abusos ou maus tratos","g":[["Comportamentos desejados",["Zela pelos procedimentos de segurança dos Escoteiros do Brasil e conhece a Política de Proteção Infantojuvenil, agindo conforme suas diretrizes.","Orienta os integrantes da seção sobre as regras de segurança dos Escoteiros do Brasil.","Promove a Política de Proteção Infantojuvenil dos Escoteiros do Brasil."]],["Atividades de desenvolvimento",["Organizar/participar junto com os demais adultos da Unidade Escoteira, de um debate sobre o capítulo 15 do P.O.R.","Envolver e acompanhar os integrantes da seção na elaboração de um plano de segurança/emergência para uma atividade fora da sede.","Ensinar aos integrantes da seção os conteúdos relacionados aos primeiros socorros descritos no Programa Educativo do ramo.","Discutir com o APF os procedimentos a serem adotados em caso de suspeita de abuso."]]],"r":["A Unidade Escoteira é um ambiente seguro e de confiança para os responsáveis e jovens."]},{"d":"Toma as devidas precauções com os aspectos legais envolvidos nas atividades escoteiras","g":[["Comportamentos desejados",["Conhece suas responsabilidades e tem atitudes adequadas e educativas com os integrantes da seção.","É exemplo de conduta responsável.","Cumpre as recomendações da União dos Escoteiros do Brasil e respeita todas as determinações legais."]],["Atividades de desenvolvimento",["Ler o Estatuto da Criança e do Adolescente.","Antes do curso, ler o livro “Proteção da Criança e do Adolescente - Orientações sobre como Proteger e Prevenir Abusos - Manual para escotistas”.","Conduzir, em uma reunião de pais, uma conversa sobre prevenção a maus tratos e abusos."]],["Inclua no seu PPF",["Participar de um evento/ conversa sobre a política de Proteção Infantojuvenil dos Escoteiros do Brasil.","Conhecer as regras do POR sobre segurança.","Conhecer o livreto Padrões de Atividades Escoteiras.","Conhecer sobre a Política de segurança da OMME - Safe no Harm (a salvo do perigo).","Elaborar um formulário, ou revisar o formulário atual, da UEL para planejamento de atividades externas.","Debater com sua Seção a importância do Planejamento para atividades, destacando os pontos críticos de controle no que se refere a segurança de todos os participantes da atividade."]]],"r":["A tropa é um espaço de confiança para os pais","A tropa tem atividades seguras e que garantem a integridade de todos os seus participantes.","A tropa é exemplo no que diz respeito à atenção aos direitos dos adolescentes no ambiente escoteiro."]}]},{"x":11,"n":"Aplicação do Marco Simbólico","l":[{"d":"Identifica os elementos que compõe o marco simbólico do ramo","g":[["Comportamentos desejados",["Identifica as características que contextualizam a utilização do Marco Simbólico nas atividades do ramo.","Solicita orientação aos demais escotistas sobre a aplicação do Marco Simbólico.","Observa a a vivência do marco simbólico na seção, utilizando-o como referencial na sua percepção do dia a dia."]],["Atividades de desenvolvimento",["Ler o texto referente ao marco simbólico do Capítulo 2 do Manual do Escotista do Ramo Sênior.","Participar, junto com a equipe de escotistas, da aplicação de uma atividade com base no marco simbólico do Ramo Sênior."]]],"r":["As atividades da tropa têm caráter educativo e reúnem os símbolos do Ramo Sênior e Método Escoteiro.","As atividades da tropa são apoiadas no marco simbólico do Ramo Sênior: “Superar seus próprios desafios”."]},{"d":"Orienta e incentiva a vivência do marco simbólico do Ramo Sênior","g":[["Comportamentos desejados",["Contextualiza suas atividades, utilizando o marco simbólico do ramo, relacionando-o ao Programa Educativo.","Utiliza o marco simbólico, preocupando-se com suas ações e o impacto que ele gera entre os integrantes da tropa.","Utiliza elementos simbólicos no Ramo Sênior."]],["Atividades de desenvolvimento",["Aplicar uma atividade com base no marco simbolico no ramo.","Estimular a realização de atividades de patrulha com base no marco simbólico do Ramo Sênior."]]],"r":["As atividades da tropa motivam seus participantes na vivência de seu marco simbólico.","A vida em grupo na tropa revela a presença dos elementos que compõem o marco simbolico no ramo.","Os adolescentes compreendem e assimilam os valores propostos pelo Escotismo por meio das experiências vividas na tropa."]},{"d":"Cria atividades inspiradas no marco simbólico e nos símbolos do Ramo","g":[["Comportamentos desejados",["Organiza atividades utilizando o marco simbólico do ramo, relacionando-o com o Programa Educativo.","Utiliza o marco simbólico, preocupando-se com suas ações e o impacto que ele gera entre os integrantes da Tropa sênior.","Utiliza elementos simbólicos no Ramo Sênior."]],["Atividades de desenvolvimento",["Planejar e executar uma atividade para a tropa sênior, na qual se evidencie o marco simbólico.","Em uma reunião de pais, realizar um debate sobre a ênfase do Ramo Sênior."]],["Inclua no seu PPF",["Participar de uma conversa, sobre o marco simbólico do ramo e aplicar seus conceitos durante as atividades de seção.","Participar junto com a chefia de sua seção sobre uma reflexão sobre como estão aplicando o Marco Simbólico na seção, estudando as possíveis implementações para os próximos ciclos de programa."]]],"r":["Os adolescentes compreendem e assimilam os valores propostos pelo Escotismo a partir das vivências proporcionadas pelas atividades do ramo."]}]},{"x":12,"n":"Operação do Sistema de Especialidades e Insígnias","l":[{"d":"Identifica os elementos essenciais que compõem o sistema de especialidades, de Insígnias de Interesse Especial e modalidades","g":[["Comportamentos desejados",["Conhecer a literatura relacionada à conquista de Distintivos de Especialidades e Insígnias de Interesse Especial, orientando os adolescentes a terem contato com isso.","Participa de cerimônias de entrega de Distintivos de Especialidades e Insígnias de Interesse Especial.","Orienta os integrantes da seção sobre as especialidades e Insígnias de Interesse Especial."]],["Atividades de desenvolvimento",["Ler o Guia de Especialidades e das Insígnias de Interesse Especial e saber orientar sobre sua utilização.","Ler as regras 169, 170 e 171 e 173 do P.O.R."]]],"r":["Os escotistas conhecem os aspectos gerais e essenciais para a operação do sistema de especialidades e insígnias.","Os escotistas conhecem as regras de concessão das Insígnias de Modalidade."]},{"d":"Aplica o Sistema de Especialidades, da Insígnia da Modalidade e das Insígnias de Interesse Especial no Programa, incentivando sua conquista na Tropa","g":[["Comportamentos desejados",["Estimula os adolescentes a conquistarem Distintivos de Especialidade e Insígnias de Interesse Especial.","Compreende as especialidades como uma busca pessoal do jovem, de acordo com suas aptidões e interesses.","Auxilia na escolha de examinadores para a conquista de especialidades."]],["Atividades de desenvolvimento",["Realizar atividades que estimulem a conquista de especialidades.","Realizar uma atividade que estimule a conquista de Insígnias de Interesse Especial do Ramo Sênior.","Registrar a conquista de especialidades e insígnias dos adolescentes que acompanha.","Preencher de maneira adequada os certificados de conquista de insígnias e especialidades."]]],"r":["Os adolescentes desenvolvem especialidades em diversos ramos de conhecimento, tendo a oportunidade de desenvolverem-se de acordo com suas aptidões.","Os adolescentes sentem-se estimulados a conquistar especialidades e Insígnias de Interesse Especial.","Os adolescentes conversam com seus responsáveis sobre a conquista de distintivos."]},{"d":"Administra adequadamente a conquista de especialidades e insígnias pelos componentes da seção","g":[["Comportamentos desejados",["Realiza o acompanhamento das crianças que estão em processo de conquista de especialidades e insígnias.","Registra de maneira adequada as especialidades e insígnias conquistadas pelas crianças.","Realiza a entrega dos certificados e distintivos em tempo e maneira adequados."]],["Atividades de desenvolvimento",["Organizar o mapeamento geral de conquistas de especialidades e insígnias dos integrantes da seção.","Orientar os demais escotistas sobre o panorama de conquistas de especialidades e insígnias dos integrantes da seção.","Em uma reunião de pais, apresentar o sistema de especialidades e insígnias."]],["Inclua no seu PPF",["Conversar com outro adulto sobre ferramentas para realização do acompanhamento de especialidades e utilizá-lo em seu dia a dia.","Verificar se o mAPPa está sendo utilizado pelos integrantes da seção e se os adultos estão conseguindo acessar e acompanhar a progressão pelo aplicativo.","Avaliar, junto ao seu APF, a forma que realizou as entregas de distintivo, durante as atividades da seção.","Avalia a entrega de distintivos de sua seção para verificar se estão de acordo com o proposto pelos Escoteiros do Brasil."]]],"r":["A documentação e os registros da seção são preservados de maneira adequada e segura.","Os adolescentes são reconhecidos adequadamente e prontamente sobre suas conquistas."]}]},{"x":13,"n":"Envolvimento Comunitário","l":[{"d":"Descreve o conceito de envolvimento comunitário e as atividades propostas para o tema pelos Escoteiros do Brasil","g":[["Comportamentos desejados",["Conhece os materiais de referência para atividades comunitárias dos Escoteiros do Brasil.","Incentiva os adolescentes a realizarem e participarem de atividades de serviço à comunidade.","Participa da organização de atividades comunitárias dos Escoteiros do Brasil."]],["Atividades de desenvolvimento",["Ler a programação e as orientações de aplicação de uma edição do EducAção Escoteira e MUTCOM.","Participar de uma atividade comunitária juntamente com a tropa."]]],"r":["Os escoteiros compreendem a importância da realização de boas ações à comunidade.","A Unidade Escoteira Local faz-se presente na comunidade e busca reconhecimento por sua atuação."]},{"d":"Aplica e desenvolve atividades comunitárias de acordo com as orientações dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Participa da organização de atividades comunitárias dos Escoteiros do Brasil.","Incentiva os adolescentes a realizarem e participarem de atividades de serviço à comunidade.","Explica aos demais adultos da estrutura a importância da realização de atividades comunitárias."]],["Atividades de desenvolvimento",["Estimular a participação da seção em um Mutirão Nacional de Ação Comunitária ou EducAção Escoteira.","Organizar uma atividade de caráter comunitário além das citadas acima.","Estimular os jovens a conquistarem a Insígnia do Desafio Comunitário ou realizarem projetos para o Mensageiros da Paz.","Ler a publicação “Escotismo e Comunidade” e discuti-la com seu Assessor Pessoal de Formação."]]],"r":["Os escoteiros compreendem a importância da realização atividades comunitárias.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço relevante para o desenvolvimento comunitário."]},{"d":"Avalia a participação da seção em atividades de envolvimento comunitário e busca pontos de melhoria para as próximas participações","g":[["Comportamentos desejados",["Avalia a organização de atividades comunitárias dos Escoteiros do Brasil na Unidade Escoteira Local.","Incentiva as crianças a realizarem e participarem de atividades de serviço à comunidade.","Identifica pontos de melhoria para a organização de novas atividades de envolvimento comunitário na Unidade Escoteira Local."]],["Atividades de desenvolvimento",["Realizar, junto à equipe de escotistas, uma reunião de avaliação das atividades de desenvolvimento comunitário.","Orientar os jovens a avaliarem o impacto das atividades e projetos de desenvolvimento comunitário realizados pelas patrulhas ou seção, indicando pontos de melhoria."]],["Inclua no seu PPF",["Organizar/participar de uma conversa de avaliação sobre as atividades de Envolvimento Comunitário com os outros adultos da seção.","Avaliar como foi a aplicação e envolvimento da sua seção no MUTCOM.","Promover uma atividade de serviço à comunidade na seção, incentivando a participação da tropa sênior, buscando orientação na diretoria da UEL.","Organizar/participar de uma conversa de avaliação sobre as atividades de envolvimento comunitário com os outros adultos da seção.","Em uma Reunião do Conselho de Pais da seção, avaliar as possibilidades de atividades comunitárias, mapeando as iniciativas propostas para aumentar o impacto das ações da Seção."]]],"r":["Os adolescentes compreendem a importância da realização de atividades voltadas ao envolvimento comunitário.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço relevante para o desenvolvimento comunitário."]}]},{"x":14,"n":"Desenvolvimento Sustentável","l":[{"d":"Descreve o conceito de desenvolvimento sustentável e as atividades propostas para o tema pelos Escoteiros do Brasil.","g":[["Comportamentos desejados",["Conhece os materiais de referência para atividades de desenvolvimento sustentável dos Escoteiros do Brasil.","Incentiva os adolescentes a realizarem e participarem de atividades de desenvolvimento sustentável.","Conhece quais são os Objetivos do Desenvolvimento Sustentável."]],["Atividades de desenvolvimento",["Ler a programação e as orientações de aplicação de uma edição do MUTECO.","Participar de uma atividade relacionada ao desenvolvimento sustentável, junto com a tropa."]]],"r":["Os integrantes da seção compreendem a importância da realização de atividades que enfatizem as práticas para o desenvolvimento sustentável.","A Unidade Escoteira Local faz-se presente na comunidade e busca reconhecimento por sua atuação."]},{"d":"Aplica e desenvolve atividades sobre desenvolvimento sustentável e meio ambiente de acordo com as orientações dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Participa da organização de atividades que enfatizem a prática de ações para o desenvolvimento sustentável.","Incentiva os adolescentes a realizar e participar de atividades voltadas ao desenvolvimento sustentável.","Atualiza-se em relação à tendências e práticas sustentáveis."]],["Atividades de desenvolvimento",["Estimular a participação da seção em um Mutirão Nacional de Ação Ecológica, orientando os jovens quanto aos aspectos de sua organização.","Organizar uma atividade relacionada ao Desenvolvimento Sustentável além do MUTECO.","Estimular os integrantes da seção a conquistarem a Insígnia Mundial do Meio Ambiente."]]],"r":["Os integrantes da seção compreendem a importância da realização de atividades comunitárias ligadas aos ODS.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço relevante para o desenvolvimento Sustentável."]},{"d":"Avalia a participação da seção em atividades de desenvolvimento sustentável, buscando pontos de melhoria","g":[["Comportamentos desejados",["Avalia a organização de atividades dos Escoteiros do Brasil que enfatizem o desenvolvimento sustentável na Unidade Escoteira Local.","Incentiva as crianças a realizarem e participarem de atividades relacionadas ao desenvolvimento sustentável.","Identifica pontos e melhoria para a organização de novas atividades relacionadas ao desenvolvimento sustentável na Unidade Escoteira Local."]],["Atividades de desenvolvimento",["Realizar, junto à equipe de escotistas, uma reunião de avaliação das atividades relacionadas às práticas de desenvolvimento sustentável.","Ler o documento “Educação para os Objetivos de Desenvolvimento Sustentável”, da Unesco.","Orientar os jovens a avaliarem o impacto das atividades e projetos de desenvolvimento comunitário realizados pelas patrulhas ou seção, indicando pontos de melhoria."]],["Inclua no seu PPF",["Organizar/participar de uma conversa de avaliação sobre as atividades de Desenvolvimento Sustentável com os outros adultos da seção.","Avaliar como foi a aplicação e envolvimento da sua seção no MUTECO.","Promover uma atividade sobre desenvolvimento sultentável na seção, incentivando a participação dos jovens, buscando a orientação da Direotria da UEL.","Organizar/participar de uma conversa de avaliação sobre as atividades de desenvolvimento sustentável com os outros adultos da seção.","Em uma Reunião do Conselho de Pais da seção, avaliar as possibilidades de atividades de desenvolvimento sustentável, mapeando as iniciativas propostas para aumentar o impacto das ações da seção."]]],"r":["Os integrantes da seção compreendem a relação entre os Objetivos do Desenvolvimento Sustentável e suas formas de interação com o mundo que os cerca.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço de referência em práticas de desenvolvimento sustentável."]}]},{"x":15,"n":"Aplicação do Sistema de Equipes","l":[{"d":"Descreve os elementos que compõem o Sistema de Patrulhas","g":[["Comportamentos desejados",["Conhece os elementos essenciais que embasam o Sistema de Patrulhas.","Entende a tropa como ambiente natural para o desenvolvimento das atividades no Ramo Sênior.","Incentiva as patrulhas a terem seus símbolos."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 5 do Manual do Escotista do Ramo Sênior.","Orientar os monitores para que as patrulhas tenham encargos dentro e fora da sede.","Orientar os monitores para que as patrulhas tenham livros de patrulha, bandeirola e e grito, além de utilizar seu distintivo de patrulha."]]],"r":["Os adolescentes nas patrulhas têm encargos na sede e em atividades fora da sede.","As patrulhas na tropa têm livros de patrulha.","Os integrantes da tropa utilizam distintivos de patrulha.","As patrulhas têm elementos simbólicos, tais como bandeirola, grito e cores."]},{"d":"Aplica o Sistema de Patrulhas na tropa sênior, de acordo com o orientado no Manual do Escotista do Ramo Sênior","g":[["Comportamentos desejados",["Incentiva as patrulhas para a realização de Conselhos, Atividades de Patrulhas, Eleições de Monitores e Sub-Monitores.","Estimula frequentemente a realização de atividades de patrulha.","Realiza a ação educativa durante os Conselhos de Patrulha, Assembleias de Tropa e Corte de Honra."]],["Atividades de desenvolvimento",["Orientar os monitores para que as patrulhas realizem a eleição de monitores e submonitores.","Orientar as patrulhas sobre a realização de atividades de patrulha dentro ou fora da sede.","Atuar educativamente nas reuniões da Corte de Honra previstas no calendário.","Atuar educativamente nas Assembleias de Tropa previstas no calendário."]]],"r":["Os monitores operam as atividades da seção por meio das orientações dos escotistas.","As patrulhas realizam atividades de patrulha (tanto na sede quanto fora) com regularidade.","As reuniões da Corte de Honra são realizadas com regularidade e contam com a correta intervenção educativa dos escotistas."]},{"d":"Orienta os demais escotistas na correta aplicação do Sistema de Patrulhas no Ramo Sênior","g":[["Comportamentos desejados",["Entende a tropa sênior como espaço natural para o desenvolvimento das atividades do Ramo Sênior.","Proporciona o ambiente necessário para o autodesenvolvimento das crianças da tropa sênior.","Orienta os demais escotistas sobre as maneiras de aplicar o sistema de equipes no ramo."]],["Atividades de desenvolvimento",["Em um Conselho de Pais, apresentar as características do Sistema de Patrulhas.","Orientar os demais escotistas sobre a realização de Conselhos de Patrulha, Assembleias de Tropa e Corte de Honra.","Orientar e auxiliar os monitores no planejamento e execução de excursões e acampamentos de patrulha."]],["Inclua no seu PPF",["Participar de uma conversa sobre a vida em grupo no Ramo Sênior e aplicar seus conceitos durante as atividades da seção.","Avaliar a atuação das matilhas refletindo no desenvolvimento de cada integrante."]]],"r":["Os escotistas recebem a orientação adequada sobre a aplicação do Sistema de Patrulhas."]}]},{"x":16,"n":"Domínio do Programa Educativo","l":[{"d":"Identifica as seis áreas de desenvolvimento do Programa Educativo","g":[["Comportamentos desejados",["Participa junto dos demais escotistas da seção da organização de atividades nas seis áreas de desenvolvimento.","Identifica quais são as 6 áreas de desenvolvimento do Programa Educativo.","Colabora no registro das atividades da seção."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 6 (Áreas de desenvolvimento), do Manual do Escotista do Ramo Sênior.","Ler o capítulo 7 e 10 do P.O.R.","Ler o Livro Escotistas em Ação, Ramo Sênior."]]],"r":["São realizadas na U.E.L. atividades nas seis áreas de desenvolvimento."]},{"d":"Aplica atividades atraentes, progressivas e variadas nas seis áreas de desenvolvimento, organizadas de acordo com a ênfase definida pelo Ciclo de Programa","g":[["Comportamentos desejados",["Aplica atividades atraentes, progressivas e variadas no Ramo Sênior.","Pesquisa por atividades relacionadas às áreas de desenvolvimento.","Orienta educativamente os adolescentes da seção no cumprimento das atividades do Programa Educativo, conforme definidas no ciclo de programa."]],["Atividades de desenvolvimento",["Aplicar atividades em todas as áreas de desenvolvimento e registrá-las adequadamente.","Ler o capítulo 8 (O Ciclo de Programa), do Manual do Escotista do Ramo Sênior.","Participar de todas as fases de desenvolvimento de um Ciclo de Programa, de acordo com as orientações do Manual do Escotista do Ramo."]]],"r":["As atividades fixas e variáveis consideram todas as áreas de desenvolvimento."]},{"d":"Avalia a aplicação das atividades do programa educativo e orienta os demais escotistas","g":[["Comportamentos desejados",["Avalia as atividades organizadas na seção.","Orienta a realização de atividades relacionadas às áreas de desenvolvimento.","Orienta os demais integrantes da Tropa sênior sobre os processos de avaliação da progressão pessoal."]],["Atividades de desenvolvimento",["Conversar com o APF sobre os resultados da avaliações das atividades desenvolvidas e buscar novas ideias a partir dos pontos de melhoria identificados.","Ler a Política Nacional de Programa Educativo.","Conduzir corretamente, em conjunto com os jovens, processos de avaliação das atividades realizadas pela seção."]],["Inclua no seu PPF",["Realizar, com seus pares, momentos de avaliação das diversas atividades da seção.","Rever com sua Equipe de trabalho se as atividades estão relacionadas às áreas de desenvolvimento e, se necessário, reler o capítulo do Manual do escotista que versa sobre o tema.","Realizar reuniões com sua Equipe de trabalho para orientá-los sobre os processos de avaliação da progressão pessoal na Tropa sênior.","Em uma reunião com sua equipe de trabalho, avaliar se todos os pontos do método escoteiro estão sendo trabalhados, fazendo eventuais sugestões de como melhorar a aplicação de algum dos pontos."]]],"r":["As atividades fixas e variáveis consideram todas as áreas de desenvolvimento.","A administração da seção está em dia e a documentação em ordem."]}]},{"x":17,"n":"Campismo e Vida ao Ar Livre","l":[{"d":"Reconhece Reconhece a a importância importância da da vida vida ao ao ar ar livre livre para para as as atividades atividades escoteiras escoteiras","g":[["Comportamentos desejados",["Relaciona adequadamente a utilização de técnicas de campismo e vida ao ar livre a atividades educativas.","Colabora com os demais escotistas na promoção de atividades que contribuam para o aprendizado de técnicas de campo para os adolescentes.","Identifica adequadamente os materiais necessários para os diversos tipos de atividades de campismo e vida ao ar livre."]],["Atividades de desenvolvimento",["Aplicar os seguintes nós: Direito, Volta do Fiel, Volta da Ribeira, Nó de Escota, Escota Alceado, Nó em Oito, Volta Redonda com Dois Cotes, Catau, Lais de Guia, Cadeira de Bombeiro, saber falcaçar cabos e transmiti-los utilizando o Sistema de Patrulhas.","Distribuir corretamente o material dentro de uma mochila e ensinar para a tropa utilizando o sistema de patrulhas."]]],"r":["Os escotistas da seção valorizam a realização de acampamentos e atividades ao ar livre na seção.","São realizadas atividades ao ar livre na seção."]},{"d":"Seleciona e aplica técnicas de campismo adequadas às atividades do Programa Educativo do Ramo Sênior","g":[["Comportamentos desejados",["Aplica tecnicas de campo e proporciona vivências educativas a partir destes recursos aos adolescentes.","Planeja atividades que contribuam para o aprendizado de técnicas de campo para os adolescentes.","Orienta os integrantes da seção na realização de atividades e tarefas refrentes ao campismo e à vida ao ar livre."]],["Atividades de desenvolvimento",["Utilizando o Sistema de Patrulha ensinar para a tropa: Utilizar e conservar o fogareiro e lampião, realizar uma receita de comida mateira e acender uma fogueira. Utilizar ferramentas de sapa e corte, as amarras Quadrada, Diagonal, Paralela e Tripé e montar uma barraca. Os Sinais de Pistas e sua utilização.","Ler o livro “Padrões de atividades escoteiras.”","Saber estimar alturas e distâncias utilizando métodos distintos, assim como ensiná-los à tropa, utilizando o sistema de Patrulhas.","Saber os seguintes nós: Pescador, oito, correr, Balso pelo Seio, Volta do Salteador, nó de andaime, boca de lobo e volta do enfardador e ensinar para tropa utilizando o Sistema de Patrulha."]]],"r":["Os integrantes da tropa assumem responsabilidades e sabem como resolver pequenos problemas em acampamentos.","Os integrantes da tropa participam com entusiasmo dos acampamentos e atividades ao ar livre.","Os integrantes da tropa apresentam bom aproveitamento na realização das técnicas de campo previstas no Programa Educativo do Ramo.","São realizadas atividades ao ar livre na seção."]},{"d":"Avalia a execução da prática de técnicas de campismo e vida ao ar livre e orienta sobre sua correta aplicação","g":[["Comportamentos desejados",["Aplica técnicas de campo e proporciona vivências educativas, a partir destes recursos, às crianças.","Planeja atividades que contribuam para o aprendizado de técnicas de campo para as crianças.","Orienta os demais escotistas da equipe na execução de atividades ao ar livre e aplicação de técnicas de campismo."]],["Atividades de desenvolvimento",["Organizar uma jornada com a seção e avaliá-la junto à equipe de escotistas e a Corte de Honra.","Aplicar os conceitos básicos de estruturas (cavaletes, encaixes, ancoragens) nos projetos e montagem de construções como pontes, balsas etc.","Utilizando o sistema de Patrulha ensinar a tropa a construir um abrigo natural.","Utilizando o Sistema de Patrulha ensinar as patrulhas a montarem uma barraca suspensa e orientar-las sobre como utilizar mapas e bússolas.","Orientar as patrulhas sobre como utilizar as técnicas de previsão de tempo por indícios naturais.","Orientar os jovens a avaliarem as atividades realizadas pelas patrulhas ou pela seção, indicando pontos de melhoria.","Ensinar a técnica do percurso de Gilwell, utilizando o Sistema de Patrulhas.","Ensinar técnicas de leitura e orientação de cartas topográficas, com auxílio de bússola, utilizando o Sistema de Patrulhas.","Saber confeccionar as amarras Quadrada Japonesa e Diagonal Filipina e ensinar a tropa utilizando o sistema de Patrulha."]],["Inclua no seu PPF",["Participar de um módulo ou outro momento de capacitação a respeito de técnicas de campo, aplicando seus conceitos nas reuniões da seção.","Conversar com sua equipe de trabalho sobre o equilíbrio de atividades ao ar livre dentro dos ciclos de programas propostos.","Em uma reunião de pais, expor a importância de atividades ao ar livre para o Movimento escoteiro, destacando os benefícios que essa prática traz para o desenvolvimento dos jovens."]]],"r":["A equipe de escotistas recebe a orientação adequada para a aplicação de atividades ao ar livre.","As atividades ao ar livre são avaliadas e sua execução é constantemente aperfeiçoada."]}]},{"x":18,"n":"Organização de Atividades","l":[{"d":"Identifica os tipos de atividade (fixas e variáveis), planejando e executando reuniões semanais e gerando experiências educativas","g":[["Comportamentos desejados",["Participa dos encontros de planejamento das reuniões semanais, contribuindo com sugestões.","Dirige algumas atividades das reuniões semanais e apoia a realização das demais.","Reconhece pontos positivos e negativos durante a execução das atividades realizadas."]],["Atividades de desenvolvimento",["Ler o livro “Os Primeiros Meses de uma tropa sênior”.","Participar das reuniões da tropa sênior, contribuindo em seu planejamento, execução e avaliação."]]],"r":["As reuniões semanais são dinâmicas e animadas.","As reuniões semanais são organizadas e com materiais disponíveis e preparados previamente.","Há um bom índice de assiduidade nas reuniões semanais da tropa."]},{"d":"Diferencia os cuidados de planejamento entre reuniões e atividades fora da sede","g":[["Comportamentos desejados",["Cuida da organização das atividades fora da sede realizando todos os passos que garantam sua realização de maneira segura e educativa.","Compartilha previamente a programação das atividades com a equipe de escotistas.","Informa antecipadamente os participantes da seção e seus responsáveis sobre a realização de atividades fora da sede."]],["Atividades de desenvolvimento",["Responsabilizar-se pela organização de uma atividade aventureira na seção.","Participar da organização e da execução de um Fogo de Conselho.","Orientar os monitores quanto ao planejamento de um cardápio para um acampamento de patrulha ou de seção.","Participar do planejamento de um acampamento da seção.","Organizar uma excursão com a tropa e participar da avaliação junto da equipe de escotistas e jovens.","Ler o livro “Fogo de Conselho”."]]],"r":["As atividades da seção são seguras e tem seu caráter educativo preservado.","As atividades fora da sede são organizadas e com materiais sempre disponíveis e preparados.","Há um bom índice de assiduidade nas atividades realizadas fora da sede."]},{"d":"Orienta os demais adultos sobre os tipos de atividade (fixas e variáveis), auxiliando- -os em sua execução e condução","g":[["Comportamentos desejados",["Avalia o planejamento e execução de atividades dentro e fora da sede, buscando pontos de melhoria para próximas atividades.","Orienta os demais escotistas da seção no planejamento e execução de atividades dentro e fora da sede.","Planeja atividades variadas, de acordo com a ênfase identificada durante a execução do ciclo de programa."]],["Atividades de desenvolvimento",["Realizar reuniões de avaliação das atividades junto à equipe de escotistas e discutir suas impressões sobre as atividades com o APF.","Organizar um Acampamento Volante com a tropa."]],["Inclua no seu PPF",["Preparar um plano de execução de atividades e tê-lo aprovado pela diretoria da UEL.","Realizar reuniões de avaliação e orientação dos demais escotistas quanto à realização de atividades ao ar livre.","Reavaliar, junto à sua equipe, o calendário de atividades e verificar se as atividades estão de acordo com a ênfase definida durante a preparação do ciclo de programa."]]],"r":["Os integrantes da tropa participam com entusiasmo dos acampamentos e atividades ao ar livre.","São realizadas atividades ao ar livre na seção.","Os escotistas recebem orientação adequada para a realização de atividades de campismo e vida ao ar livre.","As atividades fora da sede são organizadas e com materiais sempre disponíveis e preparados."]}]}]}]},"pio":{"n":"Pioneiro","g":[{"t":"Competências essenciais","c":[{"x":0,"n":"Gestão de Mudanças","l":[{"d":"Demonstra disposição de aprender formas diferentes de fazer as coisas","g":[["Comportamentos desejados",["Aceita outras formas de fazer as coisas.","Mantém uma atitude positiva quando tem que mudar de ideia, conceitos, tarefas ou funções.","Busca informações sobre as mudanças e obtém informações que permitam compreendê-las."]],["Atividades de desenvolvimento",["Ler o documento “Características Essenciais do Movimento Escoteiro” e debater com seu APF as impressões sobre o documento.","Ler o capítulo “História do Escotismo”, do livro “Escotistas em ação - Ramo Pioneiro”."]]],"r":["Os voluntários lidam de maneira receptiva com as mudanças da organização."]},{"d":"Analisa e implementa ações para a gestão de mudanças","g":[["Comportamentos desejados",["Aplica procedimentos de maneira flexível quando as circunstâncias exigem.","Toma decisões de maneira autônoma como resposta a situações de transformação.","É criativo e inovador no desempenho de suas funções."]],["Atividades de desenvolvimento",["Trabalhar junto com sua equipe ações que promovam a inovação em rotinas de sua função."]]],"r":["Os fluxos e processos da estrutura são constantemente revisados e aprimorados."]},{"d":"Avalia e projeta ações de mudança na estrutura em que atua","g":[["Comportamentos desejados",["Antecipa riscos emergentes e aproveita oportunidades para satisfazer as necessidades futuras.","Modifica procedimentos padronizados em resposta a ambientes em transformação.","Cria novos modelos e metodologias organizacionais em resposta a novos contextos, condições e situações."]],["Atividades de desenvolvimento",["Organizar ações de melhoria e desenvolvimento contínuo na estrutura em que atua, tais como projetos, campanhas de comunicação e inovações em processos."]],["Inclua no seu PPF",["Promover em seu grupo uma discussão sobre alguma nova publicação ou resolução da UEB lançadas no último ano.","Propor alguma alteração ou adequação de procedimento no seu nível de atuação visando atender às transformações do ambiente.","Identificar uma nova situação e propor um plano de implantação para as mudanças sugeridas, ressaltando os controles que devem ser tidos para evitar os antigos hábitos.","Desenvolver pesquisas sobre o uso de novas tecnologias na metodologia organizacional.","Organizar ações de melhoria e desenvolvimento contínuo na estrutura em que atua, tais como projetos, campanhas de comunicação e inovações em processos."]]],"r":["Em momentos de mudança, os voluntários já se sentem preparados para adaptarem-se e promoverem as ações necessárias para a sua implantação."]}]},{"x":1,"n":"Aprendizagem e Desenvolvimento Pessoal","l":[{"d":"Expressa interesse e comprometimento com sua capacitação para a função que exerce","g":[["Comportamentos desejados",["Observa e aprende com os demais.","Participa de cursos, módulos e outras iniciativas de formação, inerentes ao seu cargo ou função.","Como voluntário, buscar esclarecer suas dúvidas em relação ao desempenho de sua função com o APF."]],["Atividades de desenvolvimento",["Em conjunto com o APF, preparar o seu Plano Pessoal de Formação.","Participar do Curso Preliminar.","Ler e discutir com o APF a descrição do Cargo de Assessor Pessoal de Formação."]]],"r":["Os voluntários são comprometidos com seus processos de atualização.","Os adultos da U.E.L. têm APFs nomeados pela Diretoria da Estrutura."]},{"d":"Analisa os resultados de sua aprendizagem e compartilha seus conhecimentos e experiências com os demais","g":[["Comportamentos desejados",["Atua como agente promotor de novas ideias e tecnologias.","Motiva os demais na participação em processos de melhoria contínua, ajudando no desenvolvimento de suas tarefas e crescimento pessoal","Aplica ao seu trabalho novas aprendizagens que enriquecem suas ações"]],["Atividades de desenvolvimento",["Realizar a revisão de seu PPF.","Participar do Curso Básico.","Ler o Guia do Chefe Escoteiro de Baden-Powell.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função.","Participar do curso em EAD sobre Assessor Pessoal de Formação ou outra iniciativa sobre o tema."]]],"r":["Os voluntários da estrutura compartilham informações sobre suas experiências de formação.","Os voluntários da estrutura aplicam novos conceitos às ações empregadas."]},{"d":"Avalia seus próprios resultados e realiza ações para melhorar seu desempenho continuamente","g":[["Comportamentos desejados",["Analisa seus próprios resultados e estabelece planos de ações para sua melhora.","Aproveita as mudanças organizacionais como oportunidades para desenvolver novos conhecimentos e habilidades.","Utiliza suas próprias experiências como aprendizados que compartiilha abertamente com os demais."]],["Atividades de desenvolvimento",["Realizar a revisão do seu PPF.","Organizar ações para que os demais voluntários participem de iniciativas de formação e atualização.","Participar do Curso Avançado.","Conversar com o seu APF sobre a História da Insígnia de Madeira e Gilwell Park.","Ler a Politica Nacional de Adultos no Movimento Escoteiro.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função."]],["Inclua no seu PPF",["Fazer anotações pessoais e avaliar se as atividades planejadas foram cumpridas e se as propostas foram realizadas, identificando oportunidades de autodesenvolvimento.","Fazer um levantamento dos projetos que estão sendo realizados pela UEB, que possam ser agregados como metodologia de desenvolvimento e melhoria no nível em que atua.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função.","Promover um debate junto ao nível em que atua sobre as atualizações propostas pela União dos Escoteiros do Brasil, vinculando as experiências vividas e desenvolvidas no último ano.","Desenvolver e manter um arquivo pessoal com projetos realizados e resgatá-los com os ajustes sempre que necessário."]]],"r":["Os voluntários promovem momentos de autoavaliação e compartilhamento de impressões sobre seu próprio desenvolvimento, gerando um clima de aprendizado contínuo."]}]},{"x":2,"n":"Compromisso","l":[{"d":"Aceita voluntariamente os fundamentos do Escotismo e cumpre suas tarefas com responsabilidade","g":[["Comportamentos desejados",["Vincula o propósito, os princípios, os valores e a missão do Movimento Escoteiro às suas atividades cotidianas.","Assume como próprios o propósito, os princípios, os valores e a missão do Movimento Escoteiro.","Atua de acordo com a orientação espiritual dos Escoteiros do Brasil no exercício de sua função."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 1 do P.O.R.","Conversar com seu APF, identificando os quatro itens que compõem os fundamentos do Escotismo (definição, propósito, princípios e método).","Realizar sua Promessa Escoteira.","Ler o capítulo 3 do P.O.R., “Orientação espiritual”."]]],"r":["As responsabillidades são distribuídas e cumpridas de maneira adequada."]},{"d":"Assume voluntariamente novas responsabilidades adicionais à correspondente ao seu cargo, atuando de acordo com os fundamentos do Escotismo","g":[["Comportamentos desejados",["Compartilha o significado do propósito, dos princípios, dos valores e da missão do Movimento Escoteiro a ambientes exteriores aos da organização","Assessora e guia os demais na realização de suas tarefas.","Dá andamento aos seus compromissos e reconhece as ações que deve implementar para seu cumprimento."]],["Atividades de desenvolvimento",["Organizar/Participar com a equipe de adultos da estrutura, de grupos de debates sobre as diversas funções existentes no Movimento Escoteiro.","Organizar/Participar de ações de captação de novos adultos para o Movimento Escoteiro.","Ler o Projeto Educativo da União dos Escoteiros do Brasil"]]],"r":["Os voluntários compartilham os valores do Movimento Escoteiro em ambientes externos à organização.","Os voluntários recebem a orientação e o suporte necessários para a implementação do propósito, princípio, valores e missão do Movimento Escoteiro."]},{"d":"Implementa ações para promover o compromisso de outros adultos dos Escoteiros do Brasil aos fundamentos do Escotismo","g":[["Comportamentos desejados",["Gera espaços que fomentem a iniciativa e responsabilidades em momentos críticos.","É disciplinado e consciente no uso de recursos para o cumprimento de suas ações.","Dedica uma porcentagem de seu tempo a revisão dos planos de trabalho, objetivos e sua contribuição nestas tarefas."]],["Atividades de desenvolvimento",["Ler o Manual de Reconhecimento dos Escoteiros do Brasil."]],["Inclua no seu PPF",["Elaborar uma forma de dividir tarefas promovendo a avaliação de situações vividas pelo grupo e diferentes formas de se abordar momentos críticos.","Desenvolver propostas e métodos para melhoria na execução do planejamento das atividades no tocante ao uso de recursos.","Organizar com a equipe de adultos da estrutura, de grupos de debates sobre o uso de recursos para o cumprimento de ações.","Apresentar a revisão crítica de planos de trabalho executados nos últimos 6 meses, buscando apresentar sugestões de melhorias.","Apresentar um cronograma de desenvolvimento de ações futuras, evitando o acúmulo de atividades a serem realizadas."]]],"r":["Os voluntários são devidamente reconhecidos pelo seu compromisso e comprometimento.","São organizados momentos para revisão dos planos de trabalho e discussão sobre a distribuição de tarefas entre os voluntários."]}]},{"x":3,"n":"Consciência Organizacional","l":[{"d":"Identifica as estruturas da organização, especialmente o funcionamento e os objetivos do nível em que atua","g":[["Comportamentos desejados",["Conhece a história e os avanços mais relevantes da organização.","Conhece e identifica a estrutura da organização nos níveis local e regional.","Conhece os direitos e deveres inerentes ao seu cargo/função."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 5 do título 2 do Estatuto da União dos Escoteiros do Brasil e o Capítulo 5 do P.O.R."]]],"r":["Os voluntários conhecem a estrutura do nível que atuam e suas competências."]},{"d":"Desenvolve ações para a promoção de maior sentido de unidade e propósito comum nas ações da estrutura em que atua","g":[["Comportamentos desejados",["Implementa procedimentos organizacionais para a resolução de problemas.","Aplica os princípios de governança dentro da instituição.","Promove permanentemente as práticas democráticas e o respeito às diferenças."]],["Atividades de desenvolvimento",["Promover as políticas organizacionais dos Escoteiros do Brasil em grupos de debate e discussões, juntamente com a equipe da qual faz parte.","Ler o Estatuto dos Escoteiros do Brasil.","Participar de eventos distritais, regionais ou nacionais."]]],"r":["Os processos de escolha e renovação de lideranças estão de acordo com as recomendações das Políticas e orientações da Organização Mundial do Movimento Escoteiro.","São promovidas práticas de exercício da democracia e respeito às diferenças na estrutura."]},{"d":"Avalia e implementa ações para a conscientização de voluntários sobre a importância da estrutura institucional do Movimento Escoteiro","g":[["Comportamentos desejados",["Promove o sentido de unidade e propósito comum entre os diferentes níveis da Organização.","Compreende o impacto da sociedade civil, governo, setor privado, terceiro setor e outros grupos de interesse externos no cumprimento da missão da Organização.","Conhece a estrutura do Escotismo Mundial."]],["Atividades de desenvolvimento",["Explicar aos demais voluntários as relações entre as estruturas e níveis da organização.","Participar de uma assembleia regional ou nacional.","Ler as resoluções do CAN e DEN e debater com o APF ou grupo de discussão sobre os documentos."]],["Inclua no seu PPF",["Promover dentro do nível em que atua um debate sobre os diferentes níveis institucionais da União dos Escoteiros do Brasil, buscando compreender a atuação de cada um.","Promover as políticas organizacionais dos Escoteiros do Brasil em grupos de debate e discussões, juntamente com a equipe da qual faz parte.","Conhecer as propostas atuais sobre voluntariado definidas pelo Sistema público e terceiro setor, avaliar as necessidades de adaptação do nível em que atua.","Propor ações em parcerias com outras ONGS, entidades privadas e governamentais, visando o cumprimento da missão de nossa organização.","Apresentar aos membros do nível em que atua uma pesquisa sobre a estrutura do escotismo mundial, resumindo pelo menos uma política regional ou mundial."]]],"r":["Os voluntários têm a compreensão da importância das estruturas da organização e promovem boas práticas e o diálogo entre elas.","Os voluntários têm a compreensão da importância da boa relação que o Movimento Escoteiro deve ter com as demais instituições."]}]},{"x":4,"n":"Planejamento Estratégico","l":[{"d":"Identifica as responsabilidades e objetivos da função que desempenha","g":[["Comportamentos desejados",["Atua de acordo com as funções atribuidas a seu cargo, com a tarefa que lhe é designada.","Conhece o plano de trabalho da equipe da qual faz parte.","Solicita a assessoria necessária para o estabelecimento de planos de trabalho referentes a sua função."]],["Atividades de desenvolvimento",["Assinar o acordo de trabalho voluntário contendo a descrição das funções pertinentes ao cargo ao qual está designado."]]],"r":["Os voluntários da estrutura compartilham as responsabilidades necessárias para o desenvolvimento das atividades."]},{"d":"Planeja atividades e tarefas inerentes ao seu cargo ou função","g":[["Comportamentos desejados",["Formula planos de ação, considerando os objetivos de longo prazo, as metas e os planos da organização.","Presta assessoria em função dos planos de trabalho a curto, médio e longo prazo.","Estabelece pontos de controle, gerando dados e informações para o acompanhamento dos objetivos e prazos."]],["Atividades de desenvolvimento",["Ler o documento “Perfis: cargos e funções”, do nível em que atua.","Participar da concepção do calendário de atividades da estrutura em que atua."]]],"r":["Os voluntários da estrutura trabalham na concepção e revisão de planos de trabalho, monitorando seus resultados."]},{"d":"Compreende como sua atuação contribui para o alcance dos objetivos do Planejamento Estratégico dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Avalia periodicamente os resultados considerando fatores internos e externos críticos para o cumprimento dos seus planos e atividades.","Desenvolve diagnósticos de seus resultados e toma medidas em correspondência com seus resultados.","Propõe ações de melhora aos planos estratégicos e de ação da estrutura que faz parte."]],["Atividades de desenvolvimento",["Ler o Planejamento Estratégico dos Escoteiros do Brasil.","Participar do planejamento da sua Unidade Escoteira Local, considerando os objetivos anuais da sua seção."]],["Inclua no seu PPF",["Realizar sessão de avaliação visando identificar a influência de fatores internos e externos e se o planejamento proposto está sendo realizado, verificando a necessidade de adequação.","Estudar ao menos uma ferramenta de diagnóstico e, a utilizando, apresentar um estudo sobre quais ações devo realizar na resolução de problemas e desenvolvimento de um projeto em andamento.","Analisar o plano estratégico do nível que atua propondo ações de melhoria.","Participar do planejamento da sua Unidade Escoteira Local, considerando os objetivos anuais do nível em que atua."]]],"r":["Os voluntários são devidamente reconhecidos pelo seu compromisso e comprometimento.","São organizados momentos para revisão dos planos de trabalho e discussão sobre a distribuição de tarefas entre os voluntários."]}]},{"x":5,"n":"Relações Interpessoais","l":[{"d":"Identifica quais são as condutas referenciais de cortesia, respeito e confiança desejadas aos adultos dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Trata os demais com respeito, aceita as diferenças de pensamento e expressão das emoções.","Interage socialmente com outros, seguindo as normas básicas de cortesia.","Refere-se em termos positivos aos demais e sobre o trabalho que realizam."]],["Atividades de desenvolvimento",["Ler e discutir com seu Assessor Pessoal de Formação a definição do Movimento Escoteiro - Regra 001 do P.O.R."]]],"r":["A relação entre os voluntários é respeitosa e baseada em ações de cortesia.","Existe uma cultura de respeito à diversidade."]},{"d":"Desenvolve ações favorecendo as boas relações de trabalho cooperativo entre os adultos, inclusive com os responsáveis dos jovens","g":[["Comportamentos desejados",["É coerente em suas ações e seus resultados.","Promove a participação dos integrantes do clã pioneiro e o diálogo intergeracional.","Escuta pontos de vista dos demais e modifica sua própria perspectiva, quando necessário."]],["Atividades de desenvolvimento",["Participar da organização de, pelo menos, um conselho de pais.","Participar de uma seção de avaliação sobre o seu próprio trabalho e receber as críticas de maneira aberta e construtiva."]]],"r":["Há envolvimento e preocupação por parte dos voluntários para que os conflitos existentes sejam mediados e solucionados."]},{"d":"Avalia sua relação com os demais e busca alternativas para fortalecê-las, baseadas em compreensão e flexibilidade","g":[["Comportamentos desejados",["Demonstra proatividade no momento de prestar apoio aos acontecimentos que requerem esforços integrados.","Sabe criticar ideias sem ofender pessoalmente quem as expressa.","Demonstra não tomar as palavras ou situações de maneira pessoal."]],["Atividades de desenvolvimento",["Planejar ações de integração entre pessoas e áreas de trabalho, promovendo o fortalecimento das relações","Prestar adequadamente avaliações sobre os componentes de sua equipe de trabalho"]],["Inclua no seu PPF",["Propor um projeto para a UEL que deva ser realizado com integração das diferentes equipes que a compõe.","Procurar desenvolver atividades com outras pessoas da UEL não membros da sua equipe, buscando um olhar diferenciado na dinâmica possibilitando o fortalecimento e a boa comunicação interna do nível em que atua.","Planejar atividades de integração entre as equipes ou a novos integrantes a sua equipe de atuação.","Identificar formas de escuta e reflexão antes de criticar outras pessoas da equipe ou da UEL","Planejar ações de integração entre pessoas e áreas de trabalho, promovendo o fortalecimento das relações.","Prestar adequadamente avaliações sobre os componentes de sua equipe de trabalho.","Promover um debate sobre empatia e comunicação não violenta.","Desenvolver uma metodologia para dar oportunidade de ouvir todos os membros da equipe antes de tomar decisões ou propor ações, levando em consideração que as soluções devem sempre estar voltadas para o interesse do grupo e não para os interesses individuais."]]],"r":["Os voluntários são pró-ativos na resolução de conflitos entre adultos da organização.","Os voluntários posicionam-se de maneira adequada e sensata, gerando um clima de confiança mútua."]}]},{"x":6,"n":"Trabalho em Equipe","l":[{"d":"Reafirma a importância do trabalho em equipe, cooperando com os participantes de seu grupo de trabalho","g":[["Comportamentos desejados",["Assume seu papel/tarefas designadas com responsabilidade.","Ajuda em outras tarefas além das quais é responsável, quando necessário.","Expressa-se em termos positivos a sua equipe."]],["Atividades de desenvolvimento",["Participar de, pelo menos, um Conselho de Chefes da Unidade Escoteira Local."]]],"r":["As tarefas/projetos são desenvolvidas coletivamente e seus resultados são compartilhados."]},{"d":"Desenvolve projetos e as competências da equipe de trabalho que compõe","g":[["Comportamentos desejados",["Conhece as fortalezas e pontos de melhoria dos integrantes da equipe.","Proporciona ou assegura o apoio necessário para o desenvolvimento da equipe.","Gera um clima de trabalho que promove o espírito e a cooperação da equipe com outras equipes."]],["Atividades de desenvolvimento",["Cumprir com as responsabilidades inerentes a sua função (Registro no PAXTU, acompanhamento da progressão pessoal, aplicação de jogo/atividade, realização de cerimônia etc.)"]]],"r":["Os voluntários têm facilitado o apoio para o desenvolvimento de seus projetos mediante o trabalho em equipe.","A comunicação entre os voluntários da estrutura tem fluxos ágeis e definidos."]},{"d":"Avalia os resultados atingidos pela equipe de trabalho que compõe e estimula ações para sua melhoria","g":[["Comportamentos desejados",["Avalia as fortalezas e pontos de melhoria da equipe e seus integrantes para propor ações de melhora.","Avalia abertamente sua própria participação e contribuição nos resultados da equipe.","Permite aos demais a participação na construção da visão dos resultados que se esperam pela equipe."]],["Atividades de desenvolvimento",["Avaliar as ações desenvolvidas pela sua equipe em reuniões periódicas, com a colaboração dos demais participantes da equipe."]],["Inclua no seu PPF",["Promover momentos de autoavaliação das ações e atuação da equipe perante as necessidades de um projeto em desenvolvimento, identificando as fortalezas e pontos de melhoria de cada membro da equipe.","Avaliar periodicamente com os membros do nível em que atua as ações realizadas e refletir sobre as causas do não cumprimento, identificando como posso melhor contribuir para os resultados da equipe.","Avaliar as ações desenvolvidas por você em reuniões periódicas, com a colaboração dos demais participantes da equipe.","Propor diferentes modos para que todos da equipe possam participar dos processos de construção e desenvolvimento de projetos, inclusive assumindo diferentes funções."]]],"r":["Os voluntários realizam processos de avaliação em equipe e propõem estratégias para suas ações."]}]}]},{"t":"Competências específicas","c":[{"x":7,"n":"Aplicação de Jogos e Canções","l":[{"d":"Identifica as características que compõem os jogos e atividades educativas no clã, apoiando os pioneiros na sua realização","g":[["Comportamentos desejados",["Pesquisa sobre os diferentes tipos de jogos, canções e atividades educativas existentes.","Orienta para que sejam realizados jogos, canções e atividades educativas adequados aos diversos momentos e situações no clã pioneiro.","Entende os jogos e canções como recurso educativo."]],["Atividades de desenvolvimento",["Compartilhar com o clã pioneiro as técnicas que tornam os Jogos, Canções e Atividades educativas mais dinâmicas e bem planejadas.","Aplicar em conjunto com o clã Pioneiro jogos, canções e atividades educativas."]]],"r":["Os pioneiros são orientados pelos escotistas na aplicação de jogos, canções e atividades educativas.","Os escotistas tem compreensão sobre seu papel durante a aplicação de jogos, canções e atividades educativas.","As reuniões do clã pioneiro são atraentes e geram resultados educativos nos participantes da seção."]},{"d":"Analisa a aplicação de jogos e atividades educativas no clã pioneiro, debatendo com os pioneiros suas oportunidades de desenvolvimento pessoal","g":[["Comportamentos desejados",["Auxilia os participantes da seção na seleção adequada de atividades de acordo com as necessidades do clã.","Promove debates com o clã a respeito dos resultados alcançados após a execução de jogos, canções e atividades educativas.","Compartilha com o clã as responsabilidades na execução de jogos, canções e atividades educativas."]],["Atividades de desenvolvimento",["Orientar os pioneiros na aplicação de jogos diversos (ativo, técnico, cooperativo, noturno, grande jogo etc.)","Realizar debates com a seção após a execução de atividades educativas, discutindo os resultados alcançados."]]],"r":["As responsabilidades atribuídas aos participantes da seção são claras e promovem a execução adequada das atividades.","Os participantes do clã têm uma atuação participativa no processo de execução de jogos, canções e atividades educativas.","As atividades da seção geram momentos de debate e análise."]},{"d":"Orienta os pioneiros sobre a criação e aplicação de jogos e atividades educativas que contribuam para a conquista de competências","g":[["Comportamentos desejados",["Cria jogos e canções adequados à faixa etária do ramo.","Orienta sobre a aplicação de jogos e canções adequados aos diversos momentos e situações no Clã Pioneiro.","Administra seu próprio arquivo/acervo de jogos e canções e o compartilha com os demais integrantes da equipe de escotistas."]],["Atividades de desenvolvimento",["Orientar os integrantes da seção na criação/adaptação de jogos, canções e atividades educativas que contribuam em todas as áreas de desenvolvimento.","Colaborar com a atualização de arquivo de jogos, canções e atividades educativas da seção.","Identificar as características que contribuem para que os participantes da seção desenvolvam suas competências durante a aplicação de jogos e canções."]],["Inclua no seu PPF",["Participar de uma iniciativa de formação sobre criação de jogos e canções.","Fazer uma leitura de livros e manuais de jogos e canções aplicadas para crianças.","Aprimorar a criação de jogos e canções, selecionando atividades interessantes para aplicar na sua seção.","Promover na seção um momento de reflexão entre os escotistas sobre a aplicação de jogos e canções e como essa prática pode ser aperfeiçoada.","Ter uma conversa com o APF sobre que ferramentas podem ser utilizadas para a gestão e arquivo de Jogos e Canções Escoteiras."]]],"r":["O clã gera atividades atraentes, progressivas e variadas adequadas às suas necessidades.","A equipe de escotistas junto com o clã realiza análises dos resultados das atividades e os utiliza como subsídio para o planejamento de suas atividades e orientação educativa."]}]},{"x":8,"n":"Condução de Cerimônias","l":[{"d":"Identifica as vozes de comando no clã pioneiro e conduz as cerimônias da seção","g":[["Comportamentos desejados",["Comunica-se com os pioneiros utilizando vozes de comando corretamente.","Demonstra boa organização na preparação do local e dos materiais necessários para a realização das cerimonias do clã.","Transmite as informações com segurança quando coordena uma cerimônia."]],["Atividades de desenvolvimento",["Antes do curso preliminar, assistir os vídeos da série “Como se Faz?”","Conduzir uma cerimônia de hasteamento/arriamento na seção.","Realizar uma entrega de distintivo de progressão/Insígnia de Interesse Especial na seção."]]],"r":["Auxilia os outros adultos e jovens na realização de Cerimônias na sessão.","As cerimônias são significativas e personalizadas para cada um de seus participantes."]},{"d":"Conduz cerimônias de promessa, investidura, partida e entrega de distintivos especiais de maneira adequada","g":[["Comportamentos desejados",["Auxilia os outros adultos na realização de cerimônias na seção.","Orienta os integrantes da seção sobre a participação adequada em cerimônias escoteiras.","Compreende as cerimônias como um espaço educativo e inclusivo na prática do escotismo."]],["Atividades de desenvolvimento",["Ler o manual de cerimônias dos Escoteiros do Brasil e discutir com seu Assessor Pessoal de Formação.","Conduzir uma cerimônia de promessa.","Conduzir uma cerimonia de partida e investidura.","Realizar uma entrega de distintivo/insígnia de Interesse Especial ou Distintivo de Insígnia de B-P.","Em parceria com o chefe da Tropa Sênior/Guia conduzir uma cerimônia de Passagem de Ramo."]]],"r":["As cerimônias são adequadas, realizadas em momento oportuno, local apropriado e são estimulantes.","Os pioneiros compreendem o papel dos padrinhos/madrinhas em sua vida como pioneiros.","Os Pioneiros sentem-se corresponsáveis pelo sucesso das cerimônias.","Os escotistas da seção conseguem atuar como mediadores no sentido de aproximar a realidade do Pioneiro no desenvolvimento das competências."]},{"d":"Orienta os demais integrantes da equipe quanto à realização de cerimônias, zelando pelo caráter educativo","g":[["Comportamentos desejados",["Conduz adequadamente o processo de passagem entre ramos dos integrantes do Clã Pioneiro.","Orienta os demais adultos da seção na realização de cerimônias.","Compreende as cerimônias escoteiras como um momento educativo e inclusivo da prática do escotismo."]],["Atividades de desenvolvimento",["Orientar outro adulto na condução de cerimônias típicas do ramo (partida e investidura)."]],["Inclua no seu PPF",["Participar de uma cerimônia de passagem em conjunto com outros escotistas e observar se a cerimônia guarda as características previstas no Manual de Cerimônias dos Escoteiros do Brasil.","Observar outros escotistas na aplicação de cerimônias e transmitir informações para que as realizem corretamente e com segurança.","Analisar as cerimônias realizadas na seção, e assim avaliar as congruências e eventuais divergências encontradas entre o que é aplicado em sua UEL e o proposto pelos Escoteiros do Brasil.","Observar a participação dos integrantes da seção nas cerimônias e relacionála com o desenvolvimento da progressão pessoal."]]],"r":["Os participantes da seção valorizam os momentos que se reúnem para realizar cerimônias.","Os pioneiros sentem-se responsáveis pelo sucesso das cerimônias estimulando a participação de toda a seção.","Os Pioneiros se apoiam mutuamente no desenvolvimento das competências.","Os Pioneiros são os principais interessados em seu crescimento pessoal."]}]},{"x":9,"n":"Compreensão sobre o Desenvolvimento de Crianças, Adolescentes e Jovens","l":[{"d":"Conhece as diferentes fases do desenvolvimento dos pioneiros e identifica os elementos que compõem o sistema de progressão","g":[["Comportamentos desejados",["Compreende o Ramo Pioneiro como uma fase de desenvolvimento dos jovens adultos.","Percebe que as atividades do clã são o espaço para o desenvolvimento global das crianças, favorecendo a vida em grupo.","Comunica-se adequadamente com pioneiros, orientando-as educativamente."]],["Atividades de desenvolvimento",["Ler o capítulo 1 do Manual do Escotista do Ramo Pioneiro.","Ler as regras 13, 53, 66, 84 e 102 do P.O.R."]]],"r":["O clã é um espaço de crescimento pessoal para seus integrantes.","As atividades da seção estão adequadas à faixa etária de seus integrantes.","Há estímulo para o desenvolvimento do processo de autoconhecimento, aceitação e aprimoramento das características pessoais, favorecendo a vida em grupo."]},{"d":"Acompanha e registra as atividades de progressão pessoal realizadas pelos integrantes da seção sob sua orientação","g":[["Comportamentos desejados",["Realiza o registro no PAXTU das atividades realizadas pelos pioneiros que acompanha.","Conversa com os pioneiros sobre o seu desenvolvimento e os orienta a respeito de sua progressão pessoal.","Realiza o registro das conquistas dos pioneiros no PAXTU e os mantêm atualizados."]],["Atividades de desenvolvimento",["Acompanhar por pelo menos um ciclo de programa a progressão pessoal de alguns pioneiros do clã.","Acompanhar um pioneiro na execução de um projeto nos campos de ação prioritários.","Utilizar o aplicativo mAPPa como ferramenta para o acompanhamento da progressão pessoal."]]],"r":["Os pioneiros sentem-se estimulados em sua progressão pessoal."]},{"d":"Orienta os demais escotistas sobre o acompanhamento da progressão pessoal dos jovens do clã","g":[["Comportamentos desejados",["Demonstra empatia diante situações apresentadas pelas crianças.","É capaz de dialogar e orientar as crianças sem ser diretivo.","Utiliza uma linguagem adequada na orientação às crianças."]],["Atividades de desenvolvimento",["Realizar a avaliação e registro da progressão pessoal dos pioneiros","Conversar com os outros integrantes da equipe de escotistas sobre o acompanhamento da progressão pessoal."]],["Inclua no seu PPF",["Participar ativamente do processo de avaliação da progressão pessoal dos integrantes da seção utilizando linguagem apropriada.","Participar de uma Reunião da COMAD promovendo o bom diálogo entre os participantes, auxiliando nas avaliações necessárias."]]],"r":["Percebe-se o clima de confiança entre adultos e pioneiros.","Os Pioneiros são os principais interessados em seu crescimento pessoal."]}]},{"x":10,"n":"Segurança","l":[{"d":"Reconhece a importância da segurança nas atividades escoteiras, seguindo as orientações do P.O.R. nas atividades da seção","g":[["Comportamentos desejados",["Leva em conta prioritariamente os aspectos relacionados à segurança para organizar suas atividades.","Zela pela segurança dos pioneiros durante as atividades.","Observa se todas as atividades do clã, preservam prioritariamente as regras de segurança."]],["Atividades de desenvolvimento",["Antes do curso, ler o capítulo 14 do P.O.R. (segurança nas atividades escoteiras)","Ler o capítulo 15 do P.O.R. (Política de Proteção Infanto-Juvenil)","Realizar o Curso de Proteção Infanto-Juvenil dos Escoteiros do Brasil.","Solicitar formalmente autorização da Diretoria do Grupo Escoteiro para realizar atividade fora da sede."]]],"r":["O clã realiza atividades estimulantes e notavelmente seguras.","O clã é modelo de zelo e cuidado com os jovens."]},{"d":"Age de maneira imediata em situações potenciais ou reais de risco à integridade física, abusos ou maus tratos","g":[["Comportamentos desejados",["Zela pelos procedimentos de segurança dos Escoteiros do Brasil e conhece a política de proteção infantojuvenil, agindo conforme suas diretrizes.","Orienta os integrantes da seção sobre as regras de segurança dos e Escoteiros do Brasil.","Promove a Política de Proteção Infantojuvenil dos Escoteiros do Brasil."]],["Atividades de desenvolvimento",["Organizar/participar junto com os demais adultos da Unidade Escoteira, de um debate sobre o capítulo 15 do P.O.R.","Envolver e acompanhar os integrantes da seção na elaboração de um plano de segurança/emergência para uma atividade fora da sede.","Ensinar aos integrantes da seção os conteúdos relacionados aos primeiros socorros descritos no Programa Educativo do ramo.","Discutir com o APF os procedimentos a serem adotados em caso de suspeita de abuso."]]],"r":["A Unidade Escoteira é um ambiente seguro e de confiança para os responsáveis e jovens."]},{"d":"Toma as devidas precauções com os aspectos legais envolvidos nas atividades escoteiras","g":[["Comportamentos desejados",["Conhece suas responsabilidades e tem atitudes adequadas e educativas com os integrantes da seção.","É exemplo de conduta responsável.","Cumpre as recomendações da União dos Escoteiros do Brasil e respeita todas as determinações legais."]],["Atividades de desenvolvimento",["Ler o Estatuto da Criança e do Adolescente.","Antes do curso, ler o livro “Proteção da Criança e do Adolescente - Orientações sobre como Proteger e Prevenir Abusos”."]],["Inclua no seu PPF",["Participar de um evento/ conversa sobre a política de Proteção Infantojuvenil dos Escoteiros do Brasil.","Conhecer as regras do POR sobre segurança.","Conhecer o livreto Padrões de Atividades Escoteiras.","Conhecer sobre a Política de segurança da OMME - Safe no Harm (a salvo do perigo).","Elaborar um formulário, ou revisar o formulário atual, da UEL para planejamento de atividades externas.","Debater com sua Seção a importância do Planejamento para atividades, destacando os pontos críticos de controle no que se refere a segurança de todos os participantes da atividade."]]],"r":["O clã tem atividades seguras e que garantem a integridade de todos os seus participantes."]}]},{"x":11,"n":"Aplicação do Marco Simbólico","l":[{"d":"Identifica os elementos que compõe o marco simbólico do Ramo","g":[["Comportamentos desejados",["Identifica as características que contextualizam a utilização do marco simbólico nas atividades do ramo.","Solicita orientação aos demais escotistas sobre a aplicação do marco simbólico.","Observa como se dá a vivência do marco simbólico no dia a dia da seção."]],["Atividades de desenvolvimento",["Ler o texto referente ao marco simbólico do Capítulo 2 do Manual do Escotista do Ramo Pioneiro.","Participar, junto com a equipe de escotistas e clã, da aplicação de uma atividade com base no marco simbólico do Ramo Pioneiro."]]],"r":["As atividades do clã tem caráter educativo e reúnem os símbolos do Ramo e Método Escoteiro.","As atividades do clã são apoiadas no marco simbólico do Ramo “Tenho um projeto para a minha vida”."]},{"d":"Orienta e incentiva a vivência do marco simbólico do Ramo Pioneiro","g":[["Comportamentos desejados",["Contextualiza suas atividades utilizando o marco simbólico do Ramo, relacionando-o com o Programa Educativo.","Utiliza o marco simbólico, preocupando-se com suas ações e o impacto que ele gera entre os integrantes do clã pioneiro.","Utiliza elementos simbólicos no Ramo Pioneiro."]],["Atividades de desenvolvimento",["Orientar os Pioneiros na aplicação de uma atividade com base no marco simbólico do Ramo.","Acompanhar um pioneiro no planejamento do seu projeto de vida.","Orientar os pioneiros na elaboração de uma atividade que trabalhe as virtudes pioneiras com o Clã."]]],"r":["A vida de grupo no clã revela a presença dos marcos simbólicos do Ramo Pioneiro."]},{"d":"Orienta e incentiva a vivência do marco simbólico e a utilização dos símbolos do Ramo que atua","g":[["Comportamentos desejados",["Organiza atividades utilizando o marco simbólico do ramo, relacionando-o com o Programa Educativo.","Utiliza o marco simbólico, preocupando-se com suas ações e o impacto que ele gera entre os integrantes do Clã Pioneiro.","Utiliza elementos simbólicos no Ramo Pioneiro."]],["Atividades de desenvolvimento",["Orientar os pioneiros na criação e aplicação de uma atividade baseada no marco simbólico do ramo.","Acompanhar atualização frequente do Projeto de Vida dos pioneiros do clã."]],["Inclua no seu PPF",["Participar de uma conversa, sobre o marco simbólico do ramo e aplicar seus conceitos durante as atividades de seção.","Participar junto com a chefia de sua seção sobre uma reflexão sobre como estão aplicando o Marco Simbólico na seção, estudando as possíveis implementações para os próximos ciclos de programa."]]],"r":["A vida de grupo no clã revela a presença dos marcos simbólicos do Ramo Pioneiro.","O clã pioneiro compreende a importância do marco simbólico “Tenho um projeto para minha vida” como norteador de suas ações, tanto dentro do movimento escoteiro, quanto na sua vida pessoal."]}]},{"x":12,"n":"Operação do Sistema de Insígnias de Interesse Especial","l":[{"d":"Identifica os elementos essenciais que compõem o sistema de Insígnias de Interesse Especial","g":[["Comportamentos desejados",["Conhece a literatura relacionada à conquista de Insígnias de Interesse Especial, orientando os pioneiros a terem contato com isso.","Participa de cerimônias de entrega de Insígnias de Interesse Especial.","Orienta os integrantes da seção sobre as Insígnias de Interesse Especial."]],["Atividades de desenvolvimento",["Ler a regra 171 do P.O.R."]]],"r":["Os pioneiros sentem-se estimulados a conquistar Insígnias de Interesse Especial."]},{"d":"Incentiva a conquista de Insígnias de Interesse Especial no clã","g":[["Comportamentos desejados",["Estimula os pioneiros a conquistarem insígnias de interesse Especial.","Orienta os pioneiros na conquista de Insígnias de Interesse Especial.","Orienta os pioneiros na realização de atividades que estimulem a conquista de Insígnias de Interesse Especial."]],["Atividades de desenvolvimento",["Orientar o clã na realização de atividades que estimulem a conquista das Insígnias de Interesse Especial.","Registrar a conquista de insígnias de Interesse Especial dos pioneiros que acompanha.","Preencher de maneira adequada os certificados de conquista de insígnias de Interesse Especial."]]],"r":["Os Pioneiros sentem-se estimulados a conquistar Insígnias de Interesse Especial."]},{"d":"Administra adequadamente a conquistas de insígnias de interesse especial pelos componentes da seção","g":[["Comportamentos desejados",["Realiza o acompanhamento das crianças que estão em processo de conquista de especialidades e insígnias.","Registra de maneira adequada as especialidades e insígnias conquistadas pelas crianças.","Realiza a entrega dos certificados e distintivos em tempo e maneira adequados."]],["Atividades de desenvolvimento",["Organizar o mapeamento geral de conquistas de Insígnias de Interesse Especial dos integrantes da seção.","Orientar os demais escotistas sobre o panorama de conquistas de Insígnias de Interesse Especial dos integrantes da seção.","Orientar o clã pioneiro na elaboração e execução de um projeto para a conquista de uma Insígnias de Interesse Especial."]],["Inclua no seu PPF",["Conversar com outro adulto sobre ferramentas para realização do acompanhamento de especialidades e utilizá-lo em seu dia a dia.","Verificar se o mAPPa está sendo utilizado pelos integrantes da seção e se os adultos estão conseguindo acessar e acompanhar a progressão pelo aplicativo.","Avaliar, junto ao seu APF, a forma que realizou as entregas de distintivo, durante as atividades da seção.","Avalia a entrega de distintivos de sua seção para verificar se estão de acordo com o proposto pelos Escoteiros do Brasil."]]],"r":["A documentação e os registros da seção são preservados de maneira adequada e segura.","Os pioneiros são reconhecidos adequadamente e prontamente sobre suas conquistas."]}]},{"x":13,"n":"Envolvimento Comunitário","l":[{"d":"Descreve o conceito de envolvimento comunitário e as atividades propostas para o tema pelos Escoteiros do Brasil","g":[["Comportamentos desejados",["Conhece os materiais de referência para atividades comunitárias dos Escoteiros do Brasil e a iniciativa Mensageiros da Paz.","incentiva os pioneiros a realizarem e participarem de atividades de serviço a comunidade.","Participa da organização de atividades comunitárias."]],["Atividades de desenvolvimento",["Ler a programação e as orientações de aplicação de uma edição do EducAção Escoteira e MUTCOM.","Participar de uma atividade comunitária em conjunto com o Clã Pioneiro na comunidade onde está localizada a UEL."]]],"r":["Os pioneiros se interessam pelo desenvolvimento de projetos comunitários.","A Unidade Escoteira Local faz-se presente na comunidade e busca reconhecimento por sua atuação."]},{"d":"Aplica e desenvolve atividades comunitárias, de acordo com as orientações do Manual do Escotista","g":[["Comportamentos desejados",["Orienta os pioneiros na organização de atividades comunitárias dos Escoteiros do Brasil.","Incentiva os pioneiros a realizarem e participarem de atividades de serviço à comunidade.","Explica ao Clã e demais adultos da estrutura a importância da realização de atividades comunitárias."]],["Atividades de desenvolvimento",["Orientar o clã pioneiro na organização e execução de um Mutirão Nacional de Ação Comunitária ou EducAção Escoteira.","Orientar o clã pioneiro na organização e execução de uma atividade de serviço comunitário em uma localidade diferente daquela onde está inserida a UEL.","Ler a publicação “Distintivo Mensageiros da Paz” e a publicação “Escotismo e Comunidade”."]]],"r":["Os integrantes do clã compreendem a importância da realização de atividades comunitárias.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço relevante para o desenvolvimento comunitário.","Os pioneiros desenvolvem e implementam projetos de impacto na comunidade."]},{"d":"Avalia junto à equipe de escotistas e COMAD a participação da seção em atividades de desenvolvimento sustentável","g":[["Comportamentos desejados",["Avalia a organização de atividades comunitárias dos Escoteiros do Brasil na Unidade Escoteira Local.","Incentiva as crianças a realizarem e participarem de atividades de serviço à comunidade.","Identifica pontos de melhoria para a organização de novas atividades de envolvimento comunitário na Unidade Escoteira Local."]],["Atividades de desenvolvimento",["Orientar os pioneiros a avaliarem o impacto das atividades e projetos de desenvolvimento comunitário realizados pelas Equipes de Interesse ou Clã Pioneiro, indicando pontos de melhoria.","Orientar os pioneiros e equipes de interesse a desenvolverem projetos comunitários/Mensageiro da Paz para atender demandas da comunidade do entorno."]],["Inclua no seu PPF",["Organizar/participar de uma conversa de avaliação sobre as atividades de Envolvimento Comunitário com os outros adultos da seção.","Avaliar como foi a aplicação e envolvimento da sua seção no MUTCOM.","Promover uma atividade de serviço à comunidade na seção, incentivando a participação do Clã Pioneiro, buscando orientação na diretoria da UEL.","Organizar/participar de uma conversa de avaliação sobre as atividades de envolvimento comunitário com os outros adultos da seção.","Em uma Reunião do Conselho de Pais da seção, avaliar as possibilidades de atividades comunitárias, mapeando as iniciativas propostas para aumentar o impacto das ações da Seção."]]],"r":["Os integrantes do clã compreendem a importância da realização atividades voltadas ao desenvolvimento comunitário.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço de referência em práticas de desenvolvimento comunitário."]}]},{"x":14,"n":"Desenvolvimento Sustentável","l":[{"d":"Descreve o conceito de desenvolvimento sustentável e as atividades propostas para o tema pelos Escoteiros do Brasil","g":[["Comportamentos desejados",["Conhece os materiais de referência para atividades de desenvolvimento sustentável dos Escoteiros do Brasil.","Incentiva os integrantes do Clã a realizarem e participarem de atividades de desenvolvimento sustentável.","Conhece o que são os objetivos do desenvolvimento sustentável."]],["Atividades de desenvolvimento",["Ler a programação e as orientações de aplicação de uma Edição do MUTECO.","Participar de uma atividade relacionada ao desenvolvimento sustentável juntamente com o clã pioneiro."]]],"r":["Os pioneiros compreendem a importância da realização de atividades que enfatizem as práticas para o desenvolvimento sustentável.","A Unidade Escoteira Local faz-se presente na comunidade e busca reconhecimento por sua atuação."]},{"d":"Aplica e acompanha o desenvolvimento de atividades sobre desenvolvimento sustentável e meio ambiente de acordo com as orientações dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Participa da organização de atividades que enfatizem a prática de ações para o desenvolvimento sustentável.","Incentiva os pioneiros a realizarem e participarem de atividades voltadas ao desenvolvimento sustentável.","Atualiza-se em relação à tendências e práticas sustentáveis."]],["Atividades de desenvolvimento",["Orientar o clã pioneiro na organização e execução de um MUTECO.","Orientar o clã pioneiro na organização e execução de uma atividade ou projeto relacionado ao desenvolvimento sustentável, além da citada acima."]]],"r":["Os integrantes da seção compreendem a importância da realização de atividades relacionadas ao desenvolvimento sustentável.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço relevante para o desenvolvimento Sustentável."]},{"d":"Avalia junto à equipe de escotistas e COMAD a participação da seção em atividades de desenvolvimento sustentável e busca pontos de melhoria","g":[["Comportamentos desejados",["Avalia a organização de atividades dos Escoteiros do Brasil que enfatizem o desenvolvimento sustentável na Unidade Escoteira Local.","Incentiva as crianças a realizarem e participarem de atividades relacionadas ao desenvolvimento sustentável.","Identifica pontos e melhoria para a organização de novas atividades relacionadas ao desenvolvimento sustentável na Unidade Escoteira Local."]],["Atividades de desenvolvimento",["Orientar os jovens a avaliarem o impacto das atividades e projetos de desenvolvimento sustentável realizados pelo clã, indicando pontos de melhoria.","Ler o documento “Educação para os Objetivos de Desenvolvimento Sustentável”, da UNESCO."]],["Inclua no seu PPF",["Organizar/participar de uma conversa de avaliação sobre as atividades de Desenvolvimento Sustentável com os outros adultos da seção.","Avaliar como foi a aplicação e envolvimento da sua seção no MUTECO.","Promover uma atividade sobre desenvolvimento sultentável na seção, incentivando a participação dos pioneiros, buscando a orientação da Direotria da UEL.","Organizar/participar de uma conversa de avaliação sobre as atividades de desenvolvimento sustentável com os outros adultos da seção.","Em uma Reunião do Conselho de Pais da seção, avaliar as possibilidades de atividades de desenvolvimento sustentável, mapeando as iniciativas propostas para aumentar o impacto das ações da seção."]]],"r":["Os integrantes da seção compreendem a relação entre os Objetivos do Desenvolvimento Sustentável e suas formas de interação com o mundo que os cerca.","A Unidade Escoteira Local é reconhecida pela comunidade como um espaço de referência em práticas de desenvolvimento sustentável."]}]},{"x":15,"n":"Aplicação do Sistema de Equipes","l":[{"d":"Descreve os elementos que compõem o conceito de vida em equipe no Ramo","g":[["Comportamentos desejados",["Conhece os elementos essenciais que embasam o sistemas de equipe no Ramo.","Entende o clã como ambiente natural para o desenvolvimento das atividades do Ramo Pioneiro.","Incentiva e colabora com o trabalho da COMAD e equipes de interesse."]],["Atividades de desenvolvimento",["Antes do Curso preliminar, ler o capítulo 5 do Manual do Escotista do Ramo Pioneiro.","Ler a Carta Pioneira e discuti-la com seu APF."]]],"r":["A vida em equipe no clã acontece de acordo com os conceitos apresentados no Manual do Escotista do Ramo Pioneiro.","Os pioneiros compreendem seu papel no desempenho das equipes interesse e a COMAD no desenvolvimento de suas ações."]},{"d":"Garante a aplicação do sistema de equipes na seção de acordo com o orientado no Manual do Escotista do Ramo Pioneiro","g":[["Comportamentos desejados",["Valoriza a autonomia da COMAD e das equipes de interesse.","Atua educativamente na resolução de confitos entre os integrantes da seção.","Proporciona o ambiente necessário para o autodesenvolvimento dos jovens do clã pioneiro."]],["Atividades de desenvolvimento",["Auxiliar os pioneiros na realização de um conselho/assembleia de clã.","Estimular e orientar a criação de equipes de interesse.","Acompanhar uma reunião de conselho de clã, participando quando solicitado."]]],"r":["Os pioneiros assumem responsabilidades conscientes de seus papéis nas atividades do clã e em suas vidas pessoais.","São realizados conselhos de clã e projetos das equipes de interesse."]},{"d":"Orienta os demais Escotistas e apoia a COMAD no emprego dos conceitos da vida em equipe no Ramo Pioneiro","g":[["Comportamentos desejados",["Entende o Clã Pioneiro como espaço natural para o desenvolvimento das atividades do Ramo Pioneiro.","Proporciona o ambiente necessário para o autodesenvolvimento dos jovens do Clã Pioneiro.","Orienta os demais escotistas sobre as maneiras de aplicar o sistema de equipes no ramo."]],["Atividades de desenvolvimento",["Orientar os pioneiros para revisão periódica da Carta Pioneira.","Acompanhar o trabalho das equipes de interesse e COMAD, gerando planos de melhoria."]],["Inclua no seu PPF",["Participar de uma conversa sobre a vida em grupo no Ramo Pioneiro e aplicar seus conceitos durante as atividades da seção.","Avaliar a atuação das matilhas refletindo no desenvolvimento de cada integrante."]]],"r":["Os escotistas recebem a orientação adequada sobre a aplicação do sistema de equipes na seção.","Os pioneiros atuam com eficiência no sistema de equipes do Ramo."]}]},{"x":16,"n":"Domínio do Programa Educativo","l":[{"d":"Identifica as seis áreas de desenvolvimento do Programa Educativo","g":[["Comportamentos desejados",["Participa junto dos demais escotistas e pioneiros da seção na organização de atividades nas seis áreas de desenvolvimento.","Identifica quais são as seis áreas de desenvolvimento do Programa Educativo.","Identifica quais são os quatro campos de atuação prioritários em projetos no ramo pioneiro (serviço, natureza, trabalho e viagem)."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 3 e 4 do Manual do Escotista do Ramo Pioneiro.","Ler o capítulo 7 e 11 do P.O.R.","Ler o Livro Escotistas em Ação, Ramo Pioneiro."]]],"r":["São realizadas no clã atividades nas seis áreas de desenvolvimento.","Os escotistas e pioneiros compreendem que os projetos devem ser realizados nos quatro campos prioritários."]},{"d":"Aplicar em conjunto com o clã atividades atraentes, progressivas e variadas nas 6 áreas de desenvolvimento, de acordo com a ênfase definida pelo ciclo de programa","g":[["Comportamentos desejados",["Aplica, junto dos demais escotistas e pioneiros da seção, atividades nas seis áreas de desenvolvimento, de forma atraente, progressiva e variada.","Pesquisa de acordo com a necessidade local atividades nas seis áreas de desenvolvimento do Programa Educativo.","Motiva os jovens na atuação em projetos envolvendo os quatro campos de atuação prioritários (serviço, natureza, trabalho e viagem)."]],["Atividades de desenvolvimento",["Em conjunto com o clã, aplicar atividades em todas as áreas de desenvolvimento e registrá-las adequadamente.","Ler o capítulo 6 do Manual do Escotista do Ramo Pioneiro.","Participar de todas as etapas do ciclo de programa, dando autonomia aos jovens.","Apoiar a criação/orientação de um projeto do clã."]]],"r":["As atividades consideram todas as áreas de desenvolvimento.","São desenvolvidos projetos nos quatro campos de atuação prioritários."]},{"d":"Avalia a aplicação das atividades do programa educativo e orienta os demais escotistas","g":[["Comportamentos desejados",["Avalia as atividades organizadas na seção.","Orienta a realização de atividades relacionadas às áreas de desenvolvimento.","Orienta os demais integrantes da Clã Pioneiro sobre os processos de avaliação da progressão pessoal."]],["Atividades de desenvolvimento",["Conversar com o APF sobre os resultados das avaliações das atividades desenvolvidas e buscar novas ideias a partir dos pontos de melhorias identificado.","Conduzir corretamente, em conjunto com os jovens, processos de avaliação das atividades realizadas pela seção.","Ler a Política Nacional de Programa Educativo."]],["Inclua no seu PPF",["Realizar, com seus pares, momentos de avaliação das diversas atividades da seção.","Rever com sua Equipe de trabalho se as atividades estão relacionadas às áreas de desenvolvimento e, se necessário, reler o capítulo do Manual do escotista que versa sobre o tema.","Realizar reuniões com sua Equipe de trabalho para orientá-los sobre os processos de avaliação da progressão pessoal no Clã Pioneiro.","Em uma reunião com sua equipe de trabalho, avaliar se todos os pontos do método escoteiro estão sendo trabalhados, fazendo eventuais sugestões de como melhorar a aplicação de algum dos pontos."]]],"r":["A equipe de escotistas recebe orientação adequada na aplicação do programa educativo do Ramo.","A aplicação dos projetos, nos quatro campos de atuação prioritários, ocorre de maneira adequada às necessidades locais."]}]},{"x":17,"n":"Campismo e Vida ao Ar Livre","l":[{"d":"Reconhece Reconhece a a importância importância da da vida vida ao ao ar ar livre livre para para as as atividades atividades escoteiras escoteiras","g":[["Comportamentos desejados",["Relaciona adequadamente a utilização de técnicas de campismo e vida ao ar livre a atividades educativas.","Colabora com os demais escotistas na promoção de atividades que contribuam para o aprendizado de técnicas de campo para os adolescentes.","Incentiva o clã a realizar atividades que envolvam técnicas de campismo."]],["Atividades de desenvolvimento",["Saber os seguintes nós: Direito, Volta do Fiel, Volta da Ribeira, Nó de Escota, Escota Alceado, Nó em Oito, Volta Redonda com Dois Cotes, Catau, Lais de Guia, Cadeira de Bombeiro, saber falcaçar cabos e transmiti-los usando o Método Escoteiro para o clã.","Distribuir corretamente o material dentro de uma mochila e orientar o Clã."]]],"r":["Os escotistas e pioneiros valorizam a realização de acampamentos e atividades ao ar livre na seção.","São realizadas atividades ao ar livre na seção."]},{"d":"Seleciona e aplica técnicas de campismo adequadas às Seleciona atividades e aplica do Programa tecnicas de Educativo campismo adequadas do Ramo às Pioneiro atividades do Programa Educativo do Ramo Pioneiro","g":[["Comportamentos desejados",["Aplica técnicas de campo e proporciona vivências educativas a partir destes recursos aos adolescentes.","Planeja atividades que contribuam para o aprendizado de técnicas de campo para os pioneiros.","Orienta os integrantes da seção na realização de atividades e tarefas refrentes ao campismo e à vida ao ar livre."]],["Atividades de desenvolvimento",["Saber as amarras Quadrada, Diagonal, Paralela e tripé e ensiná-las ao clã.","Ensinar ao clã a utilizar e conservar o fogareiro e o lampião.","Montar uma barraca e ensinar para o clã.","Ensinar o clã a acender uma fogueira e realizar uma receita de comida mateira.","Ensinar o clã a utilizar ferramentas de sapa e corte.","Ler o livro “Padrões de atividades escoteiras."]]],"r":["Os integrantes do clã pioneiro são protagonistas na organização de atividades ao ar livre, assumindo responsabilidades e sabem resolver problemas de ordem operacional durante as atividades.","Os integrantes do clã participam com entusiasmo dos acampamentos e atividades ao ar livre no clã.","Os integrantes do clã apresentam bom aproveitamento na realização das técnicas de campo previstas no Programa Educativo do Ramo.","São realizadas atividades ao ar livre na seção."]},{"d":"Avalia e orienta a execução da prática de técnicas de campismo e vida ao ar livre e orienta sobre sua correta aplicação","g":[["Comportamentos desejados",["Aplica técnicas de campo e proporciona vivências educativas, a partir destes recursos, às crianças.","Planeja atividades que contribuam para o aprendizado de técnicas de campo para as crianças.","Orienta os demais escotistas da equipe na execução de atividades ao ar livre e aplicação de técnicas de campismo."]],["Atividades de desenvolvimento",["Orientar o clã na organização de uma travessia.","Realizar reuniões de avaliação das atividades junto à equipe de escotistas e discutir suas impressões sobre as atividades com o APF.","Orientar o clã na utilização de mapa e bússola.","Orientar o clã pioneiro na aplicação dos conceitos básicos de estruturas (mesas, cavaletes, encaixes, ancoragens) nos projetos e montagens de contrução de pioneirias (torres, pontes, balsas etc.)","Orientar o clã pioneiro sobre a construção de abrigos naturais.","Orientar o clã pioneiro sobre as técnicas de previsão do tempo por indícios naturais."]],["Inclua no seu PPF",["Participar de um módulo ou outro momento de capacitação a respeito de técnicas de campo, aplicando seus conceitos nas reuniões da seção.","Conversar com sua equipe de trabalho sobre o equilíbrio de atividades ao ar livre dentro dos ciclos de programas propostos.","Em uma reunião de pais, expor a importância de atividades ao ar livre para o Movimento escoteiro, destacando os benefícios que essa prática traz para o desenvolvimento dos jovens."]]],"r":["A equipe de escotistas recebe a orientação adequada para a aplicação de atividades ao ar livre.","As atividades ao ar livre são avaliadas e sua execução é constantemente aperfeiçoada."]}]},{"x":18,"n":"Organização de Atividades","l":[{"d":"Identifica os tipos de atividades (fixas e variáveis), planejando e executando reuniões do clã e gerando Experiências Educativas","g":[["Comportamentos desejados",["Participa dos encontros de planejamento das reuniões semanais contribuindo com sugestões.","Dirige algumas atividades das reuniões do clã e apoia a realização das demais.","Reconhece pontos positivos e negativos durante a execução das atividades realizadas."]],["Atividades de desenvolvimento",["Ler o livro “Os primeiros meses de um novo clã”.","Participar das reuniões do clã, contribuindo em seu planejamento, execução e avaliação."]]],"r":["As reuniões do clã são dinâmicas e animadas.","As reuniões do clã são organizadas e com materiais disponíveis e preparados previamente.","Há um bom índice de assiduidade nas reuniões semanais do clã."]},{"d":"Diferencia os cuidados de planejamento entre reuniões semanais e atividades fora da sede","g":[["Comportamentos desejados",["Cuida em conjunto com os pioneiros da organização das atividades fora da sede, realizando todos os passos que garantam sua realização de maneira segura e educativa.","Compartilha previamente a programação das atividades com a equipe de escotistas.","Informa antecipadamente os participantes da seção sobre a realização fora da sede."]],["Atividades de desenvolvimento",["Orientar os jovens quanto ao planejamento de um cardápio para um acampamento de seção.","Orientar os jovens na realização do planejamento de um acampamento da seção.","Orientar os jovens na organização de uma excursão com o clã pioneiro.","Ler o livro Fogo de Conselho.","Orientar os jovens quanto à organização e à execução de um Fogo de Conselho."]]],"r":["As atividades da seção são seguras e têm seu caráter educativo preservado.","As atividades fora da sede são organizadas e com materiais sempre disponíveis e preparados.","Há um bom índice de assiduidade nas atividades realizadas fora da sede."]},{"d":"Orienta os pioneiros sobre os tipos de atividade (fixas e variaveis), auxiliando-os em sua execução e condução, garantindo experiências educativas","g":[["Comportamentos desejados",["Avalia o planejamento e execução de atividades dentro e fora da sede, buscando pontos de melhoria para próximas atividades.","Orienta os demais escotistas da seção no planejamento e execução de atividades dentro e fora da sede.","Planeja atividades variadas, de acordo com a ênfase identificada durante a execução do ciclo de programa."]],["Atividades de desenvolvimento",["Realizar reuniões de avaliação das atividades junto com os pioneiros e escotistas e discutir suas impressões sobre as atividades com o APF."]],["Inclua no seu PPF",["Preparar um plano de execução de atividades e tê-lo aprovado pela diretoria da UEL.","Realizar reuniões de avaliação e orientação dos demais escotistas quanto à realização de atividades ao ar livre.","Reavaliar, junto à sua equipe, o calendário de atividades e verificar se as atividades estão de acordo com a ênfase definida durante a preparação do ciclo de programa."]]],"r":["Os integrantes do clã participam com entusiasmo dos acampamentos e atividades ao ar livre.","São realizadas atividades ao ar livre na seção.","Os escotistas recebem orientação adequada para a realização de atividades de campismo e vida ao ar livre.","As atividades fora da sede são organizadas e com materiais sempre disponíveis e preparados.","Há um bom índice de assiduidade nas atividades realizadas fora da sede."]}]},{"x":19,"n":"Gestão de Projetos","l":[{"d":"Identifica as características de um projeto e compreende a importância de realizar projetos dentro do Ramo Pioneiro","g":[["Comportamentos desejados",["Conhece os campos de ação prioritários dos projetos no Ramo.","Entende a execução de projetos no Ramo Pioneiro como um recurso educativo.","Cita quais são os processos básicos para o planejamento e execução de um projeto."]],["Atividades de desenvolvimento",["Ler os Capítulos 4 e 5 do Manual do Escotista do Ramo Pioneiro e discutir com o APF sobre dúvidas e caminhos para aprofundar o aprendizado sobre projetos."]]],"r":["Os voluntários conhecem o funcionamento de um projeto e apoiam os jovens no desenvolvimento e execução.","O clã pioneiro desenvolve projetos relacionados à aplicação do Programa Educativo.","Os escotistas participam da execução de projetos no clã pioneiro, conforme o orientado no Manual do Escotista do Ramo."]},{"d":"Orienta os jovens no desenvolvimento e execução de projetos, de acordo com o Programa Educativo do Ramo.","g":[["Comportamentos desejados",["Apoia a implementação dos projetos desenvolvidos pelos jovens.","Aplica os princípios básicos de gestão de projetos.","Associa corretamente a forma de conduzir os projetos dentro do Ciclo de Programa, fomentando as equipes de interesse e observando a progressão pessoal dos jovens."]],["Atividades de desenvolvimento",["Orientar os pioneiros na realização de pelo menos um projeto de intervenção social."]]],"r":["Os projetos do clã pioneiro são acompanhados pelos escotistas.","Os pioneiros recebem a orientação necessária para o desenvolvimento de seus projetos."]},{"d":"Avalia e orienta outros escotistas sobre a forma correta de realizar projetos, assim como avalia e orienta sobre a condução do jovem na realização de projetos","g":[["Comportamentos desejados",["Realiza momentos de avaliação com os demais escotistas sobre a atuação dos escotistas no Ramo.","Identifica oportunidades de desenvolvimento dos demais escotistas e os orienta de maneira construtiva.","Planeja ações para o desenvolvimento dos escotistas e pioneiros da seção relacionadas à gestão de projetos."]],["Atividades de desenvolvimento",["Realizar atividades de capacitação em projetos para escotistas ou jovens, tais como: workshops, palestras, textos, ou outros meios."]]],"r":["Os pioneiros desenvolvem projetos com autonomia, necessitando de pouca intervenção dos mestres durante todo o processo.","Os escotistas do clã conversam sobre suas ações e buscam pontos de desenvolvimento.","São realizadas ações que ccolaboram com o desenvolvimento de escotistas e pioneiros na seção."]}]}]}]},"dir":{"n":"Dirigente","g":[{"t":"Competências essenciais","c":[{"x":0,"n":"Gestão de Mudanças","l":[{"d":"Demonstra disposição de aprender formas diferentes de fazer as coisas","g":[["Comportamentos desejados",["Aceita outras formas de fazer as coisas.","Mantém uma atitude positiva quando tem que mudar de ideia, conceitos, tarefas ou funções.","Busca informações sobre as mudanças e obtém informações que permitam compreendê-las."]],["Atividades de desenvolvimento",["Ler o documento “Características Essenciais do Movimento Escoteiro” e debater com seu APF as impressões sobre o documento.","Ler o capítulo “História do Escotismo”, do livro “Escotistas em ação de algum dos 4 ramos."]]],"r":["Os voluntários lidam de maneira receptiva com as mudanças da organização."]},{"d":"Analisa e implementa ações para a gestão de mudanças","g":[["Comportamentos desejados",["Aplica de maneira flexível normas ou procedimentos quando as circunstâncias exigem.","Toma decisões de maneira autônoma como resposta a situações de transformação.","É criativo e inovador no desempenho de suas funções."]],["Atividades de desenvolvimento",["Trabalhar junto com sua equipe ações que promovam a inovação em rotinas de sua função."]]],"r":["Os fluxos e processos da estrutura são constantemente revisados e aprimorados."]},{"d":"Avalia e projeta ações de mudança na estrutura em que atua","g":[["Comportamentos desejados",["Reflete sobre as atividades realizadas, identificando pontos de melhoria.","Antecipa riscos emergentes e aproveita oportunidades para satisfazer as necessidades futuras.","Cria novos modelos e metodologias organizacionais em resposta a novos contextos, condições e situações."]],["Atividades de desenvolvimento",["Organizar ações de melhoria e desenvolvimento contínuo na estrutura que atua, tais como projetos, campanhas de comunicação e inovações em processos."]]],"r":["Em momentos de mudança, os voluntários já se sentem preparados para adaptarem-se e promoverem as ações necessárias para a sua implantação."]}]},{"x":1,"n":"Aprendizagem e Desenvolvimento Pessoal","l":[{"d":"Expressa interesse e comprometimento com sua capacitação para a função que exerce","g":[["Comportamentos desejados",["Observa e aprende com os demais.","Participa de cursos, módulos e outras iniciativas de formação inerentes ao seu cargo ou função.","Como voluntário, buscar esclarecer suas dúvidas em relação ao desempenho de sua função com o APF."]],["Atividades de desenvolvimento",["Em conjunto com o APF, preparar o seu Plano Pessoal de Formação.","Participar do Curso Preliminar.","Ler e discutir com o APF a descrição do Cargo de Assessor Pessoal de Formação."]]],"r":["Os voluntários são comprometidos com seus processos de atualização.","Os adultos da U.E.L. tem APFs nomeados pela Diretoria da Estrutura."]},{"d":"Analisa os resultados de sua aprendizagem e compartilha seus conhecimentos e experiências com os demais","g":[["Comportamentos desejados",["Atua como agente promotor de novas ideias e tecnologias.","Motiva os demais na participação em processos de melhoria contínua, ajudando-os no desenvolvimento de suas tarefas e crescimento pessoal.","Aplica ao seu trabalho novas aprendizagens que enriquecem suas ações."]],["Atividades de desenvolvimento",["Realizar a revisão de seu PPF.","Participar do Curso Básico.","Ler o Guia do Chefe Escoteiro de Baden-Powell.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função.","Participar do curso em EAD sobre Assessor Pessoal de Formação ou outra iniciativa sobre o tema."]]],"r":["Os voluntários da estrutura compartilham informações sobre suas experiências de formação.","Os voluntários da estrutura aplicam novos conceitos às ações empregadas."]},{"d":"Avalia seus próprios resultados e realiza ações para melhorar seu desempenho continuamente","g":[["Comportamentos desejados",["Analisa seus próprios resultados e estabelece planos de ações para sua melhora.","Aproveita as mudanças organizacionais como oportunidades para desenvolver novos conhecimentos e habilidades.","Utiliza suas próprias experiências como aprendizados que compartilha abertamente com os demais."]],["Atividades de desenvolvimento",["Realizar a revisão do seu PPF.","Organizar ações para que os demais voluntários participem de iniciativas de formação e atualização.","Participar do Curso Avançado.","Conversar com o seu APF sobre a História da Insígnia de Madeira e Gilwell Park.","Ler a Politica Nacional de Adultos no Movimento Escoteiro.","Participar de um módulo, oficina ou outro momento de capacitação que contribua no desempenho de sua função."]]],"r":["Os voluntários promovem momentos de autoavaliação e compartilhamento de impressões sobre seu próprio desenvolvimento, gerando um clima de aprendizado contínuo."]}]},{"x":2,"n":"Compromisso","l":[{"d":"Aceita voluntariamente os fundamentos do Escotismo e cumpre suas tarefas com responsabilidade","g":[["Comportamentos desejados",["Vincula o propósito, os princípios, os valores e a missão do Movimento Escoteiro às suas atividades cotidianas.","Assume como próprios o propósito, os princípios, os valores e a missão do Movimento Escoteiro.","Atua de acordo com a orientação espiritual dos Escoteiros do Brasil no exercício de sua função."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler o capítulo 1 do P.O.R.","Conversar com seu APF, identificando os quatro itens que compõem os fundamentos do Escotismo (definição, propósito, princípios e método).","Realizar sua Promessa Escoteira.","Ler o capítulo 3 do P.O.R., “Orientação espiritual”."]]],"r":["As responsabillidades são distribuídas e cumpridas de maneira adequada."]},{"d":"Assume voluntariamente novas responsabilidades adicionais à correspondente ao seu cargo, atuando de acordo com os fundamentos do Escotismo","g":[["Comportamentos desejados",["Compartilha o significado do propósito, dos princípios, dos valores e da missão do Movimento Escoteiro a ambientes exteriores aos da organização","Assessora e guia os demais na realização de suas tarefas.","Dá andamento aos seus compromissos e reconhece as ações que deve implementar para seu cumprimento."]],["Atividades de desenvolvimento",["Organizar/Participar com a equipe de adultos da estrutura, de grupos de debates sobre as diversas funções existentes no Movimento Escoteiro.","Organizar/Participar de ações de captação de novos adultos para o Movimento Escoteiro.","Ler o Projeto Educativo da União dos Escoteiros do Brasil."]]],"r":["Os voluntários compartilham os valores do Movimento Escoteiro em ambientes externos à organização.","Os voluntários recebem a orientação e o suporte necessários para a implementação do propósito, princípio, valores e missão do Movimento Escoteiro."]},{"d":"Implementa ações para promover o compromisso de outros adultos dos Escoteiros do Brasil aos fundamentos do Escotismo","g":[["Comportamentos desejados",["Gera espaços que fomentem a iniciativa e responsabilidades em momentos críticos.","Reconhece o esforço de outros, fomentando a motivação e o compromisso do grupo a que pertence.","Dedica uma porcentagem de seu tempo à revisão dos planos de trabalho, objetivos e sua contribuição nessas tarefas."]],["Atividades de desenvolvimento",["Ler o Manual de Reconhecimento dos Escoteiros do Brasil.","Organizar, no âmbito da sua Unidade Escoteira Local, uma ação de avaliação, solicitação e entrega de reconhecimentos aos voluntários."]]],"r":["Os voluntários são devidamente reconhecidos pelo seu compromisso e comprometimento.","São organizados momentos para revisão dos planos de trabalho e discussão sobre a distribuição de tarefas entre os voluntários."]}]},{"x":3,"n":"Consciência Organizacional","l":[{"d":"Identifica as estruturas da organização, especialmente o funcionamento e os objetivos do nível em que atua","g":[["Comportamentos desejados",["Conhece a história e os avanços mais relevantes da organização.","Conhece e identifica a estrutura da organização nos níveis local e regional.","Conhece os direitos e deveres inerentes ao seu cargo/função."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler os capítulos 4 e 5 do título 2 do Estatuto da União dos Escoteiros do Brasil e o Capítulo 5 do P.O.R."]]],"r":["Os voluntários conhecem a estrutura do nível em que atuam e suas competências."]},{"d":"Desenvolve ações para a promoção de maior sentido de unidade e propósito comum nas ações da estrutura em que atua","g":[["Comportamentos desejados",["Implementa procedimentos organizacionais para a resolução de problemas.","Aplica os princípios de governança dentro da instituição.","Promove permanentemente as práticas democráticas e o respeito às diferenças."]],["Atividades de desenvolvimento",["Promover as políticas organizacionais dos Escoteiros do Brasil em grupos de debate e discussões, juntamente com a equipe da qual faz parte.","Ler o Estatuto dos Escoteiros do Brasil.","Participar de eventos distritais, regionais e nacionais."]]],"r":["Os processos de escolha e renovação de lideranças estão de acordo com as recomendações das políticas e orientações da Organização Mundial do Movimento Escoteiro.","São promovidas práticas de exercício da democracia e respeito às diferenças na estrutura."]},{"d":"Avalia e implementa ações para a conscientização de voluntários sobre a importância da estrutura institucional do Movimento Escoteiro","g":[["Comportamentos desejados",["Promove o sentido de unidade e propósito comum entre os diferentes níveis da organização.","Compreende o impacto da sociedade civil, governo, setor privado, terceiro setor e outros grupos de interesse externos no cumprimento da missão da organização.","Conhece a estrutura do Escotismo Mundial."]],["Atividades de desenvolvimento",["Explicar aos demais voluntários as relações entre as estruturas e níveis da organização.","Participar de uma assembleia regional ou nacional.","Ler as resoluções do CAN e DEN e debater com o APF ou grupo de discussão sobre os documentos."]]],"r":["Os voluntários têm a compreensão da importância das estruturas da organização e promovem boas práticas e o diálogo entre elas.","Os voluntários têm a compreensão da importância da boa relação que o Movimento Escoteiro deve ter com as demais instituições."]}]},{"x":4,"n":"Planejamento Estratégico","l":[{"d":"Identifica as responsabilidades e objetivos da função que desempenha","g":[["Comportamentos desejados",["Atua de acordo com as funções atribuídas a seu cargo, com a tarefa que lhe é designada.","Conhece o plano de trabalho da equipe da qual faz parte.","Solicita a assessoria necessária para o estabelecimento de planos de trabalho referentes a sua função."]],["Atividades de desenvolvimento",["Assinar o acordo de trabalho voluntário contendo a descrição das funções pertinentes ao cargo ao qual está designado.","Ler o documento “Perfis: cargos e funções”, do nível em que atua.","Leitura do plano de grupo da UEL conhecendo suas metas, áreas estratégicas e indicadores."]]],"r":["Os voluntários da estrutura compartilham as responsabilidades necessárias para o desenvolvimento das atividades."]},{"d":"Planeja atividades e tarefas inerentes ao seu cargo ou função","g":[["Comportamentos desejados",["Formula planos de ação, considerando os objetivos de longo prazo, as metas e os planos da organização.","Presta assessoria em função dos planos de trabalho a curto, médio e longo prazo.","Estabelece pontos de controle, gerando dados e informações para o acompanhamento dos objetivos e prazos."]],["Atividades de desenvolvimento",["Participar da concepção do calendário de atividades da estrutura em que atua."]]],"r":["Os voluntários da estrutura trabalham na concepção e revisão de planos de trabalho, monitorando seus resultados."]},{"d":"Compreende como sua atuação contribui para o alcance dos objetivos do Planejamento Estratégico dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Gera espaços que fomentem a iniciativa e responsabilidades em momentos críticos.","Dedica uma porcentagem de seu tempo à revisão dos planos de trabalho, objetivos e a sua contribução nestas tarefas.","Ser disciplinado no uso de recursos para o cumprimento de suas ações."]],["Atividades de desenvolvimento",["Ler o Planejamento Estratégico dos Escoteiros do Brasil.","Participar do planejamento da sua Unidade Escoteira Local, considerando os objetivos anuais das seções quem compôem a UEL.","Ler o Documento “Perfis: cargos e funções” do Nível Regional e Nacional."]]],"r":["Os voluntários são devidamente reconhecidos pelo seu compromisso e comprometimento.","São organizados momentos para revisão dos planos de trabalho e discussão sobre a distribuição de tarefas entre os voluntários."]}]},{"x":5,"n":"Relações Interpessoais","l":[{"d":"Identifica quais são as condutas referenciais de cortesia, respeito e confiança desejadas aos adultos dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Trata os demais com respeito, aceita as diferenças de pensamento e expressão das emoções.","Interage socialmente com outros, seguindo as normas básicas de cortesia.","Refere-se em termos positivos aos demais e sobre o trabalho que realizam."]],["Atividades de desenvolvimento",["Participar adequadamente das reuniões da equipe da qual faz parte.","Ler e discutir com seu Assessor Pessoal de Formação a definição do Movimento Escoteiro - Regra 001 do P.O.R."]]],"r":["A relação entre os voluntários é respeitosa e baseada em ações de cortesia.","Existe uma cultura de diálogo e respeito à diversidade."]},{"d":"Desenvolve ações favorecendo as boas relações de trabalho cooperativo entre os adultos, inclusive com os responsáveis dos jovens","g":[["Comportamentos desejados",["É coerente em suas ações e seus resultados.","Promove a participação dos integrantes da diretoria e o diálogo intergeracional.","Escuta pontos de vista dos demais e modifica sua própria perspectiva, quando necessário."]],["Atividades de desenvolvimento",["Participar da organização de pelo menos uma, ação integrada entre equipes de trabalho na execução de projetos.","Participar de uma seção de avaliação sobre o seu próprio trabalho e receber as críticas de maneira aberta e construtiva."]]],"r":["Há envolvimento e preocupação por parte dos voluntários para que os conflitos existentes sejam mediados e solucionados."]},{"d":"Avalia sua relação com os demais e busca alternativas para fortalecê-las, baseadas em compreensão e flexibilidade","g":[["Comportamentos desejados",["Utiliza habilidades interpessoais para a gestão das relações entre os integrantes da equipe.","Demonstra proatividade no momento de prestar apoio aos acontecimentos que requerem esforços integrados.","Demonstra não tomar as palavras ou situações de maneira pessoal."]],["Atividades de desenvolvimento",["Planejar ações de integração entre pessoas e áreas de trabalho, promovendo o fortalecimento das relações interpessoais.","Prestar adequadamente avaliações sobre os componentes de sua equipe de trabalho."]]],"r":["Os voluntários são pró-ativos na resolução de conflitos entre adultos da organização.","Os voluntários posicionam-se de maneira adequada e sensata, gerando um clima de confiança mútua."]}]},{"x":6,"n":"Trabalho em Equipe","l":[{"d":"Reafirma a importância do trabalho em equipe, cooperando com os participantes de seu grupo de trabalho","g":[["Comportamentos desejados",["Assume seu papel/tarefas designadas com responsabilidade.","Ajuda em outras tarefas além das quais é responsável, quando necessário.","Expressa-se em termos positivos a sua equipe."]],["Atividades de desenvolvimento",["Participar de, pelo menos, uma Reunião de Diretoria da Unidade Escoteira Local."]]],"r":["As tarefas/projetos são desenvolvidas coletivamente e seus resultados são compartilhados."]},{"d":"Desenvolve projetos e as competências da equipe de trabalho que compõe","g":[["Comportamentos desejados",["Conhece as fortalezas e pontos de melhoria dos integrantes da equipe.","Proporciona ou assegura o apoio necessário para o desenvolvimento da equipe.","Gera um clima de trabalho que promove o espírito e a cooperação da equipe com outras equipes."]],["Atividades de desenvolvimento",["Cumprir com as responsabilidades inerentes a sua função (Registro no PAXTU, tarefas administrativas, suporte a outros escotistas e dirigentes, gestão institucional etc.)"]]],"r":["Os voluntários têm facilitado o apoio para o desenvolvimento de seus projetos mediante o trabalho em equipe.","A comunicação entre os voluntários da estrutura tem fluxos ágeis e definidos."]},{"d":"Avalia os resultados atingidos pela equipe de trabalho que compõe e estimula ações para sua melhoria","g":[["Comportamentos desejados",["Observa padrões de interação dentro da equipe e antecipa-se aos conflitos, prevenindo-os.","Avalia as fortalezas e pontos de melhoria próprios e da equipe e propõe ações para seu desenvolvimento.","Permite aos demais a participação na construção da visão dos resultados que se esperam da equipe."]],["Atividades de desenvolvimento",["Avaliar as ações desenvolvidas pela sua equipe de trabalho em reuniões periódicas com a colaboração dos demais participantes da equipe."]]],"r":["Os voluntários realizam processos de avaliação em equipe e propõem estratégias para suas ações."]}]}]},{"t":"Competências específicas","c":[{"x":7,"n":"Gestão Administrativa","l":[{"d":"Identifica e registra informações nos documentos e sistemas referentes a sua função e tarefas como dirigente","g":[["Comportamentos desejados",["Identifica, no regulamento da U.E.L., quais são os documentos que se referem as suas funções desenvolvidas na estrutura.","Registra as solicitações e emissões de documentação acerca da função que atua.","Sabe acessar o PAXTU, conhecendo sua utilidade e ferramentas."]],["Atividades de desenvolvimento",["Reunir-se com o Assessor Pessoal de Formação e a Diretoria do Grupo para esclarecer quais são as rotinas e documentos sob sua responsabilidade.","Participar de uma capacitação local, distrital ou regional sobre a utilização do PAXTU."]]],"r":["Os voluntários conhecem os procedimentos básicos de administração de U.E.L."]},{"d":"Organiza e analisa documentos e informações referentes a sua função e tarefas como dirigente","g":[["Comportamentos desejados",["Organiza a documentação sob sua responsabilidade.","Registra e analisa as solicitações e emissões de documentação.","Acompanha os indicadores e a pontuação da U.E.L. no Grupo Padrão pelo PAXTU"]],["Atividades de desenvolvimento",["Organizar os documentos e livros de registro inerentes a sua função.","Colaborar na atualização de informações do PAXTU administrativo.","Responsabilizar-se pela produção de uma ata de reunião da equipe que trabalha ou de Assembleia de Grupo.","Ler o regulamento e cronograma do Grupo Escoteiro Padrão do ano vigente.","Realizar o processo de registro de associados do Grupo nos Escoteiros do Brasil."]]],"r":["A unidade local é bem organizada, sua documentação é preservada de maneira segura, adequada e todas as informações da U.E.L. estão atualizadas no PAXTU.","Escotistas conhecem os indicadores e regulamento do Grupo Padrão."]},{"d":"Orienta os demais adultos da estrutura sobre a utilização de sistemas e documentos pertinentes a suas funções","g":[["Comportamentos desejados",["Orienta os adultos sobre o manejo e gestão de documentos sob responsabilidade das diversas áreas e documentos referentes a sua função.","Orienta e acompanha escotistas no planejamento e cumprimento dos INDI- CADORES do Grupo Padrão.","Orienta outros adultos sobre a utilização do PAXTU."]],["Atividades de desenvolvimento",["Examinar a condição de organização da documentação das diversas áreas da U.E.L. e, caso necessário, propor metodologias para aperfeiçoamento dos processos.","Promover um momento de atualização e informação sobre a utilização do PAXTU para outros adultos.","Ler o cronograma e regulamento do Grupo Escopteiro Padrão para planejamento das atividades de grupo com revisão constante dos indicadores no PAXTU."]]],"r":["Os adultos recebem a orientação necessária para o cumprimento de suas tarefas e rotinas administrativas quando necessário."]}]},{"x":8,"n":"Gestão de Adultos","l":[{"d":"Identifica as funções, cargos e respectivos perfis para cada uma das funções existentes na estrutura em que atua","g":[["Comportamentos desejados",["Identifica os documentos referentes a atuação dos adultos no Movimento Escoteiros do Brasil.","Atua de acordo com a função que lhe é designada cumprindo com suas responsabilidades.","Reconhece a importância das diversas funções existentes na estrutura."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, ler as regras 35 e 36 do P.O.R. e discuti-la com seu APF."]]],"r":["Os adultos da U.E.L. conhecem os cargos e funções, além de seus parâmetros de atuação."]},{"d":"Aplica as orientações da Política Nacional de Adultos no Movimento Escoteiro na Unidade Escoteira Local","g":[["Comportamentos desejados",["Realiza ações referentes ao processo de captação de adultos na U.E.L.","Promove o Sistema Nacional de Formação na U.E.L.","Aplica os processos de acompanhamento de adultos na U.E.L."]],["Atividades de desenvolvimento",["Colaborar em ações com enfoque na captação de novos adultos.","Colaborar em ações de incentivo aos adultos da U.E.L. para a participação em iniciativas de formação dos Escoteiros do Brasil e externas.","Acompanhar o trabalho dos Assessores Pessoais de Formação, especialmente na formatação, cumprimento e revisão dos planos pessoais de formação (PPF)."]]],"r":["Os processos de gestão de adultos da estrutura atendem os parâmetros de aplicação indicados pela Política Nacional de Adultos no Movimento Escoteiro."]},{"d":"Elabora ações de valorização dos processos do Ciclo de Vida do Adulto, descritos na Política Nacional de Adultos no Movimento Escoteiro","g":[["Comportamentos desejados",["Orienta os adultos na realização de campanhas de captação de novos voluntários para o Grupo.","Orienta os adultos sobre o Sistema Nacional de Formação, incentivando-os a se desenvolverem.","Orienta os adultos sobre os processos adequados de acompanhamento, realizando o reconhecimento das iniciativas quando oportuno."]],["Atividades de desenvolvimento",["Elaborar e executar, envolvendo outros voluntários, um plano de captação de adultos para sua U.E.L.","Elaborar ações de incentivo aos adultos da U.E.L. para a participação em iniciativas de formação.","Realizar ações de integração e envolver os adultos da U.E.L.","Colaborar em ações de acompanhamento dos adultos da U.E.L"]]],"r":["Os processos de gestão de adultos da estrutura atendem os parâmetros de aplicação indicados pela Política Nacional de Adultos no Movimento Escoteiro."]}]},{"x":9,"n":"Gestão Financeira","l":[{"d":"Identifica e registra as receitas e despesas da área na qual atua na U.E.L.","g":[["Comportamentos desejados",["Identifica as receitas correntes da Unidade Escoteira.","Conhece as taxas cobradas pela Unidade Escoteira, as destinações de cada uma e a sua forma de registro.","Identifica as despesas mais comuns da Unidade Escoteira."]],["Atividades de desenvolvimento",["Ler o capítulo 4 do P.O.R","Ler a parte do Estatuto ou Regulamento da U.E.L. sobre Patrimônio e Finanças.","Examinar uma prestação de contas anual passada da U.E.L."]]],"r":["Os dirigentes da U.E.L. sabem as taxas cobradas, o que elas pagam e são capazes de agir na tesouraria recebendo pagamentos, caso necessário."]},{"d":"Utiliza o orçamento a sua disposição e realiza o correto registro contábil, além de prestar contas à comissão fiscal da Unidade em que atua e à Região Escoteira","g":[["Comportamentos desejados",["Registra as despesas da U.E.L para fins de prestação de contas.","Acompanha a execução orçamentária para rubricas de sua responsabilidade.","Elabora orçamentos para atividades de grupo ou de seção."]],["Atividades de desenvolvimento",["Elaborar o orçamento e definir a taxa de uma atividade de grupo ou de seção.","Participar de uma reunião de apresentação de prestação de contas com a Comissão Fiscal.","Participar da elaboração da prestação de contas anual.","Colaborar no Registro e controle do Patrimônio do Grupo Escoteiro"]]],"r":["Parte significativa das atividades da U.E.L planejadas pela Diretoria são feitas a partir de orçamentos prévios","A prestação de contas é encaminhada à Comissão Fiscal com tempo suficiente para análise e solução de dúvidas, sendo ao final aprovada."]},{"d":"Planeja o orçamento anual da U.E.L. e acompanha sua execução para a realização das ações previstas","g":[["Comportamentos desejados",["Elabora o Orçamento anual da U.E.L.","Propõe reajuste de taxas ou obtenção de outros recursos quando detectar a necessidade.","Orienta os adultos da U.E.L. sobre as regras de execução orçamentária.","Orienta os Escotistas sobre a elaboração de orçamentos para atividades."]],["Atividades de desenvolvimento",["Participar da elaboração de um Orçamento Anual da U.E.L.","Organizar e executar momento de capacitação, para os adultos da U.E.L, sobre como fazer um orçamento de atividades.","Elaborar uma pequena cartilha de orientação aos adultos sobre as regras para documentação de despesas na U.E.L.","Apresentar aos pais a execução orçamentária da U.E.L, enfatizando principais receitas e justificando principais despesas."]]],"r":["Todos os gastos da U.E.L são enquadrados no orçamento da U.E.L, o qual é regularmente acompanhado e ajustado pela Diretoria.","Todos os projetos novos da U.E.L. são precedidos de análise de impacto orçamentário e planejamento para captação de recursos.","Todas as atividades feitas pela diretoria e a maior parte das atividades de seção são feitas a partir de orçamentos prévios."]}]},{"x":10,"n":"Gestão de Conflitos","l":[{"d":"Identifica ações inadequadas a atuação voluntária na U.E.L, compartilhando a informação com outros membros da diretoria","g":[["Comportamentos desejados",["Atua de acordo com o “Perfil do Adulto que Necessitamos” dos Escoteiros do Brasil.","Identifica ações inadequadas à atuação de um voluntário dos Escoteiros do Brasil (Atuação contrária aos princípios do Movimento Escoteiro, desrespeito ao próximo).","Promove um ambiente saudável e de cooperação entre os adultos no Movimento Escoteiro."]],["Atividades de desenvolvimento",["Identificar quais são os comportamentos potencialmente geradores de conflitos e discutir com seu APF."]]],"r":["A U.E.L tem um ambiente saudável seguindo os Princípios Escoteiros."]},{"d":"Atua de maneira imediata na conciliação de conflitos adultos da estrutura da qual é responsável","g":[["Comportamentos desejados",["Capacita-se para atuação em momentos onde a mediação de conflitos é necessária.","Realiza ações de prevenção a conflitos entre os adultos da estrutura."]],["Atividades de desenvolvimento",["Participar de um evento de formação ou ler alguma publicação cuja temática seja resolução de conflitos."]]],"r":["Na U.E.L eventuais conflitos são solucionados com a agilidade necessária"]},{"d":"Analisa e delibera ações para a resolução de conflitos na U.E.L. baseado nas Resoluções do CAN que tratam do assunto","g":[["Comportamentos desejados",["Orienta a aplicação de medidas disciplinares na estrutura que atua","Orienta outros adultos na condução de processos de mediação de conflitos na estrutura que atua","Encaminha quando necessário as resoluções de questões disciplinares a outros orgãos competentes da organização."]],["Atividades de desenvolvimento",["Aplicar uma dinâmica sobre gestão de conflitos para a Equipe de Escotistas e Dirigentes da sua U.E.L.","Ler a resolução N.º 03/2008 e 09/2009 da União dos Escoteiros do Brasil."]]],"r":["Na U.E.L as questões disciplinares são mediadas de maneira eficaz."]}]},{"x":11,"n":"Condução de Cerimônias","l":[{"d":"Identifica as vozes de comando, sinais de apito e os elementos que compõem uma cerimônia de abertura e encerramento de atividades escoteiras e as conduz adequadamente","g":[["Comportamentos desejados",["Descreve quais são os elementos que compõem uma cerimônia escoteira de abertura e encerramento de atividades.","Demonstra organização na preparação do local e dos materiais necessários para a realização de cerimônias no Grupo.","Transmite as informações com segurança quando coordena uma cerimônia."]],["Atividades de desenvolvimento",["Antes do Curso Preliminar, assistir aos vídeos da série “Como se faz”.","Conduzir uma cerimônia de hasteamento/arriamento no grupo."]]],"r":["As cerimônias são significativas para seus participantes."]},{"d":"Conduz cerimônias escoteiras de maneira adequada","g":[["Comportamentos desejados",["Auxilia os outros adultos na realização de cerimônias no grupo.","Comportamento relacionado à aplicação.","Compreende as cerimônias escoteiras como espaço educativo e inclusivo na prática do escotismo."]],["Atividades de desenvolvimento",["Ler o Manual de Cerimônias dos Escoteiros do Brasil e discutir com o APF.","Auxiliar um escotista na realização de uma Cerimônia de Promessa.","Analisar a conformidade com o manual de cerimônias dos Escoteiros do Brasil dos cerimoniais executados na sua U.E.L.","Orienta os integrantes da Diretoria sobre a participação adequada em cerimônias escoteiras."]]],"r":["As cerimônias são adequadas, realizadas em momento oportuno, local apropriado e são estimulantes."]},{"d":"Orienta os demais adultos da estrutura sobre a realização de cerimônias, zelando pelo caráter educativo","g":[["Comportamentos desejados",["Reconhece o caráter educativo das cerimônias realizadas na U.E.L.","Organiza e conduz cerimônias adequadamente.","Orienta outros adultos quanto à correta organização de cerimônias escoteiras."]],["Atividades de desenvolvimento",["Orientar outro adulto sobre o papel dos dirigentes nas cerimônias.","Organizar na sua U.E.L. momento de capacitação sobre execução de cerimoniais, em conformidade com o manual de cerimônias dos Escoteiros do Brasil.","Participar junto aos escotistas de uma cerimônia de passagem de ramo ou cerimônia de Partida do ramo Pioneiro."]]],"r":["As cerimônias são adequadas, realizadas em momento oportuno, e local apropriado.","As cerimônias e os encontros culturais e/ou comemorativos da U.E.L. são referência no ambiente escoteiro."]}]},{"x":12,"n":"Relações Institucionais","l":[{"d":"Descreve a definição, propósito, princípio e posição do Escotismo","g":[["Comportamentos desejados",["Identifica quais são os posicionamentos institucionais sobre a definição do Escotismo.","Promove a União dos Escoteiros do Brasil como uma instituição plural e que respeita a diversidade.","Identifica que a boa ação diária e o serviço ao próximo são deveres comuns aos participantes do Escotismo."]],["Atividades de desenvolvimento",["Ler as regras 01, 02, 03 e 11 a 20 do P.O.R. e debater com seu Assessor Pessoal de Formação."]]],"r":["Os adultos da estrutura conhecem quais são os posicionamentos institucionais dos Escoteiros do Brasil.","Os adultos são capazes de apresentar a definição e o propósito do Movimento Escoteiro."]},{"d":"Representa o escotismo junto à comunidade e outras organizações","g":[["Comportamentos desejados",["Representa a estrutura que atua em eventos da comunidade onde a U.E.L. está localizada.","Representa a U.E.L. em encontros regionais e distritais.","Representa a U.E.L. em eventos que envolvem outras organizações."]],["Atividades de desenvolvimento",["Participar de reuniões na comunidade representando o movimento escoteiro ou sua U.E.L."]]],"r":["O Movimento Escoteiro é representado adequadamente na comunidade e entre outras organizações."]},{"d":"Formula propostas de parceria e geração de novas oportunidades para a U.E.L.","g":[["Comportamentos desejados",["Busca oportunidades para o estabelecimento de parcerias com outras organizações.","Promove ações que mostrem o Escotismo como movimento relevante na comunidade da U.E.L.","Orienta outros adultos quanto às formas corretas de representação institucional dos Escoteiros do Brasil."]],["Atividades de desenvolvimento",["Realizar uma sessão informativa aos demais adultos da U.E.L. sobre as regras 01, 02, 03 e 11 a 20 do P.O.R","Planejar e coordenar uma ação de mobilização (festa, campanha, festival etc.) de recursos na estrutura em que atua.","Ler os posicionamentos dos Escoteiros do Brasil sobre diversidade e maioridade penal e dicutí-los com seu APF."]]],"r":["É compartilhado aos adultos da U.E.L. os posicionamentos institucionais e as boas práticas de representação institucional do Movimento Escoteiro.","Os posicionamentos institucionais e boas práticas de representação do Movimento Escoteiro, são compartilhados aos adultos da organização."]}]},{"x":13,"n":"Compreensão do Programa Educativo","l":[{"d":"Identifica as seis áreas de desenvolvimento do Programa Educativo e sua importância para o seu desenvolvimento","g":[["Comportamentos desejados",["Conhece as características gerais do Programa Educativo dos Escoteiros do Brasil.","Entende que as atividades educativas do Movimento Escoteiro devem contemplar as seis áreas de desenvolvimento.","Apoia, quando necessário, o desenvolvimento das atividades educativas na U.E.L."]],["Atividades de desenvolvimento",["Ler o capítulo 7 do P.O.R.","Ler o livro”Escotistas em ação”, de um dos quatro ramos.","Participar de uma reunião semanal de alguma das seções da U.E.L."]]],"r":["Os dirigentes da U.E.L. conhecem as características gerais do Programa Educativo dos Escoteiros do Brasil e entendem a importância de sua correta aplicação."]},{"d":"Examina as atividades do programa educativo realizadas pelas seções e debate com os escotistas sobre suas impressões","g":[["Comportamentos desejados",["Posiciona-se adequadamente sobre a realização das atividades escoteiras nas seções.","Discute com os escotistas os pontos positivos e as oportunidades de melhoria das atividades educativas da U.E.L.","Estimula a realização de atividades educativas nas seis áreas de desenvolvimento."]],["Atividades de desenvolvimento",["Participar/Promover uma reunião com os escotistas da U.E.L., discutindo o desenvolvimento do Programa Educativo na estrutura.","Participar de uma atividade da seção (Flor Vermelha, Fogo de Conselho, excursão, acampamento, acantonamento etc).","Conduzir uma palestra para os responsáveis pelos jovens da U.E.L."]]],"r":["Os dirigentes da U.E.L. zelam pela adequada aplicação do Programa Educativo, seguindo as orientações dos Escoteiros do Brasil.","A prática do Programa Educativo dos Escoteiros do Brasil é alinhada com os conceitos estabelecidos nos guias e manuais da organização."]},{"d":"Apoia e orienta, quando necessário, os escotistas das seções quanto ao desenvolvimento de atividades e ações relacionadas ao Programa Educativo","g":[["Comportamentos desejados",["Orienta a organização de atividades escoteiras na U.E.L.","Realiza reuniões sistemáticas com os escotistas para tratar de assuntos pertinentes à aplicação do Programa Educativo dos Escoteiros do Brasil.","Sugere ações de melhoria/inovação nas atividades da U.E.L."]],["Atividades de desenvolvimento",["Ler a Política Nacional de Programa Educativo.","Organizar um momento de discussão com os escotistas da U.E.L sobre o Programa Educativo.","Avaliar o trabalho das seções, levantando pontos fortes e fracos, contribuindo com sugestões de melhorias ."]]],"r":["A diretoria da U.E.L. presta a orientação e o suporte adequados aos escotistas para a aplicação do Programa Educativo."]}]},{"x":14,"n":"Governança","l":[{"d":"Identifica quais são os regulamentos e normas dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Conhece o Estatuto e o P.O.R. dos Escoteiros do Brasil, reconhecendo sua importância.","Conhece o Estatuto/Regulamento da U.E.L., reconhecendo sua utilidade.","Atua de acordo com as normas e Regulamentos da União dos Escoteiros do Brasil."]],["Atividades de desenvolvimento",["Ler o título 1 do “Estatuto dos Escoteiros do Brasil” e discuti-lo com seu Assessor Pessoal de Formação.","Ler o Estatuto/regulamento da U.E.L. e discuti-lo com seu Assessor Pessoal de Formação."]]],"r":["A U.E.L. tem suas normas e regulamentos estabelecidos e em concordância com a orientação da União dos Escoteiros do Brasil."]},{"d":"Aplica as orientações das normas e outros documentos dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Aplica as orientações do Estatuto e o P.O.R. dos Escoteiros do Brasil, reconhecendo sua importância.","Garante que o Estatuto/Regulamento da U.E.L. esteja em concordância com o Estatuto, P.O.R. e demais documentos normativos da União dos Escoteiros do Brasil.","Divulga aos adultos da U.E.L. os documentos oficiais da União dos Escoteiros do Brasil."]],["Atividades de desenvolvimento",["Analisar o Estatuto/Regulamento da U.E.L. e identificar pontos de conflito e atualização em relação às regras estabelecidas no Estatuto, P.O.R. e demais normativas da União dos Escoteiros do Brasil, sugerindo adequação necessárias.","Auxiliar na organização de uma Assembleia de Grupo.","Ler a resolução N.º 01/2017 do CAN."]]],"r":["A U.E.L. tem suas normas e regulamentos estabelecidos e em concordância com o orientado pela União dos Escoteiros do Brasil.","Os dirigentes da U.E.L. conhecem as orientações normativas dos Escoteiros do Brasil e observam o seu cumprimento no nível local."]},{"d":"Explica aos demais adultos a função dos regulamentos, normas e outros documentos dos Escoteiros do Brasil","g":[["Comportamentos desejados",["Transmite aos demais as definições do Estatuto e o P.O.R. dos Escoteiros do Brasil e Regulamento da U.E.L.","Orienta os voluntários sobre normas da União dos Escoteiros do Brasil.","Zela pelo cumprimento do Estatuto, P.O.R. e Regras da Instituição."]],["Atividades de desenvolvimento",["Organizar uma apresentação sobre os orgãos de governança dos Escoteiros do Brasil aos demais voluntários da U.E.L.","Participar de uma reunião de distrito, Assembléia Regional ou Nacional.","Analisar o Estatuto/Regulamento da U.E.L. e identificar pontos de conflito ou atualização em relação às regras estabelecidas no Estatuto, P.O.R. e demais normativas da União dos Escoteiros do Brasil, sugerindo adequação necessárias."]]],"r":["A U.E.L. tem suas normas e regulamentos estabelecidos e em concordância com o orientado pela União dos Escoteiros do Brasil."]}]},{"x":15,"n":"Comunicação Institucional","l":[{"d":"Identifica os canais adequados de comunicação e as orientações institucionais de como apresentar o Movimento Escoteiro","g":[["Comportamentos desejados",["Conhece os canais oficiais de transmissão de informação dos Escoteiros do Brasil."]],["Atividades de desenvolvimento",["Acessar todos os canais oficiais de comunicação dos Escoteiros do Brasil (Facebook, Youtube, Instagram, Site Nacionais e Regional), buscando informações relevantes a função que atua e discutir com o seu APF sobre quais foram suas dificuldades e descobertas."]]],"r":["Os adultos da U.E.L. conhecem os canais oficiais de comunicação da instituição e os utilizam adequadamente."]},{"d":"Aplica as orientações institucionais e utiliza os meios adequados para realizar a comunicação interna e externa da U.E.L. em que atua","g":[["Comportamentos desejados",["Aplica as orientações dos Escoteiros do Brasil na confecção de materiais de comunicação para a U.E.L.","Sabe utilizar as ferramentas adequadas para comunicar as ações da U.E.L.","Busca nos canais corretos as informações necessárias para o desenvolvimento de ações na U.E.L."]],["Atividades de desenvolvimento",["Ler o Manual de Identidade Visual dos Escoteiros do Brasil.","Realizar um estudo sobre quais são os materiais de divulgação da U.E.L."]]],"r":["As ações de divulgação e comunicação da U.E.L. são baseadas nas informações e orientações oficiais dos Escoteiros do Brasil."]},{"d":"Orienta os demais adultos da U.E.L. sobre os recursos e maneiras adequadas de comunicar-se interna e externamente sobre o Movimento Escoteiro","g":[["Comportamentos desejados",["Orienta o desenvolvimento de projetos e materiais de divulgação e comunicação do Movimento Escoteiro na estrutura que atua.","Orienta outros adultos sobre as práticas de comunicação e divulgação do Movimento Escoteiro","Avalia projetos e ações desenvolvidas relacionadas a promoção do Movimento Escoteiro."]],["Atividades de desenvolvimento",["Preparar e desenvolver uma apresentação com os adultos da UEL sobre comunicação ou formas de divulgar o movimento escoteiro.","Orientar os adultos da UEL sobre práticas de comunicação e divulgação das ações da UEL."]]],"r":["Os adultos da estrutura recebem a orientação adequada no desenvolvimento de ações de comunicação e promoção do Movimento Escoteiro."]}]},{"x":16,"n":"Segurança","l":[{"d":"Reconhece a importância da segurança nas atividades escoteiras, seguindo as orientações do P.O.R. nas tarefas da U.E.L.","g":[["Comportamentos desejados",["Leva em conta prioritariamente os aspectos relacionados à segurança, para organizar suas atividades.","Zela pela segurança dos jovens durante as atividades.","Observa se todas as atividades do clã preservam prioritariamente as regras de segurança."]],["Atividades de desenvolvimento",["Antes do curso, ler o capítulo 14 do P.O.R. (Segurança nas atividades escoteiras).","Ler o capítulo 15 do P.O.R. (Política de Proteção Infantojuvenil).","Realizar o Curso de Proteção Infanto- Juvenil dos Escoteiros do Brasil."]]],"r":["A U.E.L. realiza atividades estimulantes e notavelmente seguras.","A U.E.L. é modelo de zelo e cuidado com os jovens."]},{"d":"Age de maneira imediata em situações potenciais ou reais de abusos ou maus tratos","g":[["Comportamentos desejados",["Zela pelos procedimentos de segurança dos Escoteiros do Brasil e conhece a Política de Proteção Infantojuvenil, agindo conforme suas diretrizes.","Orienta os integrantes da seção sobre as regras de segurança dos Escoteiros do Brasil.","Promove a Política de Proteção Infantojuvenil dos Escoteiros do Brasil."]],["Atividades de desenvolvimento",["Organizar/participar junto com os dem ais adultos da Unidade Escoteira, de um debate sobre o capítulo 15 do P.O.R.","Organizar um plano de segurança para uma atividade da U.E.L. fora da sede."]]],"r":["A Unidade Escoteira é um ambiente seguro e de confiança para os responsáveis e jovens."]},{"d":"Toma as devidas precauções com os aspectos legais envolvidos nas atividades escoteiras","g":[["Comportamentos desejados",["Conhece suas responsabilidades e tem atitudes adequadas e educativas com os escoteiros.","É exemplo de conduta responsável.","Cumpre as recomendações da UEB e respeita todas as determinações legais."]],["Atividades de desenvolvimento",["Ler o Estatuto da Criança e do Adolescente.","Antes do curso, ler o livro “Proteção da Criança e do Adolescente - Orientações sobre como Proteger e Previnir Abusos”.","Participar de, pelo menos, uma reunião de avaliação de um acantonamento/acampamento de uma seção ou da U.E.L focando no plano de segurança estabelecido e desenvolvido."]]],"r":["A U.E.L. tem atividades seguras e que garantem a integridade de todos os seus participantes."]}]},{"x":17,"n":"Organização de Eventos e Atividades","l":[{"d":"Identifica os tipos de atividades (fixas e variáveis), apoiando e as compreende como experiências educativas","g":[["Comportamentos desejados",["Participa dos encontros de planejamento de eventos e atividades contribuindo com sugestões.","Apoia a realização dos eventos e atividades das seções e demais estruturas da U.E.L.","Reconhece pontos positivos e negativos durante a execução das atividades realizadas."]],["Atividades de desenvolvimento",["Ler o livro “Os primeiros meses” de de algum dos quatro ramos."]]],"r":["As reuniões e atividades são dinâmicas, animadas e tem o acompanhamento adequado.","As reuniões contam com recursos necessários para sua realização e preparados préviamente.","O padrão de qualidade das atividades da U.E.L. é satisfatório."]},{"d":"Diferencia os cuidados de planejamento entre reuniões semanais e atividades fora da sede","g":[["Comportamentos desejados",["Cuida para que a organização das atividades fora da sede observem todos os passos que garantam sua realização de maneira segura e educativa.","Compreende a importância de estabelecer-se uma programação prévia a realização das atividades.","Sabe quais são os procedimentos de segurança necessários para a realização de atividades dentro e fora da sede."]],["Atividades de desenvolvimento",["Ler o livro Padrões de Acampamento","Ler o livro Fogo de Conselho.","Participar da organização de um evento do Grupo Escoteiro"]]],"r":["As atividades da U.E.L são seguras e tem seu caráter educativo preservado.","As atividades fora da sede são organizadas e com materiais sempre disponíveis e preparados.","As seções contam com o suporte dos dirigentes para a organização de suas atividades."]},{"d":"Orienta os escotistas sobre os tipos de atividade (fixas e variáveis), auxiliando-os garantindo experiências educativas","g":[["Comportamentos desejados",["Junto das equipes competentes avalia o planejamento e execução de atividades dentro e fora da sede, buscando pontos de melhoria para as próximas ativida des.","Orienta as demais equipes sobre a realização de ativ idades variadas, dentro e fora da sede.","Acompanha o planejamento de atividades variadas entendendo a necessidade de estarem relacionadas às ênfases definidas pelas seções."]],["Atividades de desenvolvimento",["Realizar reuniões de avaliação de um evento ou atividade do grupo junto com os diretores e discutir suas impressões sobre as atividades com o APF.","Dar sugestões e propor melhorias para as atividades da UEL e das seções."]]],"r":["Os dirigentes apoiam e colaboram na avaliação de atividades ao ar livre na seção.","Os escotistas recebem orientação para a organização de eventos e atividades.","As atividades fora da sede são organizadas e com materiais sempre disponíveis e preparados."]}]}]}]}};
  var RK = ['lob', 'esc', 'sen', 'pio', 'dir'];
  var NV = ['Preliminar', 'Intermediário', 'Avançado'];
  var ATIV = 'Atividades de desenvolvimento', PPF = 'Inclua no seu PPF';
  var TOT = {};
  RK.forEach(function (r) {
    TOT[r] = [0, 0, 0];
    CAT[r].g.forEach(function (g) { g.c.forEach(function (c) { c.l.forEach(function (l, ni) { l.g.forEach(function (gr) { if (gr[0] === ATIV) TOT[r][ni] += gr[1].length; }); }); }); });
  });
  function totR(r) { return TOT[r][0] + TOT[r][1] + TOT[r][2]; }
  // done: { chave: true } -> { ramo: [n_preliminar, n_intermediario, n_avancado] }
  function contar(done) {
    var c = {}; RK.forEach(function (r) { c[r] = [0, 0, 0]; });
    Object.keys(done || {}).forEach(function (k) {
      if (!done[k]) return; var p = k.split('-');
      if (p[3] === 'p') return;
      if (c[p[0]] && c[p[0]][+p[1]] !== undefined) c[p[0]][+p[1]]++;
    });
    return c;
  }
  return { CAT: CAT, RK: RK, NV: NV, ATIV: ATIV, PPF: PPF, TOT: TOT, totR: totR, contar: contar };
})();
